@app.post("/victor/route")
async def victor_route_query(req: Request):
    """빅터 자연어 → 페이지 후보. 정확 매치 1건이면 redirect URL 반환.
    Body: {q: "견적서 작성"} → JSON.
    """
    u = get_user(req)
    if not u:
        print("[VICTOR-ROUTE] 401 login_required")
        return JSONResponse({"error": "login_required"}, 401)
    try:
        data = await req.json()
        q = (data.get("q") or "").strip()
    except Exception:
        q = ""
    print(f"[VICTOR-ROUTE] 요청 q='{q}' user={u.get('name','?')}")
    if not q:
        return JSONResponse({"ok": False, "msg": "검색어가 비어있습니다."})
    candidates = _menu.search(q, limit=5)
    print(f"[VICTOR-ROUTE] candidates={len(candidates)} → {[c['code'] for c in candidates]}")
    if not candidates:
        from starlette.concurrency import run_in_threadpool
        # v5H226z410 (대표 지시): 키워드 무매치 → ① AI가 카탈로그에서 메뉴 직접 선택(업무순서 추천).
        #   "검사기 등록 어디서?" 같은 자연어를 AI가 이해해 '제작요청 등록부터' 처럼 안내 + 클릭 메뉴 제공.
        try:
            from .victor import ai_pick_menu
            route_res = await run_in_threadpool(ai_pick_menu, u, q)
            if route_res and route_res.get("candidates"):
                print(f"[VICTOR-ROUTE] AI 메뉴 라우팅 → {[c['code'] for c in route_res['candidates']]}")
                return JSONResponse(route_res)
        except Exception as _e:
            print(f"[VICTOR-ROUTE] AI route error: {_e}")
        # v5H226z126: ② 메뉴로도 못 잡으면 AI 텍스트 답변(읽기·안내·작성 보조).
        try:
            from .victor import h_ai_assist
            ai_res = await run_in_threadpool(h_ai_assist, u, db_session, q)
            if ai_res and ai_res.get("text"):
                print("[VICTOR-ROUTE] AI fallback 응답")
                return JSONResponse({"ok": True, "ai": True, "msg": ai_res["text"]})
        except Exception as _e:
            print(f"[VICTOR-ROUTE] AI fallback error: {_e}")
        return JSONResponse({
            "ok": False,
            "msg": f"'{q}' 와 일치하는 메뉴를 찾지 못했습니다. M-XX-YY 코드 또는 메뉴 이름으로 시도해주세요.",
            "candidates": []
        })
    # 단일 매치 → 자동 이동 / 다중 매치 → 후보 표시
    if len(candidates) == 1:
        m = candidates[0]
        return JSONResponse({
            "ok": True,
            "auto_navigate": True,
            "code": m["code"], "label": m["label"], "path": m["path"], "tip": m["tip"]
        })
    return JSONResponse({
        "ok": True,
        "auto_navigate": False,
        "msg": f"'{q}' 후보 {len(candidates)}개 — 클릭하여 이동:",
        "candidates": [
            {"code": m["code"], "label": m["label"], "path": m["path"], "tip": m["tip"]}
            for m in candidates
        ],
    })


@app.get("/api/menu-help")
async def api_menu_help(req: Request, path: str = "", code: str = ""):
    """현재 페이지의 M-코드·라벨·도움말 조회 (❓ 버튼이 호출)."""
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "login_required"}, 401)
    m: dict | None = None
    if code:
        m = _menu.by_code(code)
    elif path:
        m = _menu.by_path(path.split("?")[0])
    if not m:
        return JSONResponse({"ok": False, "msg": "이 화면의 도움말이 아직 등록되지 않았습니다."})
    return JSONResponse({
        "ok": True,
        "code": m["code"], "label": m["label"], "path": m["path"],
        "tip": m["tip"], "persona": m["persona"], "aliases": m["aliases"],
    })


