# Phase 1 — 메뉴 식별번호 헬퍼 (대표 결재 2026-04-29)
# =====================================================
def _current_menu_for(path: str) -> dict | None:
    """현재 URL → 카탈로그 매칭 결과 (없으면 None)."""
    try:
        # 쿼리스트링 제거
        clean = (path or "").split("?")[0]
        return _menu.by_path(clean)
    except Exception:
        return None


# v5H35 (2026-05-02) — 테스트용 가짜 날짜 헬퍼 (세션 기반, 개인별)
def fake_today_iso(request) -> str:
    """세션에 fake_today 가 설정되면 그 값, 아니면 실제 today (ISO)."""
    try:
        if hasattr(request, "session"):
            fk = request.session.get("fake_today")
            if fk:
                return str(fk)
    except Exception:
        pass
    return date.today().isoformat()


def ai_enabled_for(user) -> bool:
    """v5H226z127 (2026-05-31): 이 사용자가 지금 빅터 AI 를 쓸 수 있는가.
    True  → AI 표식 파란색(동작/사용가능)
    False → AI 표식 빨간색(미동작 또는 그 직원은 사용불가)
    판정: ① AI 서비스 가용(키·SDK) ② 로그인 사용자 ③ (선택) users.can_use_ai 플래그.
    can_use_ai 컬럼이 없으면 기본 허용(graceful) — 특정 직원 차단은 플래그로 확장."""
    try:
        from . import ai_client
        if not ai_client.ai_available():
            return False
    except Exception:
        return False
    if not user:
        return False
    try:
        flag = user.get("can_use_ai") if isinstance(user, dict) else None
        if flag is not None:
            return bool(flag)
    except Exception:
        pass
    return True


def ctx(request, name, **kwargs):
    # 사용자 언어 결정
    user = kwargs.get("user")
    lang = "ko"
    if user and isinstance(user, dict):
        lang = user.get("lang") or "ko"
    elif hasattr(request, "session"):
        lang = request.session.get("lang", "ko")

    # 번역 사전 생성
    i = get_all_translations(lang)

    # CX23c v4 마스트헤드 컨텍스트 (대표 승인 2026-04-28)
    _today_d = date.today()
    _wkdays = ['월', '화', '수', '목', '금', '토', '일']
    _today_kor = f"{_today_d.year} · {_today_d.month}월 {_today_d.day}일 {_wkdays[_today_d.weekday()]}요일"
    _edition_no = _today_d.timetuple().tm_yday  # 일년 중 N번째 발행

    # v5H35: 테스트 모드 가짜 날짜 (세션 fake_today 가 설정된 경우만)
    _today_iso = fake_today_iso(request)
    _fake_active = False
    try:
        if hasattr(request, "session"):
            _fake_active = bool(request.session.get("fake_today"))
    except Exception:
        pass

    base = {
        "categories": CATEGORIES,
        "statuses": STATUSES,
        "today": _today_iso,
        "real_today": date.today().isoformat(),
        "fake_date_active": _fake_active,
        "now": datetime.now().strftime("%Y-%m-%d %H:%M"),
        # v5H226z127: AI 사용 가능 여부 → 표식 파랑(True)/빨강(False)
        "ai_on": ai_enabled_for(user),
        "today_kor": _today_kor,            # CX23c 마스트헤드용
        "edition_no": _edition_no,          # CX23c VOL/NO 표시
        "lang": lang,
        "i": i,
        "LANGS": LANGS,
        # HAIST WORKS 브랜드 (통합 후)
        "app_name": "HAIST WORKS",
        "app_subtitle": "KNK 통합 업무 플랫폼",
        "brand_slogan": "Human & AI create the Best",
        # 외부 그룹웨어 URL (admin 설정에서 변경 가능)
        # v5H226z110 (2026-05-30): hiworks_* → groupware_* 키 전환, 하드코딩 제거
        # 구 키 fallback 유지 (마이그레이션 호환)
        "groupware_approval_url": (get_setting("groupware_approval_url", "") or get_setting("hiworks_approval_url", "") or "").strip(),
        "groupware_mail_url":     (get_setting("groupware_mail_url",     "") or get_setting("hiworks_mail_url",     "") or "").strip(),
        "groupware_domain":       (get_setting("groupware_domain",       "") or get_setting("hiworks_domain",       "") or "").strip(),
        # 구 변수명도 임시 유지 (템플릿 호환, 추후 deprecate)
        "hiworks_approval_url": (get_setting("groupware_approval_url", "") or get_setting("hiworks_approval_url", "") or "").strip(),
        "hiworks_mail_url":     (get_setting("groupware_mail_url",     "") or get_setting("hiworks_mail_url",     "") or "").strip(),
        "hiworks_domain":       (get_setting("groupware_domain",       "") or get_setting("hiworks_domain",       "") or "").strip(),
        # Victor 도크 맥락 칩 (제안 #08)
        "victor_chips":         _victor_chips_for_path(str(request.url.path) if hasattr(request, "url") else ""),
        # C안 v2 §2-4 — 워크스페이스 스위처 (uppercase + lowercase 양쪽 노출)
        "workspaces":          workspaces_for(user) if user else [],
        "current_workspace":   current_workspace_for(str(request.url.path) if hasattr(request, "url") else ""),
        "WORKSPACES":          workspaces_for(user) if user else [],
        # Phase 1 (대표 결재 2026-04-29): 메뉴 식별번호 — 현재 페이지 M-코드 + 도움말
        "current_menu":        _current_menu_for(str(request.url.path) if hasattr(request, "url") else ""),
        # v5H208: 공휴일 데이터를 context 로도 직접 전달 (globals 미적용 환경 안전망)
        "KNK_HOLIDAYS_KR":     HOLIDAYS_KR,
        "KNK_HOLIDAYS_VN":     HOLIDAYS_VN,
    }
    # 글로벌 알림 카운트 (로그인 상태일 때만)
    uid = request.session.get("user_id") if hasattr(request, "session") else None
    if uid:
        try:
            base["unread_notif"] = count_unread(uid)
        except Exception:
            base["unread_notif"] = 0
    else:
        base["unread_notif"] = 0
    # v5H72: 권한 헬퍼 — 템플릿에서 사용
    base["can_sales"]      = can_use_sales(user) if user else False
    base["can_sales_del"]  = can_delete_sales(user) if user else False  # 삭제 전용 (더 엄격)
    base["can_logi"]       = can_use_logistics(user) if user else False
    base["is_admin"]       = bool(user and user.get("role") in ("admin", "ceo"))
    # v5H226z823 (대표 결정 2026-07-05): 민감정보 열람권한 2단계 — 3분류 전역(요청당 정책 1회 로드).
    #   ceo·admin·executive(임원)는 can_view_field 에서 항상 True. leader·일반직원은 팀 정책(field_access_policy).
    #   정책 로드 실패=빈 dict → 비관리자 False(누출 없음·안전). 이번 2.1 은 can_sales_amt 만 화면에 연결하고,
    #   can_purchase_price·can_supplier 는 정의만(2.2 구매단가·2.3 구매처에서 연결).
    try:
        with db_session() as _facc:
            _fa_pol = load_field_access_policy(_facc)
    except Exception:
        _fa_pol = {}
    base["can_sales_amt"]      = can_view_field(user, "sales_amount", _fa_pol) if user else False
    base["can_purchase_price"] = can_view_field(user, "purchase_price", _fa_pol) if user else False
    base["can_supplier"]       = can_view_field(user, "supplier_info", _fa_pol) if user else False
    # 메일 '앱(독립 창)' 모드 — KNK Eum 등에서 ?app=1 로 별도 창 실행 시 사이드바 없이 메일만.
    # 세션 보존(이후 내부 이동도 유지) · ?app=0 으로 해제(WORKS 전체화면 복귀).
    _mail_app = False
    try:
        if hasattr(request, "session"):
            _ap = request.query_params.get("app") if hasattr(request, "query_params") else None
            if _ap == "1":
                request.session["mail_app"] = True
            elif _ap == "0":
                request.session["mail_app"] = False
            _mail_app = bool(request.session.get("mail_app"))
    except Exception:
        _mail_app = False
    base["mail_app"] = _mail_app
    # v5H226z706 (대표 지시·정책): 전 화면 고객사 표시는 '시스템명(alias)' 우선 — 공용 맵 주입(customer_id→시스템명).
    #   템플릿 패턴: {{ (cust_alias|default({},true)).get(x.customer_id) or x.customer_name }} (없으면 정식명 폴백·안전).
    #   정식명(매칭·세금계산서/인보이스/견적 등 발행문서)은 그대로 customer_name 사용.
    try:
        with db_session() as _ca_c:
            base["cust_alias"] = {r[0]: r[1] for r in _ca_c.execute(
                "SELECT id, alias FROM customers WHERE COALESCE(alias,'')<>''")}
    except Exception:
        base["cust_alias"] = {}
    base.update(kwargs)
    # v5H178b: HTML 페이지는 캐시 금지 — 인라인 편집 후 다른 탭/뒤로가기에서 stale 데이터 방지
    resp = tpl.TemplateResponse(request=request, name=name, context=base)
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    resp.headers["Pragma"] = "no-cache"
    resp.headers["Expires"] = "0"
    return resp


def get_user(req: Request):
    uid = req.session.get("user_id")
    if not uid:
        return None
    with db_session() as c:
        row = c.execute(
            """SELECT u.*, t.name AS team_name, t.code AS team_code, t.is_lab AS team_is_lab,
                      t.sector AS team_sector
               FROM users u LEFT JOIN teams t ON u.team_id=t.id
               WHERE u.id=? AND u.is_active=1""",
            (uid,),
        ).fetchone()
        if not row:
            return None
        # v5H226z122 (2026-05-31): 멀티탭 효율 우선 — 세션 유지 정책.
        # 토큰 유효(1시간) 동안만 pwv 동기화. 토큰 만료/무효 시에는 WORKS 세션을
        # 파기하지 않고(14일 쿠키 유지) 죽은 토큰만 제거해 재확인을 멈춘다.
        #  → 새 탭/새 창을 열어도 로그인으로 튕기지 않음 (대표 지시 2026-05-31).
        #  ※ 트레이드오프: 메신저 비번변경 '즉시 로그아웃'은 토큰 유효구간(1h)에만 보장.
        #    그 이후엔 메신저 재진입(토큰 갱신)·쿠키만료·수동 로그아웃 시 반영.
        try:
            token = req.session.get("sso_token")
            if token:
                from .sso_client import should_check_pwv, mark_pwv_checked, fetch_userinfo
                if should_check_pwv(uid):
                    info = fetch_userinfo(token)
                    if info and info.get("_invalid"):
                        # 토큰 만료/무효 → 세션은 유지, 죽은 토큰만 제거 (재확인 중단)
                        req.session.pop("sso_token", None)
                        req.session.pop("sso_pwv", None)
                    else:
                        mark_pwv_checked(uid)
        except Exception:
            # 동기화 실패(메신저 일시 장애 등)해도 기존 세션은 유지 (graceful)
            pass
        return dict(row)


def require(req: Request, roles=None):
    u = get_user(req)
    if not u:
        return None
    if roles and u["role"] not in roles:
        return None
    return u


def role_home(user) -> str:
    """ESC-02 (감사보고_04 2026-04-22): role별 홈 URL 반환.
    require() 실패 + 로그인 상태인 경우 /login 대신 적절한 홈으로 리다이렉트.
    - ceo/admin/executive → /dashboard
    - leader → /team
    - member/그 외 → /home
    """
    if not user:
        return "/login"
    role = (user.get("role") or "member") if isinstance(user, dict) else str(user["role"])
    if role in ("ceo", "admin", "executive"):
        return "/dashboard"
    elif role == "leader":
        return "/team"
    else:
        return "/home"


def can_use_logistics(user) -> bool:
    """HAIST WORKS 물류 모듈 접근 권한.
    - admin / ceo / executive: 항상 허용
    - team_id == 7 (제조팀): 읽기 허용 (2026-04-22 대표 결재 D01-02 안B)
    - 그 외: users.can_use_logistics 플래그가 1일 때만
    """
    if not user:
        return False
    role = user.get("role") if isinstance(user, dict) else user["role"]
    if role in ("admin", "ceo", "executive"):
        return True
    # 제조팀(team_id=7) 읽기 허용 — 쓰기·발주·단가수정은 구매팀 권한 그대로 유지
    team_id = user.get("team_id") if isinstance(user, dict) else user["team_id"]
    if team_id == 7:
        return True
    flag = user.get("can_use_logistics") if isinstance(user, dict) else user["can_use_logistics"]
    return bool(flag)


def can_view_sales(user) -> bool:
    """매출·영업 **읽기 전용** 권한 (2026-04-28 대표 결재 — R/W 분리).
    - admin / ceo / executive / leader: 항상 허용 (전사 매출 현황 조회)
    - team_id 1·2·3 (영업·검사기·품질): 항상 허용
    - 그 외: users.can_view_sales 플래그 1
    - 쓰기 권한자(can_use_sales=1)는 자동 포함
    """
    if not user:
        return False
    role = user.get("role") if isinstance(user, dict) else user["role"]
    if role in ("admin", "ceo", "executive", "leader"):
        return True
    team_id = user.get("team_id") if isinstance(user, dict) else user["team_id"]
    if team_id in (1, 2, 3):
        return True
    try:
        if user.get("can_view_sales") or user.get("can_use_sales"):
            return True
    except (KeyError, IndexError):
        pass
    return False


def can_view_logistics(user) -> bool:
    """자재·구매 **읽기 전용** 권한 (2026-04-28 대표 결재 — R/W 분리).
    실무자가 부품·재고·단가·구매사를 조회해야 할 때 폭넓게 허용.
    - admin / ceo / executive / leader: 항상 허용
    - team_id 1,2,3,7,8,9,10 (영업·검사기·품질·생산1·생산2·가공·구매): 항상 허용
    - 그 외: users.can_view_logistics 플래그 1
    - 쓰기 권한자(can_use_logistics=1)는 자동 포함
    """
    if not user:
        return False
    role = user.get("role") if isinstance(user, dict) else user["role"]
    if role in ("admin", "ceo", "executive", "leader"):
        return True
    team_id = user.get("team_id") if isinstance(user, dict) else user["team_id"]
    if team_id in (1, 2, 3, 7, 8, 9, 10):
        return True
    try:
        if user.get("can_view_logistics") or user.get("can_use_logistics"):
            return True
    except (KeyError, IndexError):
        pass
    return False


def can_delete_sales(user) -> bool:
    """v5H72: 매출·영업 **삭제** 권한 — can_use_sales 보다 더 엄격.
    - admin / ceo / executive: 자동 허용
    - 기술영업팀(team_id=1) 팀장(leader): 자동 허용
    - 기타 멤버: users.can_use_sales=1 명시적으로 부여 받은 자만
    대표 정의: '기술영업팀에서 등록 권한을 받은 사용자만'."""
    if not user:
        return False
    role = (user.get("role") if isinstance(user, dict) else user["role"]) or ""
    if role in ("admin", "ceo", "executive"):
        return True
    team_id = user.get("team_id") if isinstance(user, dict) else None
    if role == "leader" and team_id == 1:
        return True
    # member 는 명시적 위임 받은 자만
    try:
        return bool(user.get("can_use_sales"))
    except Exception:
        return False


# =====================================================
# v5H226z822 (대표 지시): 정보 열람 권한 — 팀별 정책 헬퍼 (1단계=정의만·화면 미연결)
# =====================================================
# 민감 정보 3분류를 팀별로 다르게 열람 제어. 정책은 DB표 field_access_policy(행 1개=그 팀이 그 분류 열람 가능).
#   대표/관리자(ceo·admin)는 정책과 무관하게 항상 전체 열람(시스템 관리자·잠금 방지).
# ⚠ 이 헬퍼는 이번 1단계에서 어떤 화면에도 연결하지 않는다(정의만). 2단계에서 화면별로 적용.
FIELD_ACCESS_LABELS = {
    "sales_amount":   "매출금액",
    "purchase_price": "구매단가",
    "supplier_info":  "구매처 정보",
}


def load_field_access_policy(c) -> dict:
    """field_access_policy 표 → {category: set(team_id)}. 표가 없으면 빈 dict(안전).
    2단계에서 요청당 1회 로드해 can_view_field(policy=...) 로 넘겨 재조회를 피할 수 있게 한다."""
    policy: dict = {}
    try:
        for r in c.execute("SELECT category, team_id FROM field_access_policy"):
            cat = r["category"] if not isinstance(r, tuple) else r[0]
            tid = r["team_id"] if not isinstance(r, tuple) else r[1]
            policy.setdefault(cat, set()).add(tid)
    except Exception:
        return {}
    return policy


def can_view_field(user, category, policy=None) -> bool:
    """민감 정보 분류(category) 열람 가능 여부.
    - user 없으면 False.
    - role 이 ceo·admin·executive(임원) 이면 True(시스템 관리자·경영진·잠금 방지·정책 무관).
      (대표 결정 2026-07-05: 임원은 전 분류 항상 전체 열람. leader·일반직원은 팀 정책.)
    - 그 외: user 의 team_id 가 그 category 허용팀에 있으면 True(정책 기반).
    - policy(=load_field_access_policy 결과) 를 주면 그것을 사용, 없으면 그때 1회 조회.
    2단계-2.1(v5H226z823)에서 sales_amount 를 화면(수주상세·작업일정표·프로젝트 매출 KPI)에 연결."""
    if not user:
        return False
    role = (user.get("role") if isinstance(user, dict) else user["role"]) or ""
    if role in ("ceo", "admin", "executive"):
        return True
    team_id = user.get("team_id") if isinstance(user, dict) else None
    if team_id is None:
        return False
    if policy is None:
        try:
            with db_session() as _c:
                policy = load_field_access_policy(_c)
        except Exception:
            return False
    allowed = policy.get(category) or set()
    return team_id in allowed


def can_view_work_patterns(user) -> bool:
    """직원 업무 패턴(추적·매뉴얼화) 열람 권한.
    v5H226z411 (대표 지시 2026-06-14): 지금은 **김정락 대표 한 명만**(사번 5 / login_id 'kjr').
    향후 확대 예정: 대표·관리자 + 팀장(자기 팀) + 본인 → 이 함수 한 곳만 고치면 됨.
    ※ ceo 계정이 둘(김동후 포함)이라 role 로 막지 않고 본인만 정확히 지정한다."""
    if not user:
        return False
    try:
        empno = str((user.get("employee_no") if isinstance(user, dict) else "") or "").strip()
        login = str((user.get("login_id") if isinstance(user, dict) else "") or "").strip().lower()
    except Exception:
        return False
    return empno == "5" or login == "kjr"


def _wp_period(request):
    """업무 패턴 기간 파라미터 → (start_iso, end_iso, label, days). 기본 최근 30일."""
    try:
        days = int((request.query_params.get("days") or "30").strip())
    except Exception:
        days = 30
    days = max(1, min(days, 366))
    end = date.today()
    start = end - timedelta(days=days - 1)
    label = {30: "최근 30일", 90: "최근 90일", 365: "최근 1년"}.get(days, f"최근 {days}일")
    return start.isoformat(), end.isoformat(), label, days


@app.get("/admin/work-patterns", response_class=HTMLResponse)
async def admin_work_patterns(request: Request):
    """v5H226z411 (대표 지시): 직원 업무 패턴 — 한 일 모아보기 (1단계: 일일업무 기준).
    업무분장·인수인계·개인 매뉴얼용 기초자료. 열람=김정락 대표 전용(can_view_work_patterns)."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_work_patterns(u):
        return RedirectResponse(role_home(u), 303)
    start, end, plabel, days = _wp_period(request)
    from collections import defaultdict
    with db_session() as c:
        # 일일업무(tasks) 집계
        task_map = {r["uid"]: dict(r) for r in c.execute(
            """SELECT t.user_id AS uid, COUNT(*) AS cnt, COALESCE(SUM(t.hours),0) AS hours,
                      SUM(CASE WHEN t.status='완료' THEN 1 ELSE 0 END) AS done,
                      SUM(CASE WHEN t.status='지연' THEN 1 ELSE 0 END) AS delayed
               FROM tasks t WHERE t.work_date BETWEEN ? AND ? GROUP BY t.user_id""",
            (start, end)).fetchall()}
        catrows = c.execute(
            """SELECT t.user_id AS uid, t.category AS cat, COUNT(*) AS n FROM tasks t
               WHERE t.work_date BETWEEN ? AND ? AND COALESCE(t.category,'')<>''
               GROUP BY t.user_id, t.category""", (start, end)).fetchall()
        # v5H226z412 (2단계): 종합 신호 — 티켓(처리)·이슈(담당)·공정(담당). 테이블/컬럼 없으면 graceful.
        tkt_map, iss_map, pha_map = {}, {}, {}
        try:
            for r in c.execute("SELECT recipient_user_id AS uid, COUNT(*) AS n FROM tickets "
                               "WHERE recipient_user_id IS NOT NULL AND date(COALESCE(created_at,'')) BETWEEN ? AND ? "
                               "GROUP BY recipient_user_id", (start, end)):
                tkt_map[r["uid"]] = r["n"]
        except Exception:
            pass
        try:
            for r in c.execute("SELECT owner_user_id AS uid, COUNT(*) AS n FROM issues "
                               "WHERE owner_user_id IS NOT NULL AND date(COALESCE(created_at,'')) BETWEEN ? AND ? "
                               "GROUP BY owner_user_id", (start, end)):
                iss_map[r["uid"]] = r["n"]
        except Exception:
            pass
        try:
            for r in c.execute("SELECT assignee_id AS uid, COUNT(*) AS n FROM project_phases "
                               "WHERE assignee_id IS NOT NULL AND date(COALESCE(updated_at,'')) BETWEEN ? AND ? "
                               "GROUP BY assignee_id", (start, end)):
                pha_map[r["uid"]] = r["n"]
        except Exception:
            pass
        # v5H226z571 (대표 지시): '단계' 시스템 완전 제거 — 부서 작업 추적은 부서일정표로 일원화(아래 dsx_map).
        # v5H226z499 (대표 지시·Phase 3): 부서 일정표 기록(dept_schedule_log) — created_by 기준 건수. 작성일(log_date) 기준.
        dsx_map = {}
        try:
            for r in c.execute(
                "SELECT created_by AS uid, COUNT(*) AS n, COALESCE(SUM(hours),0) AS h FROM dept_schedule_log "
                "WHERE created_by IS NOT NULL AND date(log_date) BETWEEN ? AND ? GROUP BY created_by",
                    (start, end)):
                if r["uid"]:
                    dsx_map[r["uid"]] = {"n": r["n"], "h": round(float(r["h"] or 0), 1)}   # v5H226z570: 시간 추가
        except Exception:
            pass
        # v5H226z414 (Phase2): 메일(WORKS mail_messages) 집계 — user_id 기준
        mail_map = {}
        try:
            for r in c.execute(
                "SELECT user_id AS uid, COUNT(*) AS total FROM mail_messages "
                "WHERE COALESCE(is_deleted,0)=0 AND date(COALESCE(received_at, created_at, '')) BETWEEN ? AND ? "
                "GROUP BY user_id", (start, end)):
                if r["uid"]:
                    mail_map[r["uid"]] = r["total"]
        except Exception:
            pass
        # v5H226z421 3단계 (대표 지시): 수주 전 부서 활동(opp_request_activities) 합산 — user_id 기준
        presale_map = {}
        try:
            for r in c.execute(
                "SELECT user_id AS uid, COUNT(*) AS n, COALESCE(SUM(hours),0) AS h "
                "FROM opp_request_activities WHERE date(act_date) BETWEEN ? AND ? GROUP BY user_id",
                (start, end)):
                if r["uid"]:
                    presale_map[r["uid"]] = {"n": r["n"], "h": round(float(r["h"] or 0), 1)}
        except Exception:
            pass
        # 메일·메신저 전용 활동자도 포함하려고 '전 활성 사용자' 기준 + 사번(employee_no)
        try:
            urows = c.execute(
                "SELECT u.id, u.name, COALESCE(tm.name,'(부서없음)') AS team_name, COALESCE(u.employee_no,'') AS empno "
                "FROM users u LEFT JOIN teams tm ON tm.id=u.team_id WHERE COALESCE(u.is_active,1)=1").fetchall()
        except Exception:
            urows = c.execute(
                "SELECT u.id, u.name, COALESCE(tm.name,'(부서없음)') AS team_name, '' AS empno "
                "FROM users u LEFT JOIN teams tm ON tm.id=u.team_id WHERE COALESCE(u.is_active,1)=1").fetchall()
        umap = {r["id"]: dict(r) for r in urows}
    # 메신저(별도 DB 읽기전용·z143 승인 방식) — 사번별 메시지 수. with 밖(별도 연결).
    msgr_map = _wp_messenger_map(start, end)
    catmap = defaultdict(list)
    for r in catrows:
        catmap[r["uid"]].append((r["n"], r["cat"]))
    rows = []
    for uid, uinfo in umap.items():
        t = task_map.get(uid, {})
        cnt = t.get("cnt", 0) or 0
        done = t.get("done", 0) or 0
        cats = sorted(catmap.get(uid, []), reverse=True)
        tickets = tkt_map.get(uid, 0); issues = iss_map.get(uid, 0); phases = pha_map.get(uid, 0)
        mail = mail_map.get(uid, 0)
        empno = str(uinfo.get("empno") or "")
        msgr = ((msgr_map.get(empno) or {}).get("msgs", 0)) if empno else 0
        pre = presale_map.get(uid, {})
        presales = pre.get("n", 0); presales_h = pre.get("h", 0)
        _dsxd = dsx_map.get(uid, {})   # v5H226z499/z570 (Phase3): 부서 일정표 기록 수 + 시간(h)
        dsx = _dsxd.get("n", 0); dsx_h = _dsxd.get("h", 0)
        activity = cnt + tickets + issues + phases + mail + msgr + presales + dsx
        if activity <= 0:
            continue
        rows.append({
            "user_id": uid, "name": uinfo["name"], "team_name": uinfo["team_name"],
            "cnt": cnt, "hours": round(t.get("hours", 0) or 0, 1),
            "done": done, "delayed": t.get("delayed", 0) or 0,
            "rate": round(100 * done / cnt) if cnt else 0,
            "top_cats": ", ".join(cc for _, cc in cats[:2]) or "—",
            "tickets": tickets, "issues": issues, "phases": phases,
            "mail": mail, "msgr": msgr,
            "presales": presales, "presales_h": presales_h,
            "dsx": dsx, "dsx_h": dsx_h,   # v5H226z499/z570 (Phase3): 부서 일정표 기록 수 + 시간(h)
            "activity": activity,
        })
    rows.sort(key=lambda x: -x["activity"])
    depts = {}
    for r in rows:
        d = depts.setdefault(r["team_name"], {"team_name": r["team_name"], "people": 0, "cnt": 0,
                                              "hours": 0.0, "done": 0, "delayed": 0,
                                              "tickets": 0, "issues": 0, "phases": 0, "mail": 0, "msgr": 0,
                                              "presales": 0, "presales_h": 0.0,
                                              "dsx": 0, "dsx_h": 0.0})
        d["people"] += 1; d["cnt"] += r["cnt"]; d["hours"] += r["hours"]; d["done"] += r["done"]
        d["delayed"] += r["delayed"]; d["tickets"] += r["tickets"]; d["issues"] += r["issues"]; d["phases"] += r["phases"]
        d["mail"] += r["mail"]; d["msgr"] += r["msgr"]
        d["presales"] += r["presales"]; d["presales_h"] += r["presales_h"]
        d["dsx"] += r["dsx"]; d["dsx_h"] += r["dsx_h"]
    dept_list = sorted(depts.values(), key=lambda x: -(x["cnt"] + x["tickets"] + x["issues"] + x["phases"] + x["mail"] + x["msgr"] + x["presales"] + x["dsx"]))
    for d in dept_list:
        d["rate"] = round(100 * d["done"] / d["cnt"]) if d["cnt"] else 0
        d["hours"] = round(d["hours"], 1)
        d["presales_h"] = round(d["presales_h"], 1)
        d["dsx_h"] = round(d["dsx_h"], 1)        # v5H226z570: 부서 일정표 시간 합계
    return ctx(request, "admin_work_patterns.html", user=u, rows=rows, depts=dept_list,
               period_label=plabel, days=days, start=start, end=end, total_people=len(rows))


def _wp_detail_data(c, uid, start, end):
    """개인 업무 패턴 집계(detail·ai 공용). 메타데이터만(notes 본문 미포함)."""
    cats = [dict(r) for r in c.execute(
        "SELECT COALESCE(NULLIF(category,''),'(미분류)') AS category, COUNT(*) AS n, COALESCE(SUM(hours),0) AS h "
        "FROM tasks WHERE work_date BETWEEN ? AND ? AND user_id=? GROUP BY category ORDER BY n DESC",
        (start, end, uid))]
    stat = [dict(r) for r in c.execute(
        "SELECT COALESCE(NULLIF(status,''),'(미지정)') AS status, COUNT(*) AS n "
        "FROM tasks WHERE work_date BETWEEN ? AND ? AND user_id=? GROUP BY status ORDER BY n DESC",
        (start, end, uid))]
    weekly = [dict(r) for r in c.execute(
        "SELECT strftime('%Y-%W', work_date) AS wk, COUNT(*) AS n, COALESCE(SUM(hours),0) AS h "
        "FROM tasks WHERE work_date BETWEEN ? AND ? AND user_id=? GROUP BY wk ORDER BY wk",
        (start, end, uid))]
    projs = [dict(r) for r in c.execute(
        "SELECT project_label AS label, COUNT(*) AS n FROM tasks "
        "WHERE work_date BETWEEN ? AND ? AND user_id=? AND COALESCE(project_label,'')<>'' "
        "GROUP BY project_label ORDER BY n DESC LIMIT 8", (start, end, uid))]
    custs = [dict(r) for r in c.execute(
        "SELECT customer_label AS label, COUNT(*) AS n FROM tasks "
        "WHERE work_date BETWEEN ? AND ? AND user_id=? AND COALESCE(customer_label,'')<>'' "
        "GROUP BY customer_label ORDER BY n DESC LIMIT 8", (start, end, uid))]
    return cats, stat, weekly, projs, custs


def _wp_detail_extra(c, uid, start, end):
    """v5H226z412 (2단계): 종합 신호 상세 — 티켓(처리/요청)·이슈(담당)·공정(담당).
    테이블/컬럼 없으면 빈 구조로 graceful."""
    out = {"tkt_recv": [], "tkt_recv_n": 0, "tkt_sent_n": 0, "issues": [], "issues_n": 0, "phases": [], "phases_n": 0}
    try:
        out["tkt_recv"] = [dict(r) for r in c.execute(
            "SELECT COALESCE(NULLIF(category,''),'(미분류)') AS category, COUNT(*) AS n, "
            "SUM(CASE WHEN status='완료' THEN 1 ELSE 0 END) AS done FROM tickets "
            "WHERE recipient_user_id=? AND date(COALESCE(created_at,'')) BETWEEN ? AND ? "
            "GROUP BY category ORDER BY n DESC", (uid, start, end))]
        out["tkt_recv_n"] = sum(x["n"] for x in out["tkt_recv"])
        out["tkt_sent_n"] = c.execute(
            "SELECT COUNT(*) FROM tickets WHERE requester_id=? AND date(COALESCE(created_at,'')) BETWEEN ? AND ?",
            (uid, start, end)).fetchone()[0]
    except Exception:
        pass
    try:
        out["issues"] = [dict(r) for r in c.execute(
            "SELECT COALESCE(NULLIF(severity,''),'(미지정)') AS severity, COUNT(*) AS n FROM issues "
            "WHERE owner_user_id=? AND date(COALESCE(created_at,'')) BETWEEN ? AND ? "
            "GROUP BY severity ORDER BY n DESC", (uid, start, end))]
        out["issues_n"] = sum(x["n"] for x in out["issues"])
    except Exception:
        pass
    try:
        out["phases"] = [dict(r) for r in c.execute(
            "SELECT COALESCE(NULLIF(status,''),'(미지정)') AS status, COUNT(*) AS n FROM project_phases "
            "WHERE assignee_id=? AND date(COALESCE(updated_at,'')) BETWEEN ? AND ? "
            "GROUP BY status ORDER BY n DESC", (uid, start, end))]
        out["phases_n"] = sum(x["n"] for x in out["phases"])
    except Exception:
        pass
    return out


# v5H226z414 (Phase 2, 대표 지시): Eum 메신저·메일 활동 통합 — 더 완전한 패턴.
#   메신저는 별도 앱이지만 같은 컨테이너 → DB 읽기전용 집계(z143 대표 승인 방식). 메신저 앱은 안 건드림.
#   메타데이터만(메시지 '건수'·방·멘션). 본문 미수집.
def _wp_open_messenger_ro():
    """메신저 DB 읽기전용 연결 (없으면 None)."""
    try:
        from . import sso_client
        import os, sqlite3 as _sq
        path = sso_client.MESSENGER_DB_PATH
        if not path or not os.path.exists(path):
            return None
        conn = _sq.connect(f"file:{path}?mode=ro", uri=True)
        conn.row_factory = _sq.Row
        return conn
    except Exception as e:
        print(f"[WP messenger] open: {e}")
        return None


def _wp_messenger_map(start, end):
    """사번별 메신저 메시지 집계 {emp: {msgs, rooms}} (시스템 메시지 제외). DB 없으면 {}."""
    conn = _wp_open_messenger_ro()
    if conn is None:
        return {}
    out = {}
    try:
        for r in conn.execute(
            "SELECT COALESCE(NULLIF(u.employee_no,''), u.username) AS emp, COUNT(*) AS msgs, "
            "COUNT(DISTINCT m.room_id) AS rooms FROM messages m JOIN users u ON u.id=m.user_id "
            "WHERE COALESCE(m.kind,'text')<>'system' AND date(m.created_at) BETWEEN ? AND ? "
            "AND COALESCE(u.is_guest,0)=0 GROUP BY emp", (start, end)):
            if r["emp"]:
                out[str(r["emp"])] = {"msgs": r["msgs"], "rooms": r["rooms"]}
    except Exception as e:
        print(f"[WP messenger] map: {e}")
    finally:
        conn.close()
    return out


def _wp_messenger_detail(empno, start, end):
    """개인 메신저 상세 {msgs, rooms, mentions, top_rooms:[{name,n}]} (사번 기준). 본문 미수집."""
    out = {"msgs": 0, "rooms": 0, "mentions": 0, "top_rooms": []}
    empno = str(empno or "").strip()
    if not empno:
        return out
    conn = _wp_open_messenger_ro()
    if conn is None:
        return out
    try:
        uid_rows = conn.execute(
            "SELECT id FROM users WHERE COALESCE(NULLIF(employee_no,''), username)=?", (empno,)).fetchall()
        mids = [x["id"] for x in uid_rows]
        if not mids:
            return out
        qm = ",".join("?" * len(mids))
        r = conn.execute(
            f"SELECT COUNT(*) AS msgs, COUNT(DISTINCT room_id) AS rooms FROM messages "
            f"WHERE user_id IN ({qm}) AND COALESCE(kind,'text')<>'system' AND date(created_at) BETWEEN ? AND ?",
            mids + [start, end]).fetchone()
        out["msgs"] = r["msgs"] or 0
        out["rooms"] = r["rooms"] or 0
        try:
            mn = conn.execute(
                f"SELECT COUNT(*) AS n FROM mentions WHERE mentioned_user_id IN ({qm}) "
                f"AND date(created_at) BETWEEN ? AND ?", mids + [start, end]).fetchone()
            out["mentions"] = mn["n"] or 0
        except Exception:
            pass
        try:
            out["top_rooms"] = [
                {"name": (x["name"] or f"방#{x['room_id']}"), "n": x["n"]}
                for x in conn.execute(
                    f"SELECT m.room_id, rm.name AS name, COUNT(*) AS n FROM messages m "
                    f"LEFT JOIN rooms rm ON rm.id=m.room_id "
                    f"WHERE m.user_id IN ({qm}) AND COALESCE(m.kind,'text')<>'system' "
                    f"AND date(m.created_at) BETWEEN ? AND ? GROUP BY m.room_id ORDER BY n DESC LIMIT 6",
                    mids + [start, end])]
        except Exception:
            pass
    except Exception as e:
        print(f"[WP messenger] detail: {e}")
    finally:
        conn.close()
    return out


def _wp_mail_detail(c, uid, start, end):
    """개인 메일 상세 {sent, recv, total, cats:[], corr:[]} (WORKS mail_messages). 본문 미수집."""
    out = {"sent": 0, "recv": 0, "total": 0, "cats": [], "corr": []}
    try:
        for r in c.execute(
            "SELECT COALESCE(NULLIF(direction,''),'?') AS d, COUNT(*) AS n FROM mail_messages "
            "WHERE user_id=? AND COALESCE(is_deleted,0)=0 AND date(COALESCE(received_at, created_at,'')) BETWEEN ? AND ? "
            "GROUP BY direction", (uid, start, end)):
            out["total"] += r["n"]
            if str(r["d"]).lower() in ("out", "sent", "발신", "outbound", "send"):
                out["sent"] += r["n"]
            elif str(r["d"]).lower() in ("in", "received", "수신", "inbound", "recv"):
                out["recv"] += r["n"]
        out["cats"] = [dict(r) for r in c.execute(
            "SELECT COALESCE(NULLIF(category,''),'(미분류)') AS category, COUNT(*) AS n FROM mail_messages "
            "WHERE user_id=? AND COALESCE(is_deleted,0)=0 AND date(COALESCE(received_at, created_at,'')) BETWEEN ? AND ? "
            "GROUP BY category ORDER BY n DESC LIMIT 6", (uid, start, end))]
        out["corr"] = [dict(r) for r in c.execute(
            "SELECT CASE WHEN LOWER(COALESCE(direction,'')) IN ('out','sent','발신','outbound','send') "
            "THEN to_email ELSE from_email END AS addr, COUNT(*) AS n FROM mail_messages "
            "WHERE user_id=? AND COALESCE(is_deleted,0)=0 AND date(COALESCE(received_at, created_at,'')) BETWEEN ? AND ? "
            "AND COALESCE(CASE WHEN LOWER(COALESCE(direction,'')) IN ('out','sent','발신','outbound','send') THEN to_email ELSE from_email END,'')<>'' "
            "GROUP BY addr ORDER BY n DESC LIMIT 6", (uid, start, end))]
    except Exception as e:
        print(f"[WP mail] detail: {e}")
    return out


def _wp_presales_detail(c, uid, start, end):
    """v5H226z421 3단계: 개인 '수주 전 부서 활동' 상세 {total_h, total_n, by_type:[], reqs:[]}."""
    out = {"total_h": 0.0, "total_n": 0, "by_type": [], "reqs": []}
    try:
        out["by_type"] = [dict(r) for r in c.execute(
            "SELECT COALESCE(NULLIF(activity_type,''),'기타') AS activity_type, COUNT(*) AS n, "
            "ROUND(COALESCE(SUM(hours),0),1) AS h FROM opp_request_activities "
            "WHERE user_id=? AND date(act_date) BETWEEN ? AND ? GROUP BY activity_type ORDER BY h DESC",
            (uid, start, end))]
        out["total_n"] = sum(x["n"] for x in out["by_type"])
        out["total_h"] = round(sum(x["h"] for x in out["by_type"]), 1)
        out["reqs"] = [dict(r) for r in c.execute(
            "SELECT t.name AS team_name, o.opp_no AS opp_no, COALESCE(o.title, dr.title) AS title, "
            "ROUND(COALESCE(SUM(a.hours),0),1) AS h, COUNT(*) AS n "
            "FROM opp_request_activities a JOIN opp_dept_requests dr ON dr.id=a.request_id "
            "LEFT JOIN teams t ON t.id=dr.team_id LEFT JOIN sales_opportunities o ON o.id=dr.opp_id "
            "WHERE a.user_id=? AND date(a.act_date) BETWEEN ? AND ? "
            "GROUP BY a.request_id ORDER BY h DESC LIMIT 8", (uid, start, end))]
    except Exception as e:
        print(f"[WP presales] detail: {e}")
    return out


@app.get("/admin/work-patterns/{uid:int}", response_class=HTMLResponse)
async def admin_work_pattern_detail(request: Request, uid: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_work_patterns(u):
        return RedirectResponse(role_home(u), 303)
    start, end, plabel, days = _wp_period(request)
    with db_session() as c:
        try:
            emp = c.execute(
                "SELECT u.id, u.name, u.role, u.rank, COALESCE(u.employee_no,'') AS empno, COALESCE(tm.name,'') AS team_name "
                "FROM users u LEFT JOIN teams tm ON tm.id=u.team_id WHERE u.id=?", (uid,)).fetchone()
        except Exception:
            emp = c.execute(
                "SELECT u.id, u.name, u.role, u.rank, '' AS empno, COALESCE(tm.name,'') AS team_name "
                "FROM users u LEFT JOIN teams tm ON tm.id=u.team_id WHERE u.id=?", (uid,)).fetchone()
        if not emp:
            return RedirectResponse("/admin/work-patterns", 303)
        emp = dict(emp)
        cats, stat, weekly, projs, custs = _wp_detail_data(c, uid, start, end)
        # 협업 대상: 내 업무에 댓글 단 사람 + 내가 댓글 단 남의 업무 (task_comments 기준)
        collab = {}
        try:
            for r in c.execute(
                "SELECT tc.author_id AS pid, COUNT(*) AS n FROM task_comments tc JOIN tasks t ON t.id=tc.task_id "
                "WHERE t.user_id=? AND tc.author_id<>? AND date(tc.created_at) BETWEEN ? AND ? GROUP BY tc.author_id",
                (uid, uid, start, end)):
                collab[r["pid"]] = collab.get(r["pid"], 0) + r["n"]
            for r in c.execute(
                "SELECT t.user_id AS pid, COUNT(*) AS n FROM task_comments tc JOIN tasks t ON t.id=tc.task_id "
                "WHERE tc.author_id=? AND t.user_id<>? AND date(tc.created_at) BETWEEN ? AND ? GROUP BY t.user_id",
                (uid, uid, start, end)):
                collab[r["pid"]] = collab.get(r["pid"], 0) + r["n"]
        except Exception:
            collab = {}
        collab_list = []
        if collab:
            ids = list(collab.keys())
            qm = ",".join("?" * len(ids))
            namemap = {r["id"]: r["name"] for r in c.execute(f"SELECT id, name FROM users WHERE id IN ({qm})", ids)}
            collab_list = sorted(
                [{"name": namemap.get(pid, f"#{pid}"), "n": n} for pid, n in collab.items()],
                key=lambda x: -x["n"])[:6]
        extra = _wp_detail_extra(c, uid, start, end)
        mail_detail = _wp_mail_detail(c, uid, start, end)
        presales_detail = _wp_presales_detail(c, uid, start, end)
    msgr_detail = _wp_messenger_detail(emp.get("empno"), start, end)
    total = sum(x["n"] for x in cats)
    total_h = round(sum(x["h"] for x in cats), 1)
    done = next((s["n"] for s in stat if s["status"] == "완료"), 0)
    delayed = next((s["n"] for s in stat if s["status"] == "지연"), 0)
    rate = round(100 * done / total) if total else 0
    for cc in cats:
        cc["pct"] = round(100 * cc["n"] / total) if total else 0
        cc["h"] = round(cc["h"], 1)
    wmax = max([w["n"] for w in weekly], default=0) or 1
    for w in weekly:
        w["h"] = round(w["h"], 1)
        w["pct"] = round(100 * w["n"] / wmax)
    return ctx(request, "admin_work_pattern_detail.html", user=u, emp=emp,
               cats=cats, stat=stat, weekly=weekly, projs=projs, custs=custs, collab=collab_list,
               extra=extra, mail=mail_detail, msgr=msgr_detail, presales=presales_detail,
               total=total, total_h=total_h, rate=rate, delayed=delayed,
               period_label=plabel, days=days, start=start, end=end)


@app.post("/admin/work-patterns/{uid:int}/ai-summary")
async def admin_work_pattern_ai_summary(request: Request, uid: int):
    """직원 업무 패턴 AI 요약 = 개인 매뉴얼의 씨앗. 메타데이터(집계+업무 제목)만 전송, notes 본문 제외.
    인사평가(우수/부진)는 금지하고 사실 기반 주담당 영역·반복업무만 정리."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login"}, 401)
    if not can_view_work_patterns(u):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    start, end, plabel, days = _wp_period(request)
    with db_session() as c:
        try:
            emp = c.execute(
                "SELECT u.name, COALESCE(u.employee_no,'') AS empno, COALESCE(tm.name,'') AS team "
                "FROM users u LEFT JOIN teams tm ON tm.id=u.team_id WHERE u.id=?", (uid,)).fetchone()
        except Exception:
            emp = c.execute(
                "SELECT u.name, '' AS empno, COALESCE(tm.name,'') AS team "
                "FROM users u LEFT JOIN teams tm ON tm.id=u.team_id WHERE u.id=?", (uid,)).fetchone()
        if not emp:
            return JSONResponse({"ok": False, "error": "notfound"}, 404)
        emp = dict(emp)
        cats, stat, weekly, projs, custs = _wp_detail_data(c, uid, start, end)
        extra = _wp_detail_extra(c, uid, start, end)
        mail_d = _wp_mail_detail(c, uid, start, end)
        presales_d = _wp_presales_detail(c, uid, start, end)
        titles = [r[0] for r in c.execute(
            "SELECT title FROM tasks WHERE work_date BETWEEN ? AND ? AND user_id=? AND COALESCE(title,'')<>'' "
            "ORDER BY work_date DESC LIMIT 30", (start, end, uid)).fetchall()]
    msgr_d = _wp_messenger_detail(emp.get("empno"), start, end)
    total = sum(x["n"] for x in cats)
    if not total and not (extra["tkt_recv_n"] or extra["issues_n"] or extra["phases_n"] or mail_d["total"] or msgr_d["msgs"] or presales_d["total_n"]):
        return JSONResponse({"ok": True, "summary": "이 기간에 기록된 업무(일일업무·티켓·이슈·공정·메일·메신저·수주 전 활동)가 없어 요약할 내용이 없습니다."})
    cat_txt = ", ".join(f"{x['category']} {x['n']}건({round(100*x['n']/total)}%)" for x in cats) if total else "—"
    stat_txt = ", ".join(f"{x['status']} {x['n']}건" for x in stat) or "—"
    proj_txt = ", ".join(f"{x['label']}({x['n']})" for x in projs) or "—"
    cust_txt = ", ".join(f"{x['label']}({x['n']})" for x in custs) or "—"
    title_txt = "\n".join(f"- {t}" for t in titles)
    tkt_txt = (", ".join(f"{x['category']} {x['n']}건" for x in extra["tkt_recv"]) or "—") \
        + f" (받아 처리 {extra['tkt_recv_n']} · 요청 {extra['tkt_sent_n']})"
    iss_txt = ", ".join(f"{x['severity']} {x['n']}건" for x in extra["issues"]) or "—"
    pha_txt = ", ".join(f"{x['status']} {x['n']}건" for x in extra["phases"]) or "—"
    pre_txt = (", ".join(f"{x['activity_type']} {x['h']}h" for x in presales_d["by_type"]) or "—") \
        + f" (총 {presales_d['total_h']}h · {presales_d['total_n']}건)"
    try:
        from . import ai_client
        from starlette.concurrency import run_in_threadpool
        if not ai_client.ai_available():
            return JSONResponse({"ok": False, "error": "ai_off",
                                 "summary": "AI가 연결되어 있지 않습니다. (관리자 → AI 설정에서 키 등록 후 사용)"})
        system = (
            "당신은 ㈜케이엔케이(KNK · 검사기·자동화 설비 제조)의 업무 분석 비서입니다. "
            "아래는 한 직원이 기간 동안 남긴 업무 집계(일일업무·티켓·이슈·프로젝트 공정·메일·메신저 · 메타데이터)와 업무 제목 목록입니다. "
            "이 사람이 실제로 맡고 있는 '주 담당 업무 영역'과 '업무 특성'을 한국어로 정리하세요. "
            "목적은 감시가 아니라 업무분장·인수인계·개인 업무 매뉴얼 작성을 위한 기초자료입니다.\n"
            "출력 형식:\n① 한 문단 요약 (이 직원의 주 담당 영역 — 일일업무뿐 아니라 티켓·이슈·공정 역할 포함)\n"
            "② '반복·핵심 업무' 불릿 3~6개 (매뉴얼화 후보 — 인수인계 시 알아야 할 일)\n"
            "③ 한 줄 메모 (협업 관계나 주의점)\n"
            "주의: 우수/부진 같은 인사평가나 추측은 하지 말고, 주어진 사실만으로 정리할 것.")
        prompt = (
            f"직원: {emp['name']} ({emp['team'] or '부서미상'}) · 기간 {plabel} ({start}~{end})\n"
            f"[일일업무] 구성: {cat_txt}\n진행 상태: {stat_txt}\n"
            f"주요 프로젝트: {proj_txt}\n주요 고객/대상: {cust_txt}\n"
            f"[받은 티켓] {tkt_txt}\n[담당 이슈] {iss_txt}\n[담당 공정] {pha_txt}\n"
            f"[메일] 보낸 {mail_d['sent']} · 받은 {mail_d['recv']} (총 {mail_d['total']})\n"
            f"[메신저] 메시지 {msgr_d['msgs']}건 · 방 {msgr_d['rooms']} · 멘션 {msgr_d['mentions']}\n"
            f"[수주 전 활동] {pre_txt}\n"
            f"[일일업무 제목 표본(최근 {len(titles)}건)]:\n{title_txt}")
        ok, ans = await run_in_threadpool(
            ai_client.ai_chat, prompt, system, max_tokens=800, temperature=0.3)
        if not ok or not (ans or "").strip():
            return JSONResponse({"ok": False, "error": "ai_fail",
                                 "summary": "AI 요약 생성에 실패했습니다. 잠시 후 다시 시도해 주세요."})
        return JSONResponse({"ok": True, "summary": ans.strip()})
    except Exception as e:
        print(f"[WORK-PATTERN AI] {e}")
        return JSONResponse({"ok": False, "error": str(e), "summary": "AI 호출 중 오류가 발생했습니다."})


