_TASK_STATUSES = ("진행중", "완료", "지연", "보류", "취소")
_TASK_CATEGORIES = ("영업", "구매", "생산", "품질", "기술", "관리", "출장", "회의", "교육", "기타")


def _validate_task_payload(d: dict) -> tuple:
    """v5H121: tasks API 정합성 검증. (title, category, status, hours) 반환.
    실패 시 ValueError(친절 한국어). 백워드 호환: 미지정/구식 값은 기본값으로 폴백."""
    title = (d.get("title") or "").strip()
    if not title:
        raise ValueError("제목은 필수입니다.")
    if len(title) > 200:
        raise ValueError("제목은 200자 이내로 입력하세요.")
    category = d.get("category") or "기타"
    if category not in _TASK_CATEGORIES:
        category = "기타"  # 폴백 — 구식 값 보호
    status = d.get("status") or "진행중"
    if status not in _TASK_STATUSES:
        status = "진행중"  # 폴백
    try:
        hours = float(d.get("hours") or 0)
    except (TypeError, ValueError):
        hours = 0.0
    if hours < 0:
        raise ValueError("공수는 0 이상이어야 합니다.")
    if hours > 24:
        raise ValueError("공수는 1일 24시간을 초과할 수 없습니다.")
    return title, category, status, hours


@app.post("/api/task")
async def api_create_task(req: Request):
    u = get_user(req)
    if not u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    d = await req.json()
    # v5H121: 정합성 검증 + 화이트리스트
    try:
        title, category, status, hours = _validate_task_payload(d)
    except ValueError as ve:
        return JSONResponse({"ok": False, "error": str(ve)}, 400)
    # v5H28-29: project/customer — FK(매출 프로젝트·고객사) 또는 label(자유 텍스트, 사내업무 등) 자동 분기
    _pid = d.get("project_id") or None
    _plabel = (d.get("project_label") or "").strip() or None
    _cid = d.get("customer_id") or None
    _clabel = (d.get("customer_label") or "").strip() or None
    # z107: 워크플로우 노드 연결 (선택)
    _wf_node_id = d.get("workflow_node_id") or None
    try:
        _wf_node_id = int(_wf_node_id) if _wf_node_id else None
    except (ValueError, TypeError):
        _wf_node_id = None
    with db_session() as c:
        cur = c.execute(
            """INSERT INTO tasks(user_id, work_date, title, category, project_id, project_label,
                                  customer_id, customer_label,
                                  status, hours, notes, next_plan, due_date,
                                  workflow_node_id)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                u["id"],
                d.get("work_date") or date.today().isoformat(),
                title,
                category,
                _pid,
                _plabel if not _pid else None,  # FK 있으면 라벨 무시
                _cid,
                _clabel if not _cid else None,
                status,
                hours,
                d.get("notes") or "",
                (d.get("next_plan") or "").strip(),
                d.get("due_date") or None,
                _wf_node_id,
            ),
        )
        # z107: 워크플로우 노드가 'pending' 이었으면 'in_progress'로 자동 전환
        if _wf_node_id:
            try:
                c.execute(
                    "UPDATE project_workflow_nodes SET status='in_progress' WHERE id=? AND status='pending'",
                    (_wf_node_id,)
                )
            except Exception:
                pass
        new_id = cur.lastrowid
        log_activity(c, u["id"], "task_create",
                     title=f"{u['name']} 신규 카드: {(d.get('title') or '')[:60]}",
                     body=(d.get("notes") or "")[:200],
                     task_id=new_id,
                     project_id=d.get("project_id") or None,
                     team_id=u.get("team_id"))
    # 지연으로 생성된 경우도 알림
    if (d.get("status") or "") == "지연":
        notify_status_change(new_id, u["id"], "", "지연")
    return JSONResponse({"ok": True, "id": new_id})


# =====================================================
# v5H226z405 (대표 지시): 동시 편집 감지 — 낙관적 잠금(optimistic lock)
#   화면을 열 때 들고 있던 수정시각(updated_at=base_ts)을 저장할 때 함께 보냄.
#   그새 그 행의 updated_at 이 바뀌었으면(다른 탭/사람이 먼저 저장) → 충돌 → 저장 거부.
#   ⚠ base_ts 가 비어 있으면(미전송) 검사하지 않음 → 기존 동작 100% 보존(하위호환·안전).
#   table 은 화이트리스트만(SQL 안전). orders/order_items 는 updated_at 컬럼 추가 후 동작(없으면 no-op).
# =====================================================
_EDIT_LOCK_TABLES = {"tasks", "projects", "orders", "order_items", "consumable_orders", "meetings"}


def _edit_conflict(c, table, row_id, base_ts):
    """(conflict: bool, current_ts: str). base_ts 미전송이면 (False, 현재값). 컬럼/행 없으면 (False, '')."""
    if table not in _EDIT_LOCK_TABLES:
        return False, ""
    try:
        row = c.execute(f"SELECT updated_at FROM {table} WHERE id=?", (row_id,)).fetchone()
    except Exception:
        return False, ""   # updated_at 컬럼 미존재(마이그레이션 전) → 검사 생략
    if not row:
        return False, ""
    cur = str((row[0] if not isinstance(row, dict) else row.get("updated_at")) or "")
    if not (base_ts or "").strip():
        return False, cur
    return (cur != str(base_ts).strip()), cur


def _conflict_resp(current_ts):
    return JSONResponse({
        "ok": False, "conflict": True, "current_ts": current_ts,
        "message": "이 항목이 다른 곳(다른 탭/사람)에서 먼저 저장됐습니다. 새로고침 후 다시 저장하세요.",
    }, status_code=409)


def _row_ts(c, table, row_id):
    """저장 후 새 updated_at 반환(클라이언트가 base_ts 갱신용). 없으면 ''."""
    try:
        r = c.execute(f"SELECT updated_at FROM {table} WHERE id=?", (row_id,)).fetchone()
        return str((r[0] if r and not isinstance(r, dict) else (r.get("updated_at") if r else "")) or "")
    except Exception:
        return ""


# ════════════════════════════════════════════════════════════════════════
#  회의록 (16_KNK_Meeting Phase 1 · 모드 A 텍스트)  — z412
#  회의 원문 입력 → AI 결정사항·할 일·요약 추출 → 검토 후 1-클릭 일일카드 연동.
#  · 음성/통역(모드 B·C)은 Phase 2~3. 여기서는 텍스트만.
#  · 권한(제약2): visibility = team(소속팀+참석자+임원이상) / private(작성자+참석자) / all(전사)
#  · 데이터 연결 안전: AI 추출은 '제안'일 뿐, 일일카드 등록은 사용자 클릭 시에만(자동 X).
#    담당자 이름→사용자 연결도 '정확히 1명 단일후보'일 때만(애매하면 미연결).
# ════════════════════════════════════════════════════════════════════════
_MEETING_VIS = ("team", "private", "all")


def _meeting_match_user_id(c, name):
    """이름 → 단일후보 user_id. 정확히 1명(활성) 일치할 때만 연결, 애매하면 None.
    (메모리 feedback_data_connectivity: 단일 후보일 때만 자동연결)."""
    name = (name or "").strip()
    if not name:
        return None
    try:
        rows = c.execute(
            "SELECT id FROM users WHERE name=? AND is_active=1", (name,)
        ).fetchall()
        return rows[0][0] if len(rows) == 1 else None
    except Exception:
        return None


def _meeting_link_attendees(c, mid, attendees_text):
    """참석자 자유텍스트(쉼표/줄바꿈/세미콜론 구분) → meeting_attendees 재구성.
    단일후보 매칭 시 user_id 연결."""
    c.execute("DELETE FROM meeting_attendees WHERE meeting_id=?", (mid,))
    raw = (attendees_text or "").replace("\n", ",").replace(";", ",").replace("、", ",")
    seen = set()
    for nm in (p.strip() for p in raw.split(",")):
        if not nm or nm in seen:
            continue
        seen.add(nm)
        c.execute(
            "INSERT INTO meeting_attendees(meeting_id, user_id, name) VALUES(?,?,?)",
            (mid, _meeting_match_user_id(c, nm), nm),
        )


def _can_view_meeting(c, u, m) -> bool:
    """회의록 열람 권한 (제약2 권한 분기).
    - admin/ceo/executive: 전체 열람
    - 작성자 본인·참석자(연결된 사용자): 항상 열람
    - visibility 'all': 전 직원
    - visibility 'team': 작성자와 같은 팀(팀장 포함)
    - visibility 'private': 작성자+참석자만(위에서 처리) — 그 외 불가
    """
    if not u or not m:
        return False
    role = (u.get("role") or "member").lower()
    uid = u.get("id")
    if role in ("admin", "ceo", "executive"):
        return True
    if m.get("owner_id") == uid:
        return True
    try:
        if c.execute(
            "SELECT 1 FROM meeting_attendees WHERE meeting_id=? AND user_id=?",
            (m["id"], uid),
        ).fetchone():
            return True
    except Exception:
        pass
    vis = m.get("visibility") or "team"
    if vis == "all":
        return True
    if vis == "team" and m.get("team_id") and m.get("team_id") == u.get("team_id"):
        return True
    return False


def _can_edit_meeting(u, m) -> bool:
    """회의록 수정·삭제 권한: 작성자 본인 또는 admin/ceo."""
    if not u or not m:
        return False
    if (u.get("role") or "").lower() in ("admin", "ceo"):
        return True
    return m.get("owner_id") == u.get("id")


def _meeting_due_or_none(s):
    """기한 문자열이 YYYY-MM-DD 형식이면 그대로, 아니면 None (tasks.due_date 보호)."""
    s = (s or "").strip()
    if len(s) == 10 and s[4] == "-" and s[7] == "-" \
       and s[:4].isdigit() and s[5:7].isdigit() and s[8:10].isdigit():
        return s
    return None


@app.get("/meetings", response_class=HTMLResponse)
async def meetings_page(req: Request):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    role = (u.get("role") or "member").lower()
    _sel = """SELECT m.*, t.name AS team_name, usr.name AS owner_name,
                 (SELECT COUNT(*) FROM meeting_decisions WHERE meeting_id=m.id) AS dec_cnt,
                 (SELECT COUNT(*) FROM meeting_actions WHERE meeting_id=m.id) AS act_cnt
              FROM meetings m
              LEFT JOIN teams t ON m.team_id=t.id
              LEFT JOIN users usr ON m.owner_id=usr.id """
    with db_session() as c:
        if role in ("admin", "ceo", "executive"):
            rows = c.execute(
                _sel + "ORDER BY m.meeting_date DESC, m.id DESC LIMIT 300"
            ).fetchall()
        else:
            rows = c.execute(
                _sel + """WHERE (m.owner_id=?
                                 OR m.visibility='all'
                                 OR (m.visibility='team' AND m.team_id=?)
                                 OR m.id IN (SELECT meeting_id FROM meeting_attendees WHERE user_id=?))
                          ORDER BY m.meeting_date DESC, m.id DESC LIMIT 300""",
                (u["id"], u.get("team_id"), u["id"]),
            ).fetchall()
        meetings = [dict(r) for r in rows]
    return ctx(req, "meetings.html", user=u, meetings=meetings)


