# PROJECT DETAIL
# =====================================================
@app.get("/project/{pid}", response_class=HTMLResponse)
async def project_detail(req: Request, pid: int):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    # v5H226z695 (대표 지시): 보드에서 누른 수주번호(?so=<수주번호>) — 그 수주를 상세에서 '메인(편집)' 카드로 올림.
    #   없으면 기존대로 가장 오래된 SO = 메인. (호기/관리번호 클릭 → 그 수주가 곧장 보이도록)
    focus_so = (req.query_params.get("so") or "").strip()
    with db_session() as c:
        p = c.execute(
            """SELECT p.*, cu.name AS customer_name FROM projects p
               LEFT JOIN customers cu ON p.customer_id=cu.id WHERE p.id=?""",
            (pid,),
        ).fetchone()
        if not p:
            return RedirectResponse("/", 303)
        p = dict(p)
        # v5H226z779 (대표 지시·근본해결): 호기 라벨 자동 재번호 — ⭐메인 연결 c 에서, 표시 읽기 '전'에 실행.
        #   진짜 원인(z776~z778 오진 끝에 규명): 기존 재번호가 별도 연결 c2(아래 6273)에서 돌아 이 메인 c 의 열린
        #   트랜잭션과 SQLite 락이 충돌 → write 가 조용히 실패(except:pass)해 어느 프로젝트에서도 사실상 작동 안 함
        #   (007T2601 '1호기 2개'가 발행 이후 계속 방치된 이유). c 로 쓰면 락 없음·같은 요청에 즉시 반영·c 종료 시 커밋.
        #   'N호기' 항목만 골라 발주일·id 순 1·2·3…(비표준 라벨은 보존·순번서 제외 → 중복 근본 제거).
        try:
            import re as _re0
            _hgre = _re0.compile(r"^\d+호기$")
            _aitems = c.execute(
                "SELECT oi.id, oi.unit_label, oi.order_id FROM order_items oi "
                "JOIN orders o ON o.id = oi.order_id WHERE o.project_id=? "
                "ORDER BY o.order_date ASC, o.id ASC, oi.id ASC", (pid,)).fetchall()
            _rl = [(r[0], (r[1] or ""), r[2]) for r in _aitems]
            _hg = [(iid, lbl, oid) for (iid, lbl, oid) in _rl if _hgre.match(lbl)]
            if _hg and any(lbl != f"{i+1}호기" for i, (_, lbl, _) in enumerate(_hg)):
                _nm = {}
                for i, (iid, _, _) in enumerate(_hg):
                    _nm[iid] = f"{i+1}호기"
                    c.execute("UPDATE order_items SET unit_label=? WHERE id=?", (_nm[iid], iid))
                _bo = {}
                for (iid, lbl, oid) in _rl:
                    _bo.setdefault(oid, []).append(_nm.get(iid, lbl))
                for _oid, _subs in _bo.items():
                    if _subs:
                        c.execute("UPDATE orders SET unit_label=? WHERE id=?", (" · ".join(_subs), _oid))
        except Exception:
            pass
        # v5H226z421 (대표 지시): 이 프로젝트의 출처 '영업 기회(수주 전)' 역링크 — 수주 전 업무 내용 다시 보기
        try:
            _oo = c.execute(
                "SELECT id, opp_no, title FROM sales_opportunities WHERE promoted_project_id=? LIMIT 1",
                (pid,)).fetchone()
            origin_opp = dict(_oo) if _oo else None
        except Exception:
            origin_opp = None
        # 참여 전체 카드
        tasks = [dict(r) for r in c.execute(
            """SELECT tk.*, u.name AS user_name, u.rank AS user_rank,
                      tm.name AS team_name, tm.code AS team_code
               FROM tasks tk JOIN users u ON tk.user_id=u.id
               LEFT JOIN teams tm ON u.team_id=tm.id
               WHERE tk.project_id=? ORDER BY tk.work_date DESC, tk.id DESC""",
            (pid,),
        ).fetchall()]
        stats = {
            "total": len(tasks),
            "done": sum(1 for t in tasks if t["status"] == "완료"),
            "progress": sum(1 for t in tasks if t["status"] == "진행중"),
            "delay": sum(1 for t in tasks if t["status"] == "지연"),
            "hours": round(sum(t["hours"] or 0 for t in tasks), 1),
        }
        # 팀별 집계
        by_team = {}
        for t in tasks:
            k = t["team_name"] or "(미배정)"
            by_team.setdefault(k, {"cnt": 0, "hours": 0, "members": set()})
            by_team[k]["cnt"] += 1
            by_team[k]["hours"] += t["hours"] or 0
            by_team[k]["members"].add(t["user_name"])
        by_team_list = [(k, {"cnt": v["cnt"], "hours": v["hours"], "members": sorted(v["members"])})
                        for k, v in sorted(by_team.items(), key=lambda x: -x[1]["cnt"])]
        # 참여자 개별
        by_user = {}
        for t in tasks:
            k = f"{t['user_name']} ({t['team_name'] or '-'})"
            by_user.setdefault(k, {"cnt": 0, "hours": 0, "last": None})
            by_user[k]["cnt"] += 1
            by_user[k]["hours"] += t["hours"] or 0
            if not by_user[k]["last"] or t["work_date"] > by_user[k]["last"]:
                by_user[k]["last"] = t["work_date"]
        by_user_list = sorted(by_user.items(), key=lambda x: -x[1]["cnt"])[:20]

        # 타임라인용 — 일자별 그룹화
        timeline = {}
        for t in tasks:
            timeline.setdefault(t["work_date"], []).append(t)
        timeline_list = sorted(timeline.items(), reverse=True)
        # 댓글 통합
        all_comments = [dict(r) for r in c.execute(
            """SELECT tc.*, u.name AS author_name, u.rank AS author_rank,
                      tk.title AS task_title, tk.id AS tid
               FROM task_comments tc
               JOIN tasks tk ON tc.task_id=tk.id
               JOIN users u ON tc.author_id=u.id
               WHERE tk.project_id=? ORDER BY tc.created_at DESC LIMIT 30""",
            (pid,)
        ).fetchall()]
    retro = get_retro(pid)
    # v5H68: 연결된 수주(SO) 목록
    # v5H94: 페이지 로드 시 projects.order_amount 자동 자가치유
    #   = SUM(orders.total_amount). SO 있으면 합계가 단일 진실 소스.
    # v5H101: due_date / order_date 도 SO 기준으로 자가치유
    #   - due_date  = MAX(orders.due_date)  (가장 늦은 납기 = 전체 일정 기준)
    #   - order_date = MIN(orders.order_date) (최초 발주일)
    project_orders = []
    try:
        with db_session() as c2:
            # v5H104: 각 SO 의 unit_qty 를 실제 items count 와 일치시킴
            #   (qty=2 인데 items=1 인 모순 데이터 자동 정리)
            try:
                so_ids = [r[0] for r in c2.execute(
                    "SELECT id FROM orders WHERE project_id=?", (pid,)
                ).fetchall()]
                # v5H226z779: 호기 자동 재번호는 위(메인 연결 c, p 조회 직후)로 이동함 —
                #   별도 연결 c2 의 write 는 메인 c 의 락과 충돌해 조용히 실패하던 문제(z776~z778 오진 끝에 규명) 해결.
                # 단가(수량) 정합 — items 개수에 맞춤 (개별 SO 예외는 건너뜀)
                for _oid in so_ids:
                    try:
                        _ic = c2.execute(
                            "SELECT COUNT(*) FROM order_items WHERE order_id=?", (_oid,)
                        ).fetchone()[0] or 0
                        if _ic > 0:
                            c2.execute(
                                "UPDATE orders SET unit_qty=? WHERE id=? AND COALESCE(unit_qty,1) <> ?",
                                (_ic, _oid, _ic)
                            )
                    except Exception:
                        continue
                # SO total_amount 도 items_sum 과 정합 (items 가 있을 때만) — 값 변환 실패해도 그 SO만 건너뜀
                for _oid in so_ids:
                    try:
                        row = c2.execute(
                            "SELECT COALESCE(SUM(amount),0), COUNT(*) "
                            "FROM order_items WHERE order_id=?", (_oid,)
                        ).fetchone()
                        _isum = float(row[0] or 0)
                        _icnt = int(row[1] or 0)
                        if _icnt > 0:
                            cur_t = c2.execute(
                                "SELECT total_amount FROM orders WHERE id=?", (_oid,)
                            ).fetchone()
                            if cur_t and abs(float(cur_t[0] or 0) - _isum) > 0.5:
                                c2.execute(
                                    "UPDATE orders SET total_amount=? WHERE id=?",
                                    (_isum, _oid)
                                )
                    except Exception:
                        continue
            except Exception:
                pass

            # v5H130: WON status + SO 0건 + order_amount > 0 → 백업 안전망
            #   인라인/폼 경로 모두 놓친 케이스를 상세 페이지 진입 시 보강.
            #   사용자 시나리오(009T2605)에서 v5H87 quick-status 누락으로
            #   SO가 발행 안 된 상태가 발견된 결함의 최후 차단막.
            try:
                _pre_sos = c2.execute(
                    "SELECT 1 FROM orders WHERE project_id=? LIMIT 1", (pid,)
                ).fetchone()
                _p_status = (p.get("status") if isinstance(p, dict) else p["status"]) or ""
                _p_amt = float(p.get("order_amount") or 0) if isinstance(p, dict) else float(p["order_amount"] or 0)
                # v5H142: NEW_EQUIP 만 자동 SO 발행 (소모품/수리는 별도 도메인 사용)
                _ptype_h = (p.get("project_type") if isinstance(p, dict) else (p["project_type"] if "project_type" in p.keys() else "")) or "NEW_EQUIP"
                if (not _pre_sos and _p_status in _logi.WON_STATUSES and _p_amt > 0
                    and _ptype_h == "NEW_EQUIP"):
                    # v5H226z667 (대표 지시): 자가치유가 수량(unit_qty)을 무시하고 '총액 1줄'을 만들어
                    #   order_items 단가=총액으로 깨지던 버그 수정 → 수량만큼 호기별 per-unit 라인 생성.
                    _pq_h = max(1, int((p.get("unit_qty") if isinstance(p, dict) else (p["unit_qty"] if "unit_qty" in p.keys() else 1)) or 1))
                    _upp_h = (p.get("unit_price") if isinstance(p, dict) else (p["unit_price"] if "unit_price" in p.keys() else 0)) or 0
                    _per_h = float(_upp_h) if _upp_h else (_p_amt / _pq_h)   # 호기 1대 단가(미러 우선·없으면 총액÷수량)
                    _due_h = (p.get("due_date") if isinstance(p, dict) else p["due_date"]) or ""
                    res = _pwf.confirm_order_multi(
                        c2, int(pid),
                        units=[{
                            "label": _logi.project_unit_label(_ptype_h, _i + 1),
                            "amount": _per_h,
                            "due_date": _due_h,
                            "ship_to": "",
                            "note": "",
                        } for _i in range(_pq_h)],
                        order_date=(p.get("order_date") if isinstance(p, dict) else p["order_date"]) or "",
                        created_by=u.get("id") or 0,
                        po_number=(p.get("customer_po") if isinstance(p, dict) else (p["customer_po"] if "customer_po" in p.keys() else "")) or "",
                    )
                    if res and res.get("ok"):
                        grp = (res.get("groups") or [{}])[0]
                        _auto_no = grp.get("so_no") or res.get("so_no") or ""
                        _logi.log_project_change(
                            c2, pid, u.get("id"), "수주발행(자동)",
                            "", _auto_no or _logi.project_unit_label(_ptype_h, 1),
                            note=f"v5H130 자가치유 — 상세 진입 시 누락된 SO 자동 발행 ({_p_amt:,.0f})"
                        )
            except Exception:
                pass

            project_orders = _pwf.get_project_orders(c2, pid)
            # v5H226z662 (대표 지시·A안): 수주 내역(상세) 세금계산서/거래명세서 표시를 작업일정표 보드와
            #   '같은 코드'(_enrich_units_tax)로 통일 — 묶어발행(tax_invoice_lines)+orders 폴백을 호기 빈 칸에
            #   채워, 상세가 호기 칸만 읽어 묶음 세금계산서를 '—'로 놓치던 불일치 해소(두 화면 항상 일치).
            try:
                if can_view_sales(u):
                    _eu = []
                    for _o in project_orders:
                        if (str(_o.get("status") or "").upper() == "CANCELLED"):
                            continue
                        for _uu in (_o.get("units") or []):
                            _eu.append(_uu)
                    if _eu:
                        _enrich_units_tax(c2, pid, _eu, True, iid_key="id")
            except Exception:
                pass
            if project_orders:
                _so_sum = sum(float(o.get("total_amount") or 0) for o in project_orders)
                _curr = float(p.get("order_amount") or 0) if isinstance(p, dict) else float((p["order_amount"] or 0))
                if abs(_so_sum - _curr) > 0.5:
                    c2.execute("UPDATE projects SET order_amount=? WHERE id=?",
                               (_so_sum, pid))
                    # v5H130: 자가치유 변경 이력 기록 (이전 누락분)
                    try:
                        _logi.log_project_change(
                            c2, pid, u.get("id"), "수주액(자가치유)",
                            f"{_curr:,.0f}", f"{_so_sum:,.0f}",
                            note="v5H130 SO 합계 기준 자동 정정"
                        )
                    except Exception:
                        pass
                    if isinstance(p, dict):
                        p["order_amount"] = _so_sum
                # 납기 자가치유 (MAX)
                _due_dates = [o.get("due_date") for o in project_orders if o.get("due_date")]
                if _due_dates:
                    _max_due = max(_due_dates)
                    _proj_due = (p.get("due_date") if isinstance(p, dict) else p["due_date"]) or ""
                    if _max_due != _proj_due:
                        c2.execute("UPDATE projects SET due_date=? WHERE id=?",
                                   (_max_due, pid))
                        if isinstance(p, dict):
                            p["due_date"] = _max_due
                # 발주일 자가치유 (MIN)
                _ord_dates = [o.get("order_date") for o in project_orders if o.get("order_date")]
                if _ord_dates:
                    _min_ord = min(_ord_dates)
                    _proj_ord = (p.get("order_date") if isinstance(p, dict) else p["order_date"]) or ""
                    if _min_ord != _proj_ord:
                        c2.execute("UPDATE projects SET order_date=? WHERE id=?",
                                   (_min_ord, pid))
                        if isinstance(p, dict):
                            p["order_date"] = _min_ord
    except Exception:
        pass
    # v5H101: 프로젝트 변경 이력 (최근 30건)
    project_history_logs = []
    try:
        project_history_logs = _logi.get_project_history(pid, limit=30)
    except Exception:
        pass
    # v5H111: 사이드패널 호기 분해용 — 모든 SO 의 units 를 라벨 숫자 순 정렬
    # v5H133: 표시 순서를 내림차순(최근 호기 → 1호기)으로 반전 (대표 요청)
    all_units_sorted = []
    try:
        import re as _re_n
        _flat = []
        for _so in (project_orders or []):
            _so_ccy = _so.get("currency") or "KRW"   # v5H226z696: 호기 통화 폴백용 SO 통화
            _so_flabel = _so.get("form_label") or ""   # v5H226z701: 수주액 호기/품목 목록 좌측 형태 배지
            _so_fkey = _so.get("form_key") or ""
            _so_no = _so.get("order_no") or ""          # v5H226z702: 수주액 분해 줄 왼쪽 수주번호
            for _u in (_so.get("units") or []):
                _ud = dict(_u)
                # v5H226z696 (대표 지시): 호기별 통화 = 호기 override → SO → KRW.
                #   수주액 박스가 호기마다 실통화로 표기(통화 혼합: 1호기 KRW + 나머지 USD).
                _ud["currency"] = _ud.get("currency") or _so_ccy
                # v5H226z701 (대표 지시): 수주액 박스 호기/품목 줄 왼쪽에 형태 배지 → 각 호기에 그 SO 형태 부여
                _ud["form_label"] = _so_flabel
                _ud["form_key"] = _so_fkey
                # v5H226z702 (대표 지시): 수주번호도 줄 왼쪽에 합쳐 정렬 → 각 호기에 그 SO 수주번호 부여
                _ud["so_no"] = _so_no
                _flat.append(_ud)
        def _sort_key(u):
            lbl = (u.get("unit_label") or "")
            m = _re_n.match(r"^(\d+)", lbl)
            return (int(m.group(1)) if m else 9999, lbl)
        all_units_sorted = sorted(_flat, key=_sort_key, reverse=True)
    except Exception:
        pass
    # v5H124: 프로젝트 SO 통화 혼합 감지 + 통화별 합계 분리
    currency_mix = []
    currency_warning = None
    primary_so_currency = "KRW"
    try:
        from collections import Counter as _C
        ccy_amount = {}
        ccy_count = {}
        for _so in (project_orders or []):
            _c = (_so.get("currency") or "KRW")
            ccy_amount[_c] = ccy_amount.get(_c, 0) + float(_so.get("total_amount") or 0)
            ccy_count[_c] = ccy_count.get(_c, 0) + 1
        if ccy_amount:
            currency_mix = sorted(
                [{"currency": k, "total": v, "cnt": ccy_count.get(k, 0)} for k, v in ccy_amount.items()],
                key=lambda r: -r["total"],
            )
            primary_so_currency = currency_mix[0]["currency"]
            if len(currency_mix) > 1:
                _list = ", ".join(f"{r['currency']}({r['cnt']}건)" for r in currency_mix)
                currency_warning = (
                    f"⚠ 통화 혼합 — {_list}. KPI 수주액은 주 통화({primary_so_currency}) 기준이며, "
                    "외화 SO 는 환산 없이 별도 표기됩니다."
                )
    except Exception:
        pass
    # v5H136 (2026-05-05): 이 프로젝트(장비)에 연결된 PO 라인 = 소모품·부품 사용 이력
    consumables = {"rows": [], "total_amount": 0, "total_qty": 0, "count": 0}
    try:
        consumables = _logi.get_project_consumables(pid, limit=200)
    except Exception:
        pass
    # v5H142 (2026-05-05): 이 프로젝트에 연결된 소모품 발주(consumable_order_items) 라인
    consumable_orders = {"rows": [], "total_amount": 0, "total_qty": 0, "count": 0}
    try:
        from . import consumables as _co_mod
        consumable_orders = _co_mod.get_project_consumable_orders(pid, limit=200)
    except Exception:
        pass
    # v5H137 (2026-05-05): 부모 프로젝트 정보 — CONSUMABLE/SERVICE 인 경우 안내 배너용
    parent_project = None
    try:
        _pp_id = p.get("parent_project_id") if isinstance(p, dict) else (p["parent_project_id"] if "parent_project_id" in p.keys() else None)
        if _pp_id:
            with db_session() as _cp:
                _pp = _cp.execute(
                    "SELECT id, mgmt_code, name, customer_name FROM projects WHERE id=?",
                    (int(_pp_id),)
                ).fetchone()
                if _pp:
                    parent_project = dict(_pp)
    except Exception:
        parent_project = None
    # v5H141 (2026-05-05): 자식 프로젝트(소모품/수리) 목록 — 부모 상세에 노출
    child_projects = []
    try:
        child_projects = _logi.get_child_projects(pid, limit=200)
    except Exception:
        child_projects = []
    # v5H200: 호기 상태로부터 종합 표시 상태 산출 (A안)
    # v5H214: 호기 0건(수주확정 전)이면 fallback 으로 stage 가 아닌 status 사용 — 사용자가 선택한 세부 상태 노출
    try:
        with db_session() as _cdc:
            _fb_status = (p.get("status") if isinstance(p, dict) else (p["status"] if "status" in p.keys() else "")) or ""
            _fb_stage  = (p.get("stage")  if isinstance(p, dict) else (p["stage"]  if "stage"  in p.keys() else "")) or ""
            project_display_status = _pwf.compute_project_display_status(
                _cdc, pid, fallback_stage=(_fb_status or _fb_stage)
            )
    except Exception:
        project_display_status = {"label": "—", "tone": "muted",
                                   "dist": {"진행중":0,"출하":0,"취소":0,"보류":0},
                                   "total": 0, "done": 0, "ratio_text": "",
                                   "has_canceled": False, "has_held": False}
    # v5H226z762 (대표 지시): 이 프로젝트의 제작요청서 발행 이력(최신 먼저) — 상세 '제작요청서' 섹션 소스.
    #   요청사항(고객사/기타)이 통보로만 흘러가 사라지던 문제 해결 — 여기서 다시 확인.
    prod_requests = []
    try:
        with db_session() as _cpr:
            prod_requests = [dict(r) for r in _cpr.execute(
                "SELECT id, mgmt_code, cust_req, note, dept_names, issued_by, issued_by_name, "
                "sent_to, dept_count, msg_sent, created_at, created_date, updated_at, updated_by_name "
                "FROM prod_requests WHERE project_id=? ORDER BY id DESC", (pid,)).fetchall()]
            # v5H226z800 (대표 지시·규칙): 발행자 = 이름 직책 부서 [[knk_name_display_rule]].
            #   수정자(updated_by_name)는 id 스냅샷이 없어 이름만 유지(컬럼 부재).
            for _pr in prod_requests:
                _pr["issued_by_disp"] = user_disp_by_id(_cpr, _pr.get("issued_by"), _pr.get("issued_by_name") or "")
    except Exception:
        prod_requests = []   # 표시 전용 조회 — 테이블 미생성/조회 오류 시에도 상세는 정상 렌더(주변 소모품/자식조회와 동일 패턴)
    # v5H226z373 (대표 지시): 제작요청 발행은 '신규 등록(제작요청서)' 흐름으로 일원화 →
    #   상세의 제작요청 모달/버튼 폐기(_prod_teams 불요). 단가·금액 게이트(can_money)는 유지.
    return ctx(req, "project_detail.html",
               project_display_status=project_display_status,
               can_money=can_view_sales(u),   # 단가·금액은 영업·관리 권한자만(제작요청 통보 받은 부서원에 비공개)
               user=u, p=p, tasks=tasks[:50], stats=stats,
               by_team=by_team_list, by_user=by_user_list, total_tasks=len(tasks),
               timeline=timeline_list[:30], all_comments=all_comments, retro=retro,
               project_orders=project_orders,
               focus_so=focus_so,   # v5H226z695: 보드에서 누른 수주번호 → 메인 카드 지정
               STATUSES=_logi.LOGI_STATUSES,
               project_history=project_history_logs,
               all_units_sorted=all_units_sorted,
               currency_mix=currency_mix,
               currency_warning=currency_warning,
               primary_so_currency=primary_so_currency,
               consumables=consumables,
               consumable_orders=consumable_orders,
               PROJECT_TYPES=_logi.PROJECT_TYPES,
               PROJECT_TYPE_LABELS=_logi.PROJECT_TYPE_LABELS,
               parent_project=parent_project,
               child_projects=child_projects,
               origin_opp=origin_opp,
               prod_requests=prod_requests)


def _prod_request_notify_core(pid, cust_req="", note="", team_ids=None, user=None, record=True, is_update=False, image_count=0, user_ids=None):
    """v5H226z372→z373 (대표 지시): 제작요청 통보 코어.
    제작요청서 = 프로젝트 생성의 출발점으로 일원화 — 신규 등록(발행) 직후 호출:
      ① 작업일정표 '제작요청(prod_request)' 단계 자동 체크(누가·언제·요청사항)
      ② 관련부서(team_ids 없으면 전부서·활성 인원) WORKS 내부 통보 — 단가·금액 제외
         (자료경로·모델·품명·수량·납기·요청사항만 전달).
    반환: dict {ok, sent_to, dept_count, mgmt_code, issued_at, stage_warn}"""
    user = user or {}
    cust_req = (cust_req or "").strip()
    note = (note or "").strip()
    from datetime import datetime as _dt2
    import json as _json
    by_name = user.get("name") or user.get("login_id") or "—"
    uid_self = user.get("id") or -1   # None 이면 'id != NULL' 이 전 행 배제 → -1 로 방어
    with db_session() as c:
        p = c.execute("SELECT id, mgmt_code, name, customer_name, model_name, equip_name, "
                      "unit_qty, due_date, server_path, engraving, cc_name, cc_position, "
                      "po_type, status "
                      "FROM projects WHERE id=?", (pid,)).fetchone()
        if not p:
            return {"ok": False, "error": "not_found"}
        p = dict(p)
        so_nos = [r[0] for r in c.execute(
            "SELECT order_no FROM orders WHERE project_id=? ORDER BY id", (pid,)).fetchall() if r[0]]
        # 통보 부서 — 명시 없으면 전부서(활성 인원 있는 팀 전체)
        tids = [int(t) for t in (team_ids or []) if str(t).strip().isdigit() and int(t) > 0]
        # v5H226z794 (대표 지시): 개별 지정 인원 — 사업부 필터 없이 그 사람에게 정확히 통보(팀통보와 합집합).
        _uids_explicit = [int(x) for x in (user_ids or [])
                          if str(x).strip().isdigit() and int(x) > 0 and int(x) != uid_self]
        if not tids and not _uids_explicit:
            tids = [r[0] for r in c.execute(
                "SELECT DISTINCT t.id FROM teams t JOIN users u ON u.team_id=t.id "
                "AND COALESCE(u.is_active,1)=1").fetchall()]
    if not tids and not _uids_explicit:
        return {"ok": False, "error": "no_team"}
    today = _dt2.now().strftime("%Y-%m-%d")
    now_str = _dt2.now().strftime("%Y-%m-%d %H:%M")
    mgmt = p.get("mgmt_code") or "—"
    model = p.get("model_name") or "—"
    pname = p.get("name") or "—"
    qty = p.get("unit_qty") or 1
    due = (str(p.get("due_date") or "")[:10]) or "—"
    spath = p.get("server_path") or ""
    eng = p.get("engraving") or ""
    cc_nm = p.get("cc_name") or ""
    cc_pos = p.get("cc_position") or ""
    # ① 작업일정표 '제작요청' 단계 자동 체크(+요청사항·발행정보 기록)
    # v5H226z571 (대표 지시): 단계 시스템 제거 — 제작요청의 단계 자동기록 폐지(통보 등 실제 동작은 유지).
    _stage_warn = ""
    # ② 통보 — 단가·금액 제외(생산에 필요한 자료경로·모델·품명·수량·납기·요청사항만)
    title = f"📋 제작요청{' [수정]' if is_update else ''} [{mgmt}] {model}"
    cust_disp = p.get("customer_name") or "—"
    # v5H226z595 (대표 지시): 통보 본문을 '제작요청서' 양식 느낌 텍스트로 — 메신저 카드 미지원 시 폴백 + 인앱 알림 본문 공용.
    _SEP = "━━━━━━━━━━━━━━━━━"
    _SUB = "─────────────────"
    body = f"📋 제작 요청서{' (수정)' if is_update else ''} · {mgmt}\n{_SEP}\n"
    body += f"■ 고객사 : {cust_disp}\n"
    if cc_nm:
        body += f"■ 담당자 : {cc_nm}{(' ' + cc_pos) if cc_pos else ''}\n"
    body += f"■ 작성자 : {by_name}\n"
    body += f"■ MODEL : {model}\n"
    if eng:
        body += f"■ 각인 : {eng}\n"
    body += f"{_SUB}\n〔품목〕\n"
    body += f"· 관리코드 : {mgmt}\n· 모델명 : {model}\n· 품명 : {pname}\n· 수량 : {qty}\n· 일정 : {due}\n"
    if so_nos:
        body += f"· 수주번호 : {', '.join(so_nos)}\n"
    if spath:
        body += f"{_SUB}\n📁 자료 경로\n{spath}\n"
    if cust_req:
        body += f"{_SUB}\n📝 고객사 요청사항\n{cust_req}\n"
    if note:
        body += f"{_SUB}\n📝 기타 요청사항\n{note}\n"
    if image_count and image_count > 0:
        body += f"{_SUB}\n📷 참고 이미지 {image_count}장 첨부 (아래 바로가기에서 확인)\n"
    body += f"{_SEP}\n요청자 {by_name} · {now_str}"
    # v5H226z772 (대표 지시): 제작요청서 이미지 열람 — 통보 링크를 '제작요청서' 단독 페이지로(설치앱서도 렌더·이미지 갤러리 포함)
    link = f"/project/{pid}/prod-request/edit"
    sent_to = 0
    dept_count = 0
    emp_nos = []
    _author_emp = ""   # z812: 발행자 본인 사번(이음 통보용 — 벨+메신저 둘 다)
    dept_names = ""   # z762: 통보 부서 이름 스냅샷(제작요청서 저장·표시용)
    recipients = ""   # z803: 통보 명단(부서 전체=부서명 / 개별=이름 직책 부서)
    # z746(대표 지시): 자동 라우팅 — 프로젝트 사업부(mgmt_code[3]: T검사기/M자동화/L라이프/E기타)에 맞는
    #   담당자 + '공통'(users.biz_divs 빈값)에게만 통보. 사업부 판별 불가 시 필터 없음(전원). '전부서' 선택에도 적용.
    _mc_raw = str(p.get("mgmt_code") or "")
    _pbiz = _mc_raw[3].upper() if (len(_mc_raw) >= 4 and _mc_raw[3].isalpha()) else ""

    def _biz_match(bd_csv):
        if not _pbiz:
            return True
        s = str(bd_csv or "").strip().upper()
        if not s:
            return True   # 공통(전 사업부)
        return _pbiz in {x.strip() for x in s.replace(";", ",").split(",") if x.strip()}

    try:
        with db_session() as c:
            uids = []
            _dept_ids = set()
            _wt_dept_ids = set()   # z803: 부서(팀) 전체로 선택돼 통보된 팀 — 명단에 '부서명'으로 표기
            _indiv_users = []      # z803: 개별 선택돼 통보된 사람 — 명단에 '이름 직책 부서'로 표기
            if tids:   # 팀(부서) 통보 — 사업부 필터
                ph = ",".join("?" * len(tids))
                _cand = c.execute(
                    f"SELECT id, team_id, COALESCE(biz_divs,'') AS bd FROM users "
                    f"WHERE team_id IN ({ph}) AND COALESCE(is_active,1)=1 AND id != ?",
                    (*tids, uid_self)).fetchall()
                for r in _cand:
                    if isinstance(r, dict):
                        _uid, _tid, _bd = r.get("id"), r.get("team_id"), r.get("bd") or ""
                    else:
                        _uid, _tid, _bd = r[0], r[1], (r[2] or "")
                    if not _biz_match(_bd):
                        continue
                    uids.append(_uid)
                    _dept_ids.add(_tid)
                    if _tid:
                        _wt_dept_ids.add(_tid)
                    c.execute("INSERT INTO notifications(user_id, kind, title, body, link) VALUES(?,?,?,?,?)",
                              (_uid, "prod_request", title, body, link))
                    sent_to += 1
            # v5H226z794 (대표 지시): 개별 지정 인원 — 사업부 필터 없이 정확히 통보(팀통보와 합집합·중복 제거)
            if _uids_explicit:
                _seen = set(uids)
                ph3 = ",".join("?" * len(_uids_explicit))
                for r in c.execute(
                        f"SELECT u.id, u.team_id, u.name, u.name_vi, COALESCE(u.rank,'') AS rank, "
                        f"COALESCE(t.name,'') AS team_name FROM users u LEFT JOIN teams t ON u.team_id=t.id "
                        f"WHERE u.id IN ({ph3}) AND COALESCE(u.is_active,1)=1",
                        tuple(_uids_explicit)).fetchall():
                    _d = dict(r); _u2 = _d.get("id"); _t2 = _d.get("team_id")
                    if _u2 in _seen:
                        continue
                    _seen.add(_u2); uids.append(_u2)
                    if _t2:
                        _dept_ids.add(_t2)
                    _indiv_users.append(_d)   # z803: 개별 통보 명단(이름 직책 부서)
                    c.execute("INSERT INTO notifications(user_id, kind, title, body, link) VALUES(?,?,?,?,?)",
                              (_u2, "prod_request", title, body, link))
                    sent_to += 1
            # v5H226z804 (대표 지시): 발행한 사람(본인)에게도 WORKS 알림(벨) — 발행 확인용. 통보 수(sent_to)엔 미포함.
            if uid_self and uid_self > 0:
                try:
                    _self_title = f"✅ 제작요청 발행{' [수정]' if is_update else ''} · {mgmt} — {sent_to}명 통보"
                    _self_body = f"내가 발행한 제작요청서입니다. {sent_to}명에게 통보되었습니다.\n{_SUB}\n{body}"
                    c.execute("INSERT INTO notifications(user_id, kind, title, body, link) VALUES(?,?,?,?,?)",
                              (uid_self, "prod_request", _self_title, _self_body, link))
                except Exception:
                    pass
            dept_count = len(_dept_ids)
            # z762: 통보 부서 이름 스냅샷(제작요청서 저장·표시용 — 나중에 join 없이 바로 표시)
            if _dept_ids:
                _ph_d = ",".join("?" * len(_dept_ids))
                _drs = c.execute(f"SELECT name FROM teams WHERE id IN ({_ph_d})", tuple(_dept_ids)).fetchall()
                dept_names = ", ".join(sorted({
                    (dr[0] if not isinstance(dr, dict) else dr["name"])
                    for dr in _drs if (dr[0] if not isinstance(dr, dict) else dr["name"])}))
            # v5H226z803 (대표 지시): 통보 명단 — 부서 전체 선택=🏢부서명 / 개별 선택=👤이름 직책 부서. [[knk_name_display_rule]]
            _recip_parts = []
            if _wt_dept_ids:
                _ph_wt = ",".join("?" * len(_wt_dept_ids))
                _wtn = [(dr[0] if not isinstance(dr, dict) else dr["name"]) for dr in
                        c.execute(f"SELECT name FROM teams WHERE id IN ({_ph_wt})", tuple(_wt_dept_ids)).fetchall()]
                for _tn in sorted({x for x in _wtn if x}):
                    _recip_parts.append("🏢 " + _tn)
            for _iu in _indiv_users:
                _recip_parts.append("👤 " + vname_full(_iu))
            recipients = " · ".join(_recip_parts)
            # v5H226z391: 메신저(KNK Eum) 통보용 사번 수집 — 컬럼/사번 없으면 건너뜀(인앱 알림은 위에서 이미 완료).
            try:
                if uids:
                    ph2 = ",".join("?" * len(uids))
                    erows = c.execute(
                        f"SELECT employee_no FROM users WHERE id IN ({ph2}) "
                        f"AND COALESCE(employee_no,'')<>''", tuple(uids)).fetchall()
                    emp_nos = [(er[0] if not isinstance(er, dict) else er["employee_no"]) for er in erows]
            except Exception:
                emp_nos = []
            # v5H226z812 (대표 지시): 발행자 본인 사번 — 벨(z804)에 더해 이음 'WORKS 알림' 카드도 받게(발행 확인용).
            try:
                if uid_self and uid_self > 0:
                    _ar = c.execute("SELECT employee_no FROM users WHERE id=? AND COALESCE(employee_no,'')<>''",
                                    (uid_self,)).fetchone()
                    if _ar:
                        _author_emp = (_ar[0] if not isinstance(_ar, dict) else _ar["employee_no"])
            except Exception:
                _author_emp = ""
    except Exception as e:
        return {"ok": False, "error": f"db_error: {str(e)[:120]}", "stage_warn": _stage_warn}
    # v5H226z391 (대표 지시): ③ 메신저(KNK Eum) 통보 — 'WORKS 알림' 봇이 담당자에게 1:1 푸시.
    #   실패해도 등록·인앱알림은 그대로(침묵 금지 — msg_err 로 표면화). 사번 매칭 안 되면 그 인원은 스킵.
    msg_sent = 0
    msg_err = ""
    try:
        from . import sso_client
        _pub = os.environ.get("KNK_WORKS_PUBLIC_BASE", "https://works.knknara.co.kr").rstrip("/")
        _full_link = f"{_pub}{link}"
        # v5H226z807 (대표 지시): 카드=스펙시트 표 통일 항목 — 사업부·장비명·발주유형·진행상태 추가 [[biz_div_code_standard]]
        _BIZ_KO_MSG = {"T": "검사기", "M": "자동화", "L": "라이프밸류", "E": "기타", "C": "소모품", "R": "연구"}
        _ST_KO_MSG = {"DRAFT": "작성중", "QUOTED": "견적", "CONFIRMED": "진행중", "IN_PRODUCTION": "진행중",
                      "READY_TO_SHIP": "진행중", "SHIPPED": "출하", "INVOICED": "출하", "PAID": "출하",
                      "CANCELLED": "취소", "HOLD": "보류"}
        _st_raw = str(p.get("status") or "").strip()
        _status_ko = _ST_KO_MSG.get(_st_raw.upper()) or (_st_raw if _st_raw else "진행중")
        # v5H226z595 (대표 지시): 메신저 '제작요청 카드' 구조화 데이터 — 메신저 지원 시 카드 렌더·미지원 시 body 폴백.
        _card = {
            "type": "prod_request", "title": "제작 요청서",
            "mgmt": mgmt, "customer": cust_disp,
            "cc_name": cc_nm, "cc_position": cc_pos, "author": by_name,
            "model": model, "engraving": eng, "part_name": pname,
            "equip": (p.get("equip_name") or ""), "biz": _BIZ_KO_MSG.get(_pbiz, ""),
            "po_type": (str(p.get("po_type") or "신규").strip() or "신규"), "status": _status_ko,
            "qty": qty, "due": due, "so_nos": so_nos,
            "server_path": spath, "cust_req": cust_req, "note": note,
            "issued_at": now_str, "link": _full_link, "image_count": image_count,
        }
        _mres = sso_client.notify_via_messenger(emp_nos, title, body, _full_link, card=_card)
        # v5H226z812 (대표 지시): 발행자 본인에게도 이음 'WORKS 알림' 카드 — 벨(z804)+메신저 둘 다. 통보 수(msg_sent)엔 미포함.
        if _author_emp:
            try:
                _self_ttl = f"✅ 내가 발행한 제작요청 · {mgmt} — {sent_to}명 통보"
                _self_bd = f"내가 발행한 제작요청서입니다. {sent_to}명에게 통보되었습니다.\n{_SUB}\n{body}"
                sso_client.notify_via_messenger([_author_emp], _self_ttl, _self_bd, _full_link, card=_card)
            except Exception:
                pass
        if _mres.get("ok"):
            msg_sent = _mres.get("sent", 0)
        else:
            msg_err = _mres.get("error", "메신저 통보 실패")
    except Exception as _e:
        msg_err = f"메신저 통보 오류: {str(_e)[:100]}"
    # v5H226z762 (대표 지시): 제작요청서 영구 저장 — 발행마다 1행(재발행 이력). 요청사항이 통보로만 흘러가 사라지던 문제 해결.
    #   저장 실패해도 통보는 유효 — 조용히 넘기지 않고 pr_save_err 로 표면화(except:pass 금지).
    _pr_save_err = ""
    _pr_new_id = 0
    # v5H226z815: 정밀 통보대상 CSV — 부서전체(wt_team_ids)·개별(user_ids) 구분 저장 [[feedback_user_ref_by_id]]
    _wt_csv = ",".join(str(t) for t in sorted(_wt_dept_ids))
    _uid_csv = ",".join(str(_iu.get("id")) for _iu in _indiv_users if _iu.get("id"))
    if record:
        try:
            with db_session() as c:
                _cur = c.execute(
                    "INSERT INTO prod_requests(project_id, mgmt_code, cust_req, note, team_ids, wt_team_ids, user_ids, dept_names, recipients, "
                    "issued_by, issued_by_name, sent_to, dept_count, msg_sent, created_at, created_date) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                    (pid, mgmt, cust_req, note, ",".join(str(t) for t in sorted(_dept_ids)), _wt_csv, _uid_csv, dept_names, recipients,
                     (user.get("id") or None), by_name, sent_to, dept_count, msg_sent, now_str, now_str[:10]))
                _pr_new_id = _cur.lastrowid or 0
        except Exception as _se:
            _pr_save_err = str(_se)[:150]
    return {"ok": True, "sent_to": sent_to, "dept_count": dept_count,
            "mgmt_code": mgmt, "issued_at": now_str, "stage_warn": _stage_warn,
            "msg_sent": msg_sent, "msg_err": msg_err, "pr_save_err": _pr_save_err,
            "pr_id": _pr_new_id, "recipients": recipients, "dept_names": dept_names,
            "wt_team_ids": _wt_csv, "user_ids": _uid_csv}


# v5H226z772 (대표 지시): 제작요청서 참고 이미지 저장 — files=[(orig_name, raw_bytes)…] → 압축본+썸네일 디스크 저장 + prod_request_images 기록.
#   compress_image_bytes(EXIF회전·긴변1920px·썸네일320×160) 재사용. PIL이 못 여는 형식(HEIC 등)은 그 파일만 건너뜀(나머지 저장·조용히 넘기지 않음).
_PROD_IMG_EXT = (".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp")


def _attach_prod_images(prid, project_id, files, uploaded_by):
    """반환: {"saved": n, "skipped": [orig…], "errors": [msg…]}. prid=prod_requests.id."""
    out = {"saved": 0, "skipped": [], "errors": []}
    if not prid or not files:
        return out
    import time as _t, re as _re
    try:
        from . import consumables as _co
    except Exception as _e:
        out["errors"].append(f"img_lib: {str(_e)[:80]}")
        return out
    updir = os.path.join("uploads", "prod_requests", str(int(prid)))
    try:
        os.makedirs(updir, exist_ok=True)
    except Exception as _e:
        out["errors"].append(f"mkdir: {str(_e)[:80]}")
        return out
    for idx, (orig, raw) in enumerate(files):
        try:
            ext = os.path.splitext(orig or "")[1].lower()
            if ext not in _PROD_IMG_EXT or not raw or len(raw) < 50:
                out["skipped"].append(orig or "(무명)")
                continue
            big_b, thumb_b, _info = _co.compress_image_bytes(raw)   # HEIC 등 PIL 미지원이면 예외 → 건너뜀
            base = _re.sub(r"[^\w.\-]+", "_", os.path.splitext(orig or "img")[0])[:32] or "img"
            ts = int(_t.time())
            fn = f"pr_{int(prid)}_{ts}_{idx+1}_{base}.jpg"
            fn_th = f"pr_{int(prid)}_{ts}_{idx+1}_{base}_thumb.jpg"
            with open(os.path.join(updir, fn), "wb") as _f:
                _f.write(big_b)
            with open(os.path.join(updir, fn_th), "wb") as _f:
                _f.write(thumb_b)
            url = f"/uploads/prod_requests/{int(prid)}/{fn}"
            turl = f"/uploads/prod_requests/{int(prid)}/{fn_th}"
            with db_session() as c:
                c.execute(
                    "INSERT INTO prod_request_images(prod_request_id, project_id, url, thumb_url, orig_name, size, uploaded_by, created_at) "
                    "VALUES(?,?,?,?,?,?,?,datetime('now','localtime'))",
                    (int(prid), int(project_id) if project_id else None, url, turl,
                     (orig or "")[:200], len(big_b), uploaded_by))
            out["saved"] += 1
        except Exception as _e:
            out["skipped"].append(orig or "(무명)")
            out["errors"].append(str(_e)[:80])
    return out


# =====================================================
# CUSTOMER LIST (2026-04-28 신설 — 사이드바 /customers 링크 broken 수정)
# =====================================================
@app.get("/customers", response_class=HTMLResponse)
async def customers_list(req: Request):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        try:
            # v5H58: 자동 산정 등급 점수(tier_score) 우선 정렬
            # v5H181: manager_name / phone / email / is_active / address 도 SELECT
            #         (이전엔 누락되어 list 페이지에서 빈 칸으로 보이던 버그)
            rows = c.execute(
                """SELECT cu.id, cu.name, cu.alias, cu.tier, cu.note, cu.biz_no, cu.ceo_name,
                          cu.manager_name, cu.phone, cu.email, cu.address,
                          COALESCE(cu.is_active, 1) AS is_active,
                          COALESCE(cu.is_overseas, 0) AS is_overseas,
                          COALESCE(cu.tier_score, 0) AS tier_score,
                          cu.tier_computed_at,
                          COUNT(DISTINCT p.id) AS proj_count,
                          COALESCE(SUM(p.order_amount), 0) AS total_amount,
                          MAX(p.order_date) AS last_order
                   FROM customers cu
                   LEFT JOIN projects p ON p.customer_id = cu.id
                   GROUP BY cu.id
                   ORDER BY tier_score DESC, total_amount DESC, cu.name"""
            ).fetchall()
            customers = [dict(r) for r in rows]
        except Exception:
            customers = [dict(r) for r in c.execute(
                "SELECT id, name, tier, note FROM customers ORDER BY tier DESC, name"
            ).fetchall()]
    return ctx(req, "customers_list.html", user=u, active="customers", customers=customers)


# =====================================================
# CUSTOMER DETAIL
# =====================================================
@app.get("/customer/{cid}", response_class=HTMLResponse)
async def customer_detail(req: Request, cid: int):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        cu = c.execute("SELECT * FROM customers WHERE id=?", (cid,)).fetchone()
        if not cu:
            return RedirectResponse("/", 303)
        cu = dict(cu)
        # 고객사 프로젝트
        pjts = [dict(r) for r in c.execute(
            "SELECT * FROM projects WHERE customer_id=? ORDER BY id DESC", (cid,),
        ).fetchall()]
        # 최근 2주 카드
        since = (date.today() - timedelta(days=30)).isoformat()
        tasks = [dict(r) for r in c.execute(
            """SELECT tk.*, u.name AS user_name, tm.name AS team_name, p.name AS project_name
               FROM tasks tk JOIN users u ON tk.user_id=u.id
               LEFT JOIN teams tm ON u.team_id=tm.id
               LEFT JOIN projects p ON tk.project_id=p.id
               WHERE tk.customer_id=? AND tk.work_date>=? ORDER BY tk.work_date DESC""",
            (cid, since),
        ).fetchall()]
        stats = {
            "total": len(tasks),
            "done": sum(1 for t in tasks if t["status"] == "완료"),
            "delay": sum(1 for t in tasks if t["status"] == "지연"),
            "hours": round(sum(t["hours"] or 0 for t in tasks), 1),
        }
        by_team = {}
        for t in tasks:
            k = t["team_name"] or "(미배정)"
            by_team.setdefault(k, {"cnt": 0, "hours": 0})
            by_team[k]["cnt"] += 1
            by_team[k]["hours"] += t["hours"] or 0
        by_team_list = sorted(by_team.items(), key=lambda x: -x[1]["cnt"])
        # v5H56: 다중 담당자 (역할별 정렬)
        contacts = []
        try:
            contacts = [dict(r) for r in c.execute(
                "SELECT * FROM customer_contacts WHERE customer_id=? "
                "ORDER BY is_primary DESC, "
                "CASE role WHEN '영업' THEN 1 WHEN '구매' THEN 2 "
                "          WHEN '세금계산서' THEN 3 WHEN '품질' THEN 4 "
                "          WHEN '기술' THEN 5 WHEN '결재' THEN 6 ELSE 9 END, id",
                (cid,)
            ).fetchall()]
        except Exception:
            contacts = []

    # v5H58: 등급 점수 breakdown
    from . import customer_tier as _ct
    tier_breakdown = _ct.parse_breakdown(cu.get("tier_breakdown"))
    # v5H113: 고객사 변경 이력 (최근 50건)
    try:
        customer_history = _logi.get_customer_history(cid, limit=50)
    except Exception:
        customer_history = []
    return ctx(req, "customer_detail.html",
               user=u, cu=cu, pjts=pjts, tasks=tasks[:80],
               stats=stats, by_team=by_team_list, total_tasks=len(tasks),
               contacts=contacts, tier_breakdown=tier_breakdown,
               customer_history=customer_history)


# =====================================================
# CALENDAR (개인 월간 뷰)
# =====================================================
@app.get("/calendar", response_class=HTMLResponse)
@app.get("/calendar/{month}", response_class=HTMLResponse)
async def calendar_page(req: Request, month: str = "", scope: str = "me"):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    if not month:
        month = date.today().strftime("%Y-%m")
    # 리더 이상이 아니면 me로 강제
    if scope == "team" and u["role"] not in ("leader", "executive", "ceo", "admin"):
        scope = "me"
    y, m = int(month[:4]), int(month[5:7])
    with db_session() as c:
        if scope == "team" and u.get("team_id"):
            rows = [dict(r) for r in c.execute(
                """SELECT work_date, status, COUNT(*) AS cnt, COALESCE(SUM(hours),0) AS hours
                   FROM tasks t JOIN users u ON t.user_id=u.id
                   WHERE u.team_id=? AND work_date LIKE ?
                   GROUP BY work_date, status""",
                (u["team_id"], f"{month}%"),
            ).fetchall()]
        else:
            rows = [dict(r) for r in c.execute(
                """SELECT work_date, status, COUNT(*) AS cnt, COALESCE(SUM(hours),0) AS hours
                   FROM tasks WHERE user_id=? AND work_date LIKE ?
                   GROUP BY work_date, status""",
                (u["id"], f"{month}%"),
            ).fetchall()]
    by_date = {}
    for r in rows:
        by_date.setdefault(r["work_date"], {"total": 0, "done": 0, "progress": 0,
                                              "delay": 0, "hours": 0})
        by_date[r["work_date"]]["total"] += r["cnt"]
        by_date[r["work_date"]]["hours"] += r["hours"]
        if r["status"] == "완료":
            by_date[r["work_date"]]["done"] += r["cnt"]
        elif r["status"] == "진행중":
            by_date[r["work_date"]]["progress"] += r["cnt"]
        elif r["status"] == "지연":
            by_date[r["work_date"]]["delay"] += r["cnt"]

    # v5H202: 일·월시작 캘린더(일=0, 월=1, ..., 토=6) + 공휴일 표기 (수주관리 기준 통일)
    import calendar as _cal_mod
    _ccal = _cal_mod.Calendar(firstweekday=6)  # Sunday-first
    weeks = []
    today_iso = date.today().isoformat()
    for week in _ccal.monthdatescalendar(y, m):
        row = []
        for dt in week:
            ds = dt.isoformat()
            in_month = (dt.month == m)
            row.append({
                "day": dt.day if in_month else 0,
                "date": ds if in_month else "",
                "d": by_date.get(ds) if in_month else None,
                "is_today": (ds == today_iso) if in_month else False,
                "wd": dt.weekday(),  # Mon=0..Sun=6
                "is_sun": dt.weekday() == 6,
                "is_sat": dt.weekday() == 5,
                "hol_kr": HOLIDAYS_KR.get(ds) if in_month else None,
                "hol_vn": HOLIDAYS_VN.get(ds) if in_month else None,
            })
        if any(c["day"] > 0 for c in row):
            weeks.append(row)

    prev_m = f"{y-1 if m==1 else y}-{12 if m==1 else m-1:02d}"
    next_m = f"{y+1 if m==12 else y}-{1 if m==12 else m+1:02d}"
    month_total = sum(d["total"] for d in by_date.values())
    month_done = sum(d["done"] for d in by_date.values())
    month_hours = round(sum(d["hours"] for d in by_date.values()), 1)

    # v5H226z112 (2026-05-31): 분할 레이아웃 — 우측 임박 일정 7일 (calendar split)
    # 오늘 ~ +7일 사이의 본인 업무 데이터 + 공휴일 합산
    upcoming = []
    today_dt = date.today()
    with db_session() as c2:
        for i in range(8):  # 오늘 포함 7일
            dt_i = today_dt + timedelta(days=i)
            ds_i = dt_i.isoformat()
            row = c2.execute(
                """SELECT COUNT(*) AS cnt, COALESCE(SUM(hours),0) AS hours,
                          SUM(CASE WHEN status='완료' THEN 1 ELSE 0 END) AS done
                   FROM tasks WHERE user_id=? AND work_date=?""",
                (u["id"], ds_i),
            ).fetchone()
            upcoming.append({
                "date": ds_i,
                "day": dt_i.day,
                "wd": dt_i.weekday(),
                "is_today": (i == 0),
                "is_tomorrow": (i == 1),
                "rel_label": ["오늘", "내일", "모레"][i] if i < 3 else f"D+{i}",
                "total": (row["cnt"] if row else 0) or 0,
                "done":  (row["done"] if row else 0) or 0,
                "hours": round((row["hours"] if row else 0) or 0, 1),
                "hol_kr": HOLIDAYS_KR.get(ds_i),
                "hol_vn": HOLIDAYS_VN.get(ds_i),
            })

    return ctx(req, "calendar.html",
               user=u, weeks=weeks, month=month, prev_m=prev_m, next_m=next_m,
               month_total=month_total, month_done=month_done, month_hours=month_hours,
               upcoming=upcoming,
               scope=scope, can_team=u["role"] in ("leader","executive","ceo","admin") and u.get("team_id") is not None,
               active="calendar")


# =====================================================
# FEED (부서간 오늘 피드)
# =====================================================
@app.get("/feed", response_class=HTMLResponse)
@app.get("/feed/{sel_date}", response_class=HTMLResponse)
async def feed_page(req: Request, sel_date: str = ""):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    if not sel_date:
        sel_date = date.today().isoformat()
    with db_session() as c:
        # v5H49: 오늘 카드가 없으면 가장 최근 작성일로 자동 폴백 — 빈 피드 방지
        today_n = c.execute(
            "SELECT COUNT(*) FROM tasks WHERE work_date=?", (sel_date,)
        ).fetchone()[0]
        if today_n == 0:
            r = c.execute(
                "SELECT MAX(work_date) FROM tasks WHERE work_date<=?", (sel_date,)
            ).fetchone()
            if r and r[0]:
                sel_date = r[0]
        # 팀별 오늘 한 줄 요약
        summaries = [dict(r) for r in c.execute(
            """SELECT ts.*, t.name AS team_name, t.code AS team_code, t.is_lab,
                      u.name AS author_name
               FROM team_summaries ts JOIN teams t ON ts.team_id=t.id
               LEFT JOIN users u ON ts.author_id=u.id
               WHERE ts.work_date=? ORDER BY t.display_order""",
            (sel_date,),
        ).fetchall()]
        # 전 팀 오늘 카드 (요약)
        tasks = [dict(r) for r in c.execute(
            """SELECT tk.*, u.name AS user_name, u.rank AS user_rank, u.team_id AS team_id,
                      t.name AS team_name, t.code AS team_code,
                      p.name AS project_name, cu.name AS customer_name
               FROM tasks tk JOIN users u ON tk.user_id=u.id
               LEFT JOIN teams t ON u.team_id=t.id
               LEFT JOIN projects p ON tk.project_id=p.id
               LEFT JOIN customers cu ON tk.customer_id=cu.id
               WHERE tk.work_date=? ORDER BY t.display_order, u.id, tk.id""",
            (sel_date,),
        ).fetchall()]
        # 메타데이터(댓글수+리액션수) 일괄 조회 → 카드 표면 배지로 표시
        meta = get_meta_bulk([t["id"] for t in tasks])
        # 현재 사용자 멘션/응답대기 카운트 (나를 @멘션한 댓글이 달린 카드)
        mentioned_ids = set()
        if tasks:
            ph = ",".join("?" * len(tasks))
            mrows = c.execute(
                f"""SELECT DISTINCT tc.task_id
                    FROM comment_mentions cm
                    JOIN task_comments tc ON cm.comment_id=tc.id
                    WHERE cm.user_id=? AND tc.task_id IN ({ph})""",
                (u["id"],) + tuple(t["id"] for t in tasks)
            ).fetchall()
            mentioned_ids = {r["task_id"] for r in mrows}
        for t in tasks:
            m = meta.get(t["id"], {})
            t["meta_comments"] = m.get("comments", 0)
            t["meta_ack"] = m.get("ack", 0)
            t["meta_question"] = m.get("question", 0)
            t["meta_risk"] = m.get("risk", 0)
            t["meta_ok"] = m.get("ok", 0)
            t["meta_last_comment"] = m.get("last_comment", "")
            t["meta_mentioned_me"] = 1 if t["id"] in mentioned_ids else 0
            t["meta_has_activity"] = bool(
                t["meta_comments"] or t["meta_ack"] or t["meta_question"]
                or t["meta_risk"] or t["meta_ok"]
            )
            # 정렬 키: 지연(0) → 리스크(1) → 멘션(2) → 활동(3) → 진행중(4) → 대기(5) → 완료(6)
            if t["status"] == "지연":
                sk = 0
            elif t["meta_risk"]:
                sk = 1
            elif t["meta_mentioned_me"]:
                sk = 2
            elif t["meta_has_activity"]:
                sk = 3
            elif t["status"] == "진행중":
                sk = 4
            elif t["status"] in ("대기", "보류"):
                sk = 5
            else:
                sk = 6
            t["_sort"] = sk

        by_team = {}
        for t in tasks:
            k = t["team_name"] or "(미배정)"
            by_team.setdefault(k, {"code": t["team_code"], "tasks": [],
                                    "has_urgent": False})
            by_team[k]["tasks"].append(t)
            if t["_sort"] <= 2:  # 지연/리스크/멘션 중 하나라도 있으면 긴급팀
                by_team[k]["has_urgent"] = True
        # 각 팀 내부 정렬: 우선순위 → 담당자 → id
        for k, d in by_team.items():
            d["tasks"].sort(key=lambda x: (x["_sort"], x.get("user_name") or "", x["id"]))
        # v5H49: 템플릿이 td.team_name/total/done/delay/summaries 를 기대 → dict 리스트로 변환
        by_team_list = []
        for nm, info in sorted(by_team.items(), key=lambda x: x[1]["code"] or "99"):
            ts = info.get("tasks") or []
            by_team_list.append({
                "team_name": nm,
                "code": info.get("code"),
                "has_urgent": info.get("has_urgent", False),
                "tasks": ts,
                "summaries": ts[:5],
                "total": len(ts),
                "done": sum(1 for t in ts if t.get("status") == "완료"),
                "progress": sum(1 for t in ts if t.get("status") == "진행중"),
                "delay": sum(1 for t in ts if t.get("status") == "지연"),
            })

        # 전체 카운트 (필터칩용)
        all_total = len(tasks)
        all_done = sum(1 for t in tasks if t["status"] == "완료")
        all_progress = sum(1 for t in tasks if t["status"] == "진행중")
        all_delay = sum(1 for t in tasks if t["status"] == "지연")
        all_wait = sum(1 for t in tasks if t["status"] in ("대기", "보류"))
        all_risk = sum(1 for t in tasks if t["meta_risk"])
        all_mentioned = sum(1 for t in tasks if t["meta_mentioned_me"])
    prev_d = (datetime.strptime(sel_date, "%Y-%m-%d") - timedelta(days=1)).strftime("%Y-%m-%d")
    next_d = (datetime.strptime(sel_date, "%Y-%m-%d") + timedelta(days=1)).strftime("%Y-%m-%d")
    # 멀티뷰용 flat JSON (칸반/캘린더)
    import json as _json
    flat_tasks = _json.dumps([{
        "id": t["id"], "title": t["title"], "status": t["status"],
        "user_name": t["user_name"], "user_rank": t.get("user_rank") or "",
        "team_name": t.get("team_name") or "", "project_name": t.get("project_name") or "",
        "customer_name": t.get("customer_name") or "",
        "hours": t.get("hours") or 0,
        "cm": t.get("meta_comments", 0), "risk": t.get("meta_risk", 0),
        "question": t.get("meta_question", 0), "ack": t.get("meta_ack", 0),
    } for t in tasks], ensure_ascii=False)
    # 역할 기반 기본 펼침 로직용 — 내 팀 id
    my_team_id = u.get("team_id")
    return ctx(req, "feed.html",
               user=u, summaries=summaries, by_team=by_team_list,
               sel_date=sel_date, prev_date=prev_d, next_date=next_d,
               all_total=all_total, all_done=all_done, all_progress=all_progress,
               all_delay=all_delay, all_wait=all_wait,
               all_risk=all_risk, all_mentioned=all_mentioned,
               my_team_id=my_team_id, flat_tasks_json=flat_tasks,
               sel_date_obj=sel_date, active="feed")


