        for o in orows:
            body.append(f"<tr><td>{o['id']}</td><td>{_esc(o['order_no'])}</td><td><b>{_esc(o['unit_qty'])}</b></td><td>{_esc(o['unit_label'])}</td><td>{_esc(o['total_amount'])}</td><td>{_esc(o['status'])}</td><td>{_esc(o['so_type'])}</td></tr>")
        body.append("</table>")
        oids = [o["id"] for o in orows]
        items = []
