@app.post("/admin/users/{uid:int}/delete")
async def admin_users_delete(req: Request, uid: int):
    """v5H226z532 (대표 지시): 사용자 영구 삭제 — 불필요/삭제표시(_deleted_user)·테스트 계정 정리.
    안전장치: 본인·관리자/대표 계정 보호. (실제 직원은 '수정→비활성' 권장 — 기록 보존.)"""
    u = require(req, ["admin", "ceo"])
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    if uid == u.get("id"):
        return JSONResponse({"ok": False, "error": "본인 계정은 삭제할 수 없습니다."}, 400)
    with db_session() as c:
        row = c.execute("SELECT id, name, role FROM users WHERE id=?", (uid,)).fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "이미 없는 사용자입니다."}, 404)
        row = dict(row)
        if (row.get("role") or "") in ("admin", "ceo"):
            # v5H226z537: 중복 관리자/대표 정리 허용 — 단 '마지막 1개'는 보호(전체 잠김 방지)
            _cnt = c.execute("SELECT COUNT(*) FROM users WHERE role IN ('admin','ceo')").fetchone()[0]
            if _cnt <= 1:
                return JSONResponse({"ok": False, "error": "마지막 관리자/대표 계정은 삭제할 수 없습니다."}, 400)
        # v5H226z538: PROD는 PRAGMA foreign_keys=ON 이라, 이 사용자를 참조하는 다른 테이블(작성이력 등)이
        #             있으면 DELETE 가 IntegrityError → 처리 안 된 500 → 화면엔 "통신 오류"로 보였음.
        #             삭제 대상은 placeholder/불필요 계정이므로, FK 강제를 잠깐 끄고 본행만 확실히 제거(참조는
        #             고아가 되어 "—"로 표시 — z532 설계와 동일). PRAGMA 는 트랜잭션 밖(앞선 건 SELECT뿐)에서 실행.
        try:
            c.execute("PRAGMA foreign_keys=OFF")
            c.execute("DELETE FROM users WHERE id=?", (uid,))
            c.execute("PRAGMA foreign_keys=ON")
        except Exception as e:
            return JSONResponse({"ok": False, "error": f"삭제 중 오류: {e}"}, 500)
    return JSONResponse({"ok": True, "name": row.get("name")})


@app.post("/admin/users/bulk-delete")
async def admin_users_bulk_delete(req: Request):
    """z749(대표 지시): 사용자 목록에서 선택한 여러 명 한 번에 영구 삭제.
    안전가드: ①본인 ②관리자/대표(admin·ceo)는 제외(잠금·실수 방지 — 관리자 삭제는 개별로).
    단건 삭제(z538)와 동일하게 FK 잠깐 끄고 본행만 제거(참조는 고아='—'). 데이터 보존 원하면 '비활성' 권장.
    Returns: {ok, deleted, deleted_names, skipped:[{name,reason}], errors:[{name,error}]}."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    try:
        body = await req.json()
    except Exception:
        body = {}
    ids = []
    for x in (body.get("ids") or []):
        try:
            ids.append(int(x))
        except Exception:
            pass
    ids = list(dict.fromkeys(ids))   # 중복 제거·순서 유지
    if not ids:
        return JSONResponse({"ok": False, "error": "선택된 사용자가 없습니다."}, 400)
    me = u.get("id")
    deleted, deleted_names, skipped, errors = 0, [], [], []
    with db_session() as c:
        ph = ",".join("?" * len(ids))
        rows = {}
        for r in c.execute(f"SELECT id, name, role FROM users WHERE id IN ({ph})", tuple(ids)).fetchall():
            rd = dict(r)
            rows[rd["id"]] = rd
        to_delete = []
        for uid in ids:
            r = rows.get(uid)
            if not r:
                skipped.append({"name": f"#{uid}", "reason": "이미 없음"})
                continue
            nm = r.get("name") or f"#{uid}"
            if uid == me:
                skipped.append({"name": nm, "reason": "본인 계정"})
                continue
            if (r.get("role") or "") in ("admin", "ceo"):
                skipped.append({"name": nm, "reason": "관리자/대표(개별 삭제만)"})
                continue
            to_delete.append((uid, nm))
        if to_delete:
            try:
                c.execute("PRAGMA foreign_keys=OFF")
            except Exception:
                pass
            for uid, nm in to_delete:
                try:
                    c.execute("DELETE FROM users WHERE id=?", (uid,))
                    deleted += 1
                    deleted_names.append(nm)
                except Exception as e:
                    errors.append({"name": nm, "error": str(e)[:80]})
            try:
                c.execute("PRAGMA foreign_keys=ON")
            except Exception:
                pass
    return JSONResponse({"ok": True, "deleted": deleted, "deleted_names": deleted_names,
                         "skipped": skipped, "errors": errors})


@app.post("/admin/users/{uid:int}/edit")
async def admin_users_edit_submit(req: Request, uid: int):
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    form = await req.form()
    name = (form.get("name") or "").strip()
    if not name:
        return RedirectResponse(f"/admin/users/{uid}/edit?error=required", 303)
    with db_session() as c:
        # v5H113 LOW#18: 변경 전 스냅샷
        old_row = c.execute(
            "SELECT name, role, team_id, rank, email, is_active "
            "FROM users WHERE id=?", (uid,)
        ).fetchone()
        old_data = dict(old_row) if old_row else {}
        # v5H226z536: 사번(=로그인ID) 중복 사전검사 — 다른 사용자가 이미 쓰면 차단(조용히 실패 금지)
        _sabeon = (form.get("login_id") or "").strip()
        if _sabeon:
            _dup = c.execute(
                "SELECT name FROM users WHERE id<>? AND (login_id=? OR COALESCE(employee_no,'')=?)",
                (uid, _sabeon, _sabeon)).fetchone()
            if _dup:
                from urllib.parse import quote as _q
                return RedirectResponse(
                    f"/admin/users/{uid}/edit?error=dup&val={_q(_sabeon)}&dupname={_q(_dup[0] or '')}", 303)
        # 비번 변경된 경우만 갱신
        new_pw = (form.get("password") or "").strip()
        if new_pw:
            c.execute(
                "UPDATE users SET name=?, role=?, team_id=?, rank=?, email=?, "
                "is_active=?, password=? WHERE id=?",
                (name, form.get("role", "member"),
                 form.get("team_id") or None,
                 form.get("rank", ""), form.get("email", ""),
                 int(form.get("is_active") or 1), hash_pw(new_pw), uid)
            )
        else:
            c.execute(
                "UPDATE users SET name=?, role=?, team_id=?, rank=?, email=?, "
                "is_active=? WHERE id=?",
                (name, form.get("role", "member"),
                 form.get("team_id") or None,
                 form.get("rank", ""), form.get("email", ""),
                 int(form.get("is_active") or 1), uid)
            )
        # v5H226z141: 사번(로그인ID) + 센터 진입 권한 저장
        _sabeon = (form.get("login_id") or "").strip()
        if _sabeon:
            try:
                c.execute("UPDATE users SET login_id=? WHERE id=?", (_sabeon, uid))
                _ucols = [r[1] for r in c.execute("PRAGMA table_info(users)").fetchall()]
                if "employee_no" in _ucols:
                    c.execute("UPDATE users SET employee_no=? WHERE id=?", (_sabeon, uid))
            except Exception:
                pass
        for _flag in ("can_view_sales", "can_use_sales", "can_view_logistics", "can_use_logistics"):
            try:
                c.execute(f"UPDATE users SET {_flag}=? WHERE id=?",
                          (1 if form.get(_flag) else 0, uid))
            except Exception:
                pass
        # z746(대표 지시): 담당 사업부(제작요청 통보 자동 라우팅) — 체크한 코드 CSV, 없으면 ''(공통·전 사업부 통보).
        try:
            _bd_sel = [x for x in form.getlist("biz_divs") if x in ("T", "M", "L", "E")]
            c.execute("UPDATE users SET biz_divs=? WHERE id=?", (",".join(_bd_sel), uid))
        except Exception:
            pass
        # v5H113 LOW#18: user_history diff 기록
        new_data = {
            "name": name,
            "role": form.get("role", "member"),
            "team_id": form.get("team_id") or None,
            "rank": form.get("rank", ""),
            "email": form.get("email", ""),
            "is_active": int(form.get("is_active") or 1),
        }
        _label_map = {"name":"이름","role":"권한","team_id":"팀","rank":"직급","email":"이메일","is_active":"활성"}
        for _k, _label in _label_map.items():
            ov = "" if old_data.get(_k) is None else str(old_data.get(_k))
            nv = "" if new_data.get(_k) is None else str(new_data.get(_k))
            if ov == nv:
                continue
            try:
                c.execute(
                    "INSERT INTO user_history(user_id, changed_by, field, "
                    "old_value, new_value, note) VALUES(?,?,?,?,?,?)",
                    (uid, u.get("id"), _label, ov, nv, "")
                )
            except Exception:
                pass
        if new_pw:
            try:
                c.execute(
                    "INSERT INTO user_history(user_id, changed_by, field, "
                    "old_value, new_value, note) VALUES(?,?,?,?,?,?)",
                    (uid, u.get("id"), "비밀번호", "***", "***", "비밀번호 재설정")
                )
            except Exception:
                pass
    return RedirectResponse("/admin", 303)


