@app.post("/admin/mail-inbound")
async def admin_mail_inbound_gen(req: Request):
    """새 비밀토큰 생성·저장(app_settings). 기존 토큰은 즉시 무효."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    import secrets
    new_token = secrets.token_urlsafe(32)
    with db_session() as c:
        c.execute(
            "INSERT INTO app_settings(key, value) VALUES(?, ?) "
            "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
            ("mail_inbound_token", new_token))
    return RedirectResponse("/admin/mail-inbound?saved=1", 303)


@app.post("/admin/mail-inbound/bind-me")
async def admin_mail_inbound_bind(req: Request):
    """받는 사람을 '지금 로그인한 본인' 으로 지정 — 운영 DB 동명 계정 혼동 방지.
    ① 기본 수신자 설정 ② test@ 별칭 ③ 이미 들어온 test@ 메일을 내 메일함으로 이동."""
    u = require(req, ["admin", "ceo"])
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        c.execute("INSERT INTO app_settings(key, value) VALUES('mail_default_user_id', ?) "
                  "ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(u["id"]),))
        c.execute("INSERT INTO mail_aliases(address, user_id) VALUES(?, ?) "
                  "ON CONFLICT(address) DO UPDATE SET user_id=excluded.user_id",
                  (_MAIL_POC_ADDR, u["id"]))
        moved = c.execute(
            "UPDATE mail_messages SET user_id=? WHERE to_email=? AND is_deleted=0",
            (u["id"], _MAIL_POC_ADDR)).rowcount
    return RedirectResponse(f"/admin/mail-inbound?bound={moved}", 303)


@app.get("/mail/inbox")
async def mail_inbox_page(req: Request, cat: str = "", q: str = "", star: int = 0, unread: int = 0,
                          df: str = "", dt: str = "", att: int = 0, thread: int = 1, cust: str = ""):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    with db_session() as c:
        mails = _mailbox.list_inbox(c, u["id"], category=cat, q=q,
                                    starred=bool(star), unread=bool(unread),
                                    date_from=df, date_to=dt, has_att=bool(att), cust=cust)
        unread_n = _mailbox.count_unread(c, u["id"])
        cat_counts = _mailbox.category_counts(c, u["id"])
        drafts_n = _mailbox.count_drafts(c, u["id"])
        # C1 거래처 폴더 — 보낸사람→연락처→거래처 매핑 집계(전체·거래처별·미분류). 매핑은 이메일 정확일치만.
        folders = _mailbox.customer_folder_counts(c, u["id"])
    # B1 대화 묶기: 같은 제목(RE/FW 접두 제거) 받은 메일을 한 대화로(기본 ON). thread=0 이면 평면 목록.
    thread_on = bool(thread)
    threads = _mailbox.group_threads(mails) if thread_on else None
    return ctx(req, "mail_inbox.html", user=u, mails=mails, unread=unread_n,
               cat_counts=cat_counts, cur_cat=cat, categories=_MAIL_CATEGORIES, cur_df=df, cur_dt=dt, cur_att=bool(att),
               ai_on=ai_enabled_for(u), q=q, cur_star=bool(star), cur_unread=bool(unread),
               drafts_n=drafts_n, thread_on=thread_on, threads=threads,
               folders=folders, cur_cust=(cust or "").strip())


# ── 메일 = 설치형 앱(PWA) — KNK Eum 처럼 바탕화면/홈 아이콘으로 설치 (대표 지시 2026-06-14) ──
_MAIL_PWA_ICON_CACHE = {}
# =====================================================
# v5H226z422 (대표 지시): KNK Eum WORKS — 설치형 앱(PWA). 시스템 기본 이름 'KNK Eum' 아래
#   WORKS/MAIL/메신저 통일. WORKS도 메일(KNK Eum MAIL)·메신저(KNK Eum)처럼 바탕화면/홈 아이콘·
#   독립 창으로 설치 가능. scope '/' (앱 전체). 아이콘=KNK 빨강 라운드 + 흰 '음'(KNK Eum 정체성).
# =====================================================
#   v5H226z426 (대표 지시): 아이콘이 빨강만 나오는 문제 — NAS 에 한글폰트가 없어 PNG '음' 렌더 실패.
#   → '음'(ㅇ 원 + ㅡ 가로획 + ㅁ 네모)을 **폰트 없이 도형으로** 그림(어느 서버에서나 동일).
_WORKS_PWA_ICON_SVG = (
    "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 512 512'>"
    "<rect width='512' height='512' rx='104' fill='#A5282C'/>"
    "<ellipse cx='256' cy='150' rx='92' ry='68' fill='none' stroke='#fff' stroke-width='26'/>"
    "<rect x='148' y='236' width='216' height='26' rx='13' fill='#fff'/>"
    "<rect x='170' y='292' width='172' height='122' rx='12' fill='none' stroke='#fff' stroke-width='26'/>"
    "</svg>"
)
_WORKS_PWA_ICON_CACHE = {}


def _works_pwa_icon_png(size: int) -> bytes:
    """KNK 빨강 라운드(풀블리드 maskable) + 흰 '음'. 폰트 의존 없이 도형(ㅇ 원·ㅡ 가로획·ㅁ 네모)으로
    그림 → NAS 등 한글폰트 없는 환경에서도 항상 '음'이 보임(폰트 폴백으로 빨강만 나오던 문제 해결)."""
    if size in _WORKS_PWA_ICON_CACHE:
        return _WORKS_PWA_ICON_CACHE[size]
    from PIL import Image, ImageDraw
    import io as _io
    S = size
    W = (255, 255, 255, 255)
    img = Image.new("RGBA", (S, S), (165, 40, 44, 255))   # KNK 빨강 #A5282C 풀블리드
    d = ImageDraw.Draw(img)
    sw = max(3, int(round(S * 0.05)))
    # ㅇ (원/링)
    d.ellipse([int(S * 0.320), int(S * 0.160), int(S * 0.680), int(S * 0.426)], outline=W, width=sw)
    # ㅡ (가로획)
    by = int(S * 0.460)
    d.rounded_rectangle([int(S * 0.289), by, int(S * 0.711), by + sw], radius=sw // 2, fill=W)
    # ㅁ (네모)
    d.rounded_rectangle([int(S * 0.332), int(S * 0.570), int(S * 0.668), int(S * 0.808)],
                        radius=max(2, int(S * 0.024)), outline=W, width=sw)
    buf = _io.BytesIO(); img.save(buf, "PNG")
    data = buf.getvalue(); _WORKS_PWA_ICON_CACHE[size] = data
    return data


