def _purge_cutoff_iso(months) -> str:
    from datetime import datetime, timedelta
    try:
        m = max(1, int(months or 12))
    except Exception:
        m = 12
    return (datetime.now() - timedelta(days=m * 30)).strftime("%Y-%m-%d %H:%M:%S")


