def _pay_days_from_form(form) -> int:
    """v5H226z744 (대표 지시): 결제조건 — 세금계산서 발행 후 N일. 폼 pay_days 에서 숫자만 추출.
    빈칸/비정상=0(미설정). 0~3650일로 제한(오입력 방지)."""
    raw = str(form.get("pay_days") or "").strip()
    digits = "".join(ch for ch in raw if ch.isdigit())
    if not digits:
        return 0
    try:
        n = int(digits)
    except Exception:
        return 0
    return max(0, min(n, 3650))


def _customer_contacts_from_form(form) -> list[dict]:
    """v5H56/v5H66: 폼에서 contact_*_N 패턴으로 다중 담당자 수집.
    v5H66: 'note' (특징) 필드 추가, 'role' 은 hidden 으로 '기타' 기본."""
    indices = sorted({
        int(k.split("_")[-1]) for k in form.keys()
        if k.startswith("contact_name_") and k.split("_")[-1].isdigit()
    })
    out = []
    for idx in indices:
        nm = (form.get(f"contact_name_{idx}") or "").strip()
        if not nm:
            continue
        out.append({
            "role":       (form.get(f"contact_role_{idx}") or "기타").strip(),
            "department": (form.get(f"contact_dept_{idx}") or "").strip(),
            "name":       nm,
            "position":   (form.get(f"contact_position_{idx}") or "").strip(),
            "phone":      (form.get(f"contact_phone_{idx}") or "").strip(),
            "mobile":     (form.get(f"contact_mobile_{idx}") or "").strip(),
            "email":      (form.get(f"contact_email_{idx}") or "").strip(),
            "is_primary": 1 if form.get(f"contact_primary_{idx}") == "1" else 0,
            "note":       (form.get(f"contact_note_{idx}") or "").strip(),
        })
    return out


def _gen_customer_code(c) -> str:
    """v5H226z147: 거래처코드 자동 생성 'C-0001'. 기존 코드의 최대 숫자 +1.
    c = 열린 DB 커넥션/커서. 중복 방지 위해 생성 직후 사용(같은 트랜잭션)."""
    import re as _re
    mx = 0
    try:
        for r in c.execute("SELECT code FROM customers WHERE code IS NOT NULL AND TRIM(code)<>''"):
            m = _re.search(r"(\d+)\s*$", str(r[0] if not hasattr(r, "keys") else r["code"]))
            if m:
                mx = max(mx, int(m.group(1)))
    except Exception:
        pass
    return f"C-{mx + 1:04d}"


