@app.post("/customers/{cid:int}/edit")
async def customers_edit_submit(req: Request, cid: int):
    u = get_user(req)
    if not u:
        return RedirectResponse("/login", 303)
    form = await req.form()
    name = (form.get("name") or "").strip()
    if not name:
        return RedirectResponse(f"/customers/{cid}/edit?error=name_required", status_code=303)
    contacts = _customer_contacts_from_form(form)
    with db_session() as c:
        # v5H112: name 변경 감지 → projects.customer_name 일괄 동기화 + 이력
        # v5H113: 핵심 7필드 전체 변경 이력화
        old_row = c.execute(
            "SELECT name, biz_no, ceo_name, phone, email, address, is_active, note "
            "FROM customers WHERE id=?", (cid,)
        ).fetchone()
        old_data = dict(old_row) if old_row else {}
        old_name = (old_data.get("name") or "")
        # v5H226z619 (대표 지시): 같은 상호라도 종사업장번호가 다르면 별개 사업장으로 허용.
        #   상호 + 종사업장번호가 '모두 같은' 다른 고객사가 있을 때만 중복 차단(500 방지).
        _new_sbn = (form.get("sub_biz_no") or "").strip()
        _dupc = c.execute(
            "SELECT id FROM customers WHERE name=? AND COALESCE(TRIM(sub_biz_no),'')=? AND id<>?",
            (name, _new_sbn, cid)).fetchone()
        if _dupc:
            return RedirectResponse(f"/customers/{cid}/edit?dup=1", status_code=303)
        new_is_active = int(form.get("is_active") or 1)
        new_data = {
            "name": name,
            "alias": (form.get("alias") or "").strip(),   # v5H226z550: 표시용 별칭
            "biz_no": form.get("biz_no", ""),
            "ceo_name": form.get("ceo_name", ""),
            "phone": form.get("phone", ""),
            "email": form.get("email", ""),
            "address": form.get("address", ""),
            "is_active": new_is_active,
            "note": form.get("note", ""),
            # v5H226z147: 추가 사업장 항목
            "business_type": (form.get("business_type") or "").strip(),
            "business_item": (form.get("business_item") or "").strip(),
            "zipcode": (form.get("zipcode") or "").strip(),
            "address_detail": (form.get("address_detail") or "").strip(),
            "fax": (form.get("fax") or "").strip(),
            "sub_biz_no": (form.get("sub_biz_no") or "").strip(),
            # v5H226z203: 해외 고객사 구분 + 국가
            "is_overseas": 1 if (form.get("is_overseas") or "").strip() in ("1", "on", "true", "yes") else 0,
            "country": (form.get("country") or "").strip(),
            # v5H226z744 (대표 지시): 결제조건 — 세금계산서 발행 후 N일
            "pay_days": _pay_days_from_form(form),
        }
        # v5H58: 등급(tier) 은 사용자 입력 받지 않음 — 기존 값 유지, 자동 재계산이 갱신
        c.execute(
            "UPDATE customers SET name=?, alias=?, biz_no=?, ceo_name=?, "
            "phone=?, email=?, address=?, is_active=?, note=?, "
            "business_type=?, business_item=?, zipcode=?, address_detail=?, fax=?, sub_biz_no=?, "
            "is_overseas=?, country=?, pay_days=? "
            "WHERE id=?",
            (new_data["name"], new_data["alias"], new_data["biz_no"], new_data["ceo_name"],
             new_data["phone"], new_data["email"], new_data["address"],
             new_data["is_active"], new_data["note"],
             new_data["business_type"], new_data["business_item"], new_data["zipcode"],
             new_data["address_detail"], new_data["fax"], new_data["sub_biz_no"],
             new_data["is_overseas"], new_data["country"], new_data["pay_days"], cid)
        )
        # v5H226z147: 레거시 거래처(코드 없음)에 코드 보충
        try:
            _cur = c.execute("SELECT code FROM customers WHERE id=?", (cid,)).fetchone()
            _curcode = (_cur["code"] if _cur and hasattr(_cur, "keys") else (_cur[0] if _cur else None))
            if not _curcode or not str(_curcode).strip():
                c.execute("UPDATE customers SET code=? WHERE id=?", (_gen_customer_code(c), cid))
        except Exception:
            pass
        # v5H112: name 변경 시 자식(projects) 동기화
        if old_name and old_name != name:
            try:
                c.execute(
                    "UPDATE projects SET customer_name=? WHERE customer_id=?",
                    (name, cid),
                )
            except Exception:
                pass
        # v5H113: 7필드 모두 diff → customer_history 기록
        _label_map = {
            "name": "고객사명", "biz_no": "사업자번호", "ceo_name": "대표자",
            "phone": "전화", "email": "이메일", "address": "주소",
            "is_active": "활성여부", "note": "비고",
        }
        for _key, _label in _label_map.items():
            ov = old_data.get(_key)
            nv = new_data.get(_key)
            ov_s = "" if ov is None else str(ov)
            nv_s = "" if nv is None else str(nv)
            if ov_s == nv_s:
                continue
            _note = ""
            if _key == "name":
                _note = "고객사명 변경 → projects.customer_name 동기화"
            try:
                c.execute(
                    "INSERT INTO customer_history(customer_id, changed_by, field, "
                    "old_value, new_value, note) VALUES(?,?,?,?,?,?)",
                    (cid, u.get("id"), _label, ov_s, nv_s, _note),
                )
            except Exception:
                pass
        # 담당자: 전체 삭제 후 재삽입 (간단·신뢰)
        c.execute("DELETE FROM customer_contacts WHERE customer_id=?", (cid,))
        for ct in contacts:
            c.execute(
                "INSERT INTO customer_contacts(customer_id, role, department, "
                "name, position, phone, mobile, email, is_primary) "
                "VALUES(?,?,?,?,?,?,?,?,?)",
                (cid, ct["role"], ct["department"], ct["name"], ct["position"],
                 ct["phone"], ct["mobile"], ct["email"], ct["is_primary"])
            )
        # v5H58: 수정 후에도 등급 즉시 재계산
        from . import customer_tier as _ct
        _ct.refresh_customer_tier(c, cid)
    return RedirectResponse(f"/customer/{cid}", status_code=303)


