@app.get("/sales/schedule/diag", response_class=HTMLResponse)
async def schedule_board_diag(request: Request):
    """v5H226z360 (대표 지시·읽기전용 진단): 작업일정표에 사업부별(특히 검사기) 데이터가
    왜 안 뜨는지 운영에서 바로 확인. 사업부별 발주일/납기 채움·관리번호 사업부글자·보드 노출 가능 수 집계.
    수정 없음(SELECT 전용)."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_view_sales(u):
        return RedirectResponse("/home", 303)

    def _esc(s):
        return ("" if s is None else str(s)).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")

    rows, t_dist, t_ym, t_sample = [], [], [], []
    with db_session() as c:
        _notco = "COALESCE(UPPER(project_type),'')!='CONSUMABLE'"
        for bd, label in [("T", "검사기"), ("M", "자동화"), ("L", "라이프밸류"), ("E", "기타")]:
            tot = c.execute(f"SELECT COUNT(*) FROM projects WHERE biz_div=? AND {_notco}", (bd,)).fetchone()[0]
            od = c.execute(f"SELECT COUNT(*) FROM projects WHERE biz_div=? AND {_notco} AND order_date IS NOT NULL AND order_date!=''", (bd,)).fetchone()[0]
            dd = c.execute(f"SELECT COUNT(*) FROM projects WHERE biz_div=? AND {_notco} AND due_date IS NOT NULL AND due_date!=''", (bd,)).fetchone()[0]
            board = c.execute(f"SELECT COUNT(*) FROM projects WHERE biz_div=? AND {_notco} AND ((order_date IS NOT NULL AND order_date!='') OR (due_date IS NOT NULL AND due_date!=''))", (bd,)).fetchone()[0]
            mgmt_ok = c.execute(f"SELECT COUNT(*) FROM projects WHERE biz_div=? AND {_notco} AND substr(mgmt_code,4,1)=?", (bd, bd)).fetchone()[0]
            mgmt_bad = tot - mgmt_ok
            rows.append((label, bd, tot, od, dd, board, mgmt_ok, mgmt_bad))
        t_dist = c.execute("SELECT COALESCE(NULLIF(substr(mgmt_code,4,1),''),'(빈칸/형식이상)') ch, COUNT(*) n FROM projects WHERE biz_div='T' GROUP BY ch ORDER BY n DESC").fetchall()
        t_ym = c.execute("SELECT COALESCE(NULLIF(substr(order_date,1,7),''),'(발주일 없음)') ym, COUNT(*) n FROM projects WHERE biz_div='T' GROUP BY ym ORDER BY n DESC LIMIT 18").fetchall()
        t_sample = c.execute("SELECT mgmt_code, order_date, due_date, name, status FROM projects WHERE biz_div='T' ORDER BY id DESC LIMIT 12").fetchall()

    # 결론 자동 판정 (검사기 기준)
    _t = next((r for r in rows if r[1] == "T"), None)
    concl = []
    if _t:
        _label, _bd, _tot, _od, _dd, _board, _mok, _mbad = _t
        if _tot == 0:
            concl.append("검사기(biz_div=T) 프로젝트가 0건 — 이 화면 기준엔 검사기 데이터가 없습니다(소모품 제외).")
        else:
            if _board == 0:
                concl.append(f"🔴 <b>원인 1 확정</b>: 검사기 {_tot}건 전부 <b>발주일·납기가 비어 있음</b> → 작업일정표(발주일 기준)에 한 건도 안 뜸. (수주(SO)엔 날짜가 있어도 <b>프로젝트 레코드</b>에 없으면 보드는 못 띄움)")
            elif _board < _tot:
                concl.append(f"🟠 검사기 {_tot}건 중 <b>{_tot - _board}건은 발주일·납기가 비어</b> 보드에 안 뜸. {_board}건만 노출 가능.")
            if _mbad > 0:
                concl.append(f"🔴 <b>원인 2</b>: 검사기 {_mbad}건은 <b>관리번호 4번째 글자가 'T'가 아님</b> → 보드가 검사기로 분류 못 함(검사기 탭에서 누락).")
            if _board > 0 and _mbad == 0:
                concl.append(f"🟢 검사기 {_board}건은 발주일/납기·관리번호 정상 → 해당 <b>발주월</b>로 이동하면 보드에 보입니다(아래 '발주일 월 분포' 참고).")
    concl_html = "".join(f"<li>{x}</li>" for x in concl) or "<li>판정 데이터 부족</li>"

    body = [
        "<meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1.0'>",  # v5H226z361: 휴대폰 정상 표시
        "<div style='font-family:Pretendard,system-ui,sans-serif;max-width:980px;margin:24px auto;padding:0 18px;color:#1f2937;'>",
        "<h1 style='font-size:22px;'>🔎 작업일정표 데이터 진단 — 사업부별 노출 가능 여부</h1>",
        "<p style='color:#666;font-size:13px;'>작업일정표는 <b>프로젝트의 발주일~납기가 그 달과 겹치는 건만</b> 표시하고, <b>관리번호 4번째 글자</b>로 사업부를 분류합니다. (읽기전용·수정 없음)</p>",
        "<table style='border-collapse:collapse;width:100%;font-size:13px;margin:10px 0 18px;'>",
        "<thead><tr style='background:#eef3fa;'>",
        "<th style='padding:8px;border:1px solid #d4e2f2;text-align:left;'>사업부</th>",
        "<th style='padding:8px;border:1px solid #d4e2f2;'>전체</th>",
        "<th style='padding:8px;border:1px solid #d4e2f2;'>발주일 있음</th>",
        "<th style='padding:8px;border:1px solid #d4e2f2;'>납기 있음</th>",
        "<th style='padding:8px;border:1px solid #d4e2f2;'>보드 노출 가능<br><span style='font-weight:400;font-size:11px;'>(발주일 또는 납기 有)</span></th>",
        "<th style='padding:8px;border:1px solid #d4e2f2;'>관리번호 정상<br><span style='font-weight:400;font-size:11px;'>(4번째=사업부)</span></th>",
        "<th style='padding:8px;border:1px solid #d4e2f2;'>관리번호 이상</th>",
        "</tr></thead><tbody>",
    ]
    for (label, bd, tot, od, dd, board, mok, mbad) in rows:
        body.append(
            f"<tr><td style='padding:8px;border:1px solid #e3e8ef;'><b>{_esc(label)}({bd})</b></td>"
            f"<td style='padding:8px;border:1px solid #e3e8ef;text-align:center;'>{tot}</td>"
            f"<td style='padding:8px;border:1px solid #e3e8ef;text-align:center;'>{od}</td>"
            f"<td style='padding:8px;border:1px solid #e3e8ef;text-align:center;'>{dd}</td>"
            f"<td style='padding:8px;border:1px solid #e3e8ef;text-align:center;font-weight:700;color:{'#c33' if board == 0 and tot > 0 else '#1f2937'};'>{board}</td>"
            f"<td style='padding:8px;border:1px solid #e3e8ef;text-align:center;'>{mok}</td>"
            f"<td style='padding:8px;border:1px solid #e3e8ef;text-align:center;color:{'#c33' if mbad else '#999'};font-weight:{'700' if mbad else '400'};'>{mbad}</td></tr>")
    body.append("</tbody></table>")
    body.append("<div style='background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;padding:14px 18px;margin-bottom:18px;'>")
    body.append("<b style='font-size:15px;'>📌 판정</b><ul style='margin:8px 0 0;padding-left:20px;line-height:1.8;font-size:13.5px;'>" + concl_html + "</ul></div>")
    body.append("<h3 style='font-size:15px;'>검사기(T) — 관리번호 4번째 글자 분포</h3><div style='font-size:13px;color:#444;'>")
    body.append(" · ".join(f"<b>{_esc(r[0])}</b>={r[1]}건" for r in t_dist) or "(없음)")
    body.append("</div><h3 style='font-size:15px;margin-top:14px;'>검사기(T) — 발주일 월 분포</h3><div style='font-size:13px;color:#444;'>")
    body.append(" · ".join(f"<b>{_esc(r[0])}</b>={r[1]}건" for r in t_ym) or "(없음)")
    body.append("</div><h3 style='font-size:15px;margin-top:14px;'>검사기(T) 최근 12건 샘플</h3>")
    body.append("<table style='border-collapse:collapse;width:100%;font-size:12px;'><thead><tr style='background:#f4f5f7;'>"
                "<th style='padding:5px;border:1px solid #e3e8ef;'>관리번호</th><th style='padding:5px;border:1px solid #e3e8ef;'>발주일</th>"
                "<th style='padding:5px;border:1px solid #e3e8ef;'>납기</th><th style='padding:5px;border:1px solid #e3e8ef;'>상태</th>"
                "<th style='padding:5px;border:1px solid #e3e8ef;text-align:left;'>프로젝트명</th></tr></thead><tbody>")
    for r in t_sample:
        body.append(
            f"<tr><td style='padding:5px;border:1px solid #eee;font-family:monospace;'>{_esc(r['mgmt_code'])}</td>"
            f"<td style='padding:5px;border:1px solid #eee;text-align:center;color:{'#c33' if not r['order_date'] else '#1f2937'};'>{_esc(r['order_date']) or '(없음)'}</td>"
            f"<td style='padding:5px;border:1px solid #eee;text-align:center;color:{'#c33' if not r['due_date'] else '#1f2937'};'>{_esc(r['due_date']) or '(없음)'}</td>"
            f"<td style='padding:5px;border:1px solid #eee;text-align:center;'>{_esc(r['status'])}</td>"
            f"<td style='padding:5px;border:1px solid #eee;'>{_esc(r['name'])}</td></tr>")
    body.append("</tbody></table>")
    body.append("<p style='color:#999;font-size:12px;margin-top:18px;'>※ 이 페이지는 읽기전용 진단용입니다. 빅터에게 위 '판정' 내용을 알려주시면 바로 해결하겠습니다.</p></div>")
    return HTMLResponse("".join(body))


# v5H226z270 (대표 지시): 작업 일정표 단계 파이프라인 — 패널 조회 + 단계 저장.
#   누구나 클릭(로그인만) · 누른 사람 기록 · 단계 화이트리스트 · tax_invoice(금액)는 can_view_sales 만.
def _sched_user_name(u: dict) -> str:
    return (u.get("name") or u.get("username") or u.get("login_id") or "").strip()


@app.post("/sales/schedule/bulk-ship")
async def schedule_board_bulk_ship(request: Request):
    """v5H226z472/z571 (대표 지시): 일괄출하 — 체크한 여러 행을 오늘 날짜로 '출하(납품완료)' 처리.
    로그인이면 누구나. (kind, ref_id) 중복 제거(호기 분할로 같은 건이 여러 줄일 수 있음).
    z571: 단계 시스템 제거 — 단계 거울 없이 실제 출하(호기 납품완료/소모품 SHIPPED)만 수행."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    try:
        b = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_json"}, 400)
    items = b.get("items") or []
    if not isinstance(items, list) or not items:
        return JSONResponse({"ok": False, "error": "출하 처리할 대상이 없습니다"}, 400)
    from datetime import date as _date_z472
    on_date = _date_z472.today().isoformat()   # 서버(본사 KST) 오늘 — 보드 today_day 와 동일 기준
    uid = u.get("id")
    uname = _sched_user_name(u)
    done_keys = set()
    n_ok = 0
    n_fail = 0
    for it in items[:500]:   # 안전 상한
        try:
            kind = (str(it.get("kind") or "")).strip()
            ref_id = int(it.get("ref_id"))
        except Exception:
            n_fail += 1
            continue
        if kind not in ("project", "consumable") or not ref_id:
            n_fail += 1
            continue
        key = (kind, ref_id)
        if key in done_keys:
            continue   # v5H226z472: 중복(같은 건 여러 줄) 제거
        # v5H226z571 (대표 지시): 단계 시스템 제거 — 일괄출하는 '실제 출하'만 수행(단계 거울 폐지).
        #   프로젝트=호기 전체 납품완료(mark_units_delivered·cascade), 소모품=consumable_orders.status='SHIPPED'.
        ok = False
        try:
            if kind == "project":
                with db_session() as _cz:
                    _pwf.mark_units_delivered(_cz, ref_id, uid)
                ok = True
            elif kind == "consumable":
                with db_session() as _cz:
                    _cz.execute("UPDATE consumable_orders SET status='SHIPPED' WHERE id=?", (ref_id,))
                ok = True
        except Exception:
            ok = False
        if ok:
            done_keys.add(key)
            n_ok += 1
        else:
            n_fail += 1
    return JSONResponse({"ok": n_ok > 0, "n": n_ok, "fail": n_fail,
                         "on_date": on_date,
                         "error": ("" if n_ok > 0 else "모두 실패")})


@app.get("/sales/schedule/units")
async def schedule_board_units(request: Request, ref_id: int, kind: str = "project", uids: str = "", so_no: str = ""):
    """v5H226z481 (대표 지시): 작업일정표 행 펼치기 — 한 프로젝트의 호기(order_items) 목록(상태·납기·단가) JSON.
    v5H226z624 (대표 지시): 같은 관리번호에 수주번호(SO)가 여러 개면, 펼침은 '그 행의 수주번호' 호기만 보여야 함
      (수량과 일치). 분할(uids) 줄은 그대로, 분할 안 된 행은 so_no(order_no)로 그 SO 호기만 조회 → 다른 SO 혼입 방지.
    v5H226z509 (대표 지시): 같은 관리번호라도 수주번호가 다른 호기는 따로 — 분할(호기) 줄을 펼치면
      그 줄의 호기(uids=order_items.id CSV)만 반환해 서로 다른 수주번호가 한 줄 펼침에 섞이지 않게 한다.
      uids 없으면(분할 안 된 일반 프로젝트) 기존대로 프로젝트 전체 호기."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    can_money = bool(can_view_field(u, "sales_amount"))   # v5H226z823: 호기 펼침의 단가·금액·세금계산서 = 매출금액 열람정책(정적 표와 동일 게이트)
    # v5H226z509: 분할 줄이 보낸 호기 id 화이트리스트(정수만) — IN (...) 으로 그 줄 호기만 조회
    _uid_list = []
    for _x in (uids or "").split(","):
        _x = _x.strip()
        if _x.isdigit():
            _uid_list.append(int(_x))
    units = []
    try:
        with db_session() as c:
            _cols = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
            _due = "oi.due_date AS i_due," if "due_date" in _cols else "'' AS i_due,"
            _ust = "oi.unit_status AS ust," if "unit_status" in _cols else "'진행중' AS ust,"
            _up = "oi.unit_price AS up," if "unit_price" in _cols else "oi.amount AS up,"
            # v5H226z483 (대표 지시): 상세(수주 내역)와 동일 정보량 — 발주일·납품처·거래방식·통화·비고 추가
            _od = "oi.order_date AS i_ord," if "order_date" in _cols else "'' AS i_ord,"
            _sh = "oi.ship_to AS i_ship," if "ship_to" in _cols else "'' AS i_ship,"
            _ie = "oi.is_export AS i_iex," if "is_export" in _cols else "NULL AS i_iex,"
            _ln = "oi.line_note AS lnote," if "line_note" in _cols else "'' AS lnote,"
            _ic = "oi.currency AS i_cur," if "currency" in _cols else "'' AS i_cur,"
            # v5H226z484 (대표 지시): 호기별 거래명세서·세금계산서(발행일+금액)
            _stm = "oi.statement_date AS stmt," if "statement_date" in _cols else "'' AS stmt,"
            _ti1 = "oi.tax_invoice_date AS t1d, oi.tax_invoice_amt1 AS t1a," if "tax_invoice_date" in _cols else "'' AS t1d, NULL AS t1a,"
            _ti2 = "oi.tax_invoice_date2 AS t2d, oi.tax_invoice_amt2 AS t2a," if "tax_invoice_date2" in _cols else "'' AS t2d, NULL AS t2a,"
            _ti3 = "oi.tax_invoice_date3 AS t3d, oi.tax_invoice_amt3 AS t3a," if "tax_invoice_date3" in _cols else "'' AS t3d, NULL AS t3a,"
            # v5H226z624: 펼침 범위 — 분할(uids) 우선, 없으면 그 행의 수주번호(so_no=order_no)로 한정. 둘 다 없으면 프로젝트 전체(기존)
            _so_filt = (so_no or "").strip()
            _params = [int(ref_id)]
            if _uid_list:
                _wx = f"AND oi.id IN ({','.join(str(_i) for _i in _uid_list)}) "
            elif _so_filt:
                _wx = "AND o.order_no=? "
                _params.append(_so_filt)
            else:
                _wx = ""
            rows = c.execute(
                f"SELECT oi.id AS iid, oi.unit_label AS lbl, {_due} {_ust} {_up} {_od} {_sh} {_ie} {_ln} {_ic} "
                f"{_stm} {_ti1} {_ti2} {_ti3} "
                f"oi.amount AS amt, COALESCE(oi.qty,1) AS qty, "
                f"o.order_no AS so_no, o.due_date AS o_due, o.order_date AS o_ord, o.ship_to AS o_ship, "
                f"COALESCE(o.statement_date,'') AS o_stmt, "   # v5H226z559: 거래명세서 발행일 대표 SO 폴백
                f"COALESCE(o.currency,'KRW') AS o_cur, COALESCE(o.status,'') AS sost, "
                f"COALESCE(p.is_export,0) AS p_iex "
                f"FROM order_items oi JOIN orders o ON oi.order_id=o.id "
                f"LEFT JOIN projects p ON p.id=o.project_id "
                f"WHERE o.project_id=? AND COALESCE(o.status,'')<>'CANCELLED' "
                # v5H226z509/z624: 분할 줄은 호기 id(uids)로, 분할 안 된 행은 그 행의 수주번호(so_no=order_no)로
                #   스코프 → 같은 관리번호의 다른 SO 호기가 펼침에 섞이지 않게(수량 일치).
                + _wx
                + "ORDER BY oi.id",
                tuple(_params)).fetchall()
            for r in rows:
                d = dict(r)
                eff_due = (str(d.get("i_due") or "").strip() or str(d.get("o_due") or "").strip())[:10]
                eff_ord = (str(d.get("i_ord") or "").strip() or str(d.get("o_ord") or "").strip())[:10]
                eff_ship = (str(d.get("i_ship") or "").strip() or str(d.get("o_ship") or "").strip())
                eff_cur = (str(d.get("i_cur") or "").strip() or str(d.get("o_cur") or "").strip() or "KRW")
                _iex = d.get("i_iex")
                eff_iex = int(_iex) if _iex is not None else int(d.get("p_iex") or 0)
                _ud = {
                    "iid": d["iid"], "label": d.get("lbl") or "—",
                    "due_date": eff_due, "order_date": eff_ord, "ship_to": eff_ship or "",
                    "unit_status": d.get("ust") or "진행중",
                    "unit_price": (float(d.get("up") or 0) if can_money else None),
                    "amount": (float(d.get("amt") or 0) if can_money else None),
                    "currency": eff_cur, "is_export": eff_iex, "note": d.get("lnote") or "",
                    "so_no": d.get("so_no") or "",
                    "locked": ((d.get("sost") or "").upper() in ("INVOICED", "PAID")),
                }
                if can_money:   # v5H226z484: 거래명세서·세금계산서(호기별)는 청구성격 → 영업·관리만
                    def _amt(v):
                        return (float(v) if v not in (None, "") else "")
                    _ud.update({
                        # v5H226z559: 거래명세서 발행일 — 호기 자체값 없으면 대표 SO 값으로 폴백
                        "statement_date": str(d.get("stmt") or d.get("o_stmt") or "")[:10],
                        "tax_invoice_date": str(d.get("t1d") or "")[:10], "tax_invoice_amt1": _amt(d.get("t1a")),
                        "tax_invoice_date2": str(d.get("t2d") or "")[:10], "tax_invoice_amt2": _amt(d.get("t2a")),
                        "tax_invoice_date3": str(d.get("t3d") or "")[:10], "tax_invoice_amt3": _amt(d.get("t3a")),
                    })
                units.append(_ud)
            # v5H226z662 (대표 지시·A안): 세금계산서/거래명세서 폴백(묶음 균등분배 + orders 폴백)을
            #   공유 헬퍼로 — 수주내역 상세(_enrich_units_tax)와 '같은 코드'로 채워 두 화면 항상 일치.
            if kind == "project":
                _enrich_units_tax(c, ref_id, units, can_money, iid_key="iid")
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:160]}, 500)
    return JSONResponse({"ok": True, "units": units, "can_money": can_money,
                         "statuses": list(UNIT_STATUSES)})   # v5H226z482: UNIT_STATUSES는 main 전역(_logi 아님)


@app.get("/sales/schedule/consumable-items")
async def schedule_board_consumable_items(request: Request, ref_id: int):
    """v5H226z510 (대표 지시): 작업일정표 소모품 행 펼치기 — 그 소모품(consumable_orders)에 등록된
      품목(consumable_order_items) 리스트를 읽기전용 JSON 으로. 단가·금액은 영업·관리(can_money)만.
      편집은 소모품 상세(/consumables/{id})에서. (호기 펼침과 짝 — 소모품은 리스트 보기 전용)"""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    can_money = bool(can_view_field(u, "sales_amount"))   # v5H226z823: 소모품 품목 펼침의 단가·금액 = 매출금액 열람정책
    items = []
    try:
        from . import consumables as _co
        for it in _co.coi_list(int(ref_id)):
            _d = {
                "id": it.get("id"),
                "part_name": it.get("part_name") or "",
                "model_use": it.get("model_use") or "",
                "equip_name": it.get("equip_name") or "",
                "spec": it.get("spec") or "",
                "qty": (float(it.get("qty")) if it.get("qty") not in (None, "") else None),
                "unit": it.get("unit") or "",
                "note": it.get("note") or "",
                "part_no": it.get("part_no") or "",
                "linked_mgmt_code": it.get("linked_mgmt_code") or "",
                "linked_project_id": it.get("linked_project_id") or None,
                "image_thumb_path": it.get("image_thumb_path") or it.get("image_loc_thumb_path") or "",
                "image_path": it.get("image_path") or it.get("image_loc_path") or "",
            }
            if can_money:   # 단가·금액은 청구성격 → 영업·관리만
                _d["unit_price"] = (float(it.get("unit_price")) if it.get("unit_price") not in (None, "") else None)
                _d["amount"] = (float(it.get("amount")) if it.get("amount") not in (None, "") else None)
            items.append(_d)
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:160]}, 500)
    return JSONResponse({"ok": True, "items": items, "can_money": can_money})


@app.post("/sales/schedule/unit-field")
async def schedule_board_unit_field(request: Request):
    """v5H226z481 (대표 지시): 펼친 호기 줄 인라인 수정 — 상태/납기/단가 1필드. can_use_sales(단가는 can_view_sales).
    상태=cascade(출하↔납품·단계 연동)·단가=SO 합계·프로젝트 금액 자가치유(편집 엔드포인트와 동일)."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    try:
        b = await request.json()
        iid = int(b.get("iid"))
    except Exception:
        return JSONResponse({"ok": False, "error": "bad_request"}, 400)
    field = (b.get("field") or "").strip()
    value = b.get("value")
    # v5H226z483/z484 (대표 지시): 발주일·납품처·통화·거래방식·비고 + 호기별 거래명세서·세금계산서(발행일+금액)
    _TAX_FIELDS = ("statement_date", "tax_invoice_date", "tax_invoice_amt1",
                   "tax_invoice_date2", "tax_invoice_amt2", "tax_invoice_date3", "tax_invoice_amt3")
    if field not in (("status", "due_date", "unit_price", "qty", "amount", "order_date", "ship_to", "currency", "is_export", "note") + _TAX_FIELDS):
        return JSONResponse({"ok": False, "error": "bad_field"}, 400)
    # 단가·수량·금액(청구 성격)·거래명세서·세금계산서는 영업·관리만
    if (field in ("unit_price", "qty", "amount") or field in _TAX_FIELDS) and not can_view_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    try:
        with db_session() as c:
            it = c.execute(
                "SELECT oi.order_id, COALESCE(oi.qty,1) AS qty, oi.unit_label, "
                "o.project_id, COALESCE(o.status,'') AS sost, o.order_no "
                "FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.id=?", (iid,)).fetchone()
            if not it:
                return JSONResponse({"ok": False, "error": "not_found"}, 404)
            it = dict(it)
            if (it.get("sost") or "").upper() in ("INVOICED", "PAID", "CANCELLED"):
                return JSONResponse({"ok": False, "error": f"{it['sost']} 상태 SO 는 수정 불가"}, 400)
            pid = it.get("project_id")
            if field == "status":
                ns = (value or "").strip()
                if ns not in UNIT_STATUSES:   # v5H226z482: UNIT_STATUSES는 main 전역(_logi 아님)
                    return JSONResponse({"ok": False, "error": "허용 안 된 상태"}, 400)
                c.execute("UPDATE order_items SET unit_status=?, updated_at=datetime('now','localtime') WHERE id=?", (ns, iid))
                try:
                    _logi.log_project_change(c, pid, u.get("id"), f"호기 상태({it.get('unit_label') or '—'})",
                                             "", ns, note=f"SO {it.get('order_no')} · 일정표 펼침 인라인")
                except Exception:
                    pass
                try:
                    _pwf.cascade_unit_status_to_project(c, pid, u.get("id"))
                except Exception:
                    pass
            elif field == "due_date":
                dv = (str(value or "").strip() or None)
                c.execute("UPDATE order_items SET due_date=?, updated_at=datetime('now','localtime') WHERE id=?", (dv, iid))
            elif field == "unit_price":
                try:
                    up = float(str(value).replace(",", "")) if value not in (None, "") else 0.0
                except Exception:
                    return JSONResponse({"ok": False, "error": "단가 형식 오류"}, 400)
                qty = float(it.get("qty") or 1) or 1
                c.execute("UPDATE order_items SET unit_price=?, amount=?, updated_at=datetime('now','localtime') WHERE id=?",
                          (up, up * qty, iid))
                oid = it.get("order_id")
                rws = c.execute("SELECT amount FROM order_items WHERE order_id=?", (oid,)).fetchall()
                new_total = sum(float((r[0] if isinstance(r, tuple) else r["amount"]) or 0) for r in rws)
                c.execute("UPDATE orders SET total_amount=?, updated_at=datetime('now','localtime') WHERE id=?", (new_total, oid))
                if pid:
                    row = c.execute("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE project_id=?", (pid,)).fetchone()
                    c.execute("UPDATE projects SET order_amount=? WHERE id=?", (float(row[0] or 0), pid))
            elif field == "amount":
                # v5H226z669 (대표 지시·폭주 버그 수정): 금액 직접 저장 + 단가=금액÷그 호기 qty(서버 권위)로 역산.
                #   클라는 '행 금액÷묶인 호기수'로 분배해 보냄. 단가↔금액이 서로 역연산이라 반복 클릭에도 값이 안 커짐
                #   (기존: 금액편집이 클라 data-qty로 나누고 서버가 호기 qty로 곱해, 둘이 어긋나면 클릭마다 배수 폭주).
                try:
                    av = float(str(value).replace(",", "")) if value not in (None, "") else 0.0
                except Exception:
                    return JSONResponse({"ok": False, "error": "금액 형식 오류"}, 400)
                qv = float(it.get("qty") or 1) or 1
                c.execute("UPDATE order_items SET amount=?, unit_price=?, updated_at=datetime('now','localtime') WHERE id=?",
                          (av, av / qv, iid))
                oid = it.get("order_id")
                rws = c.execute("SELECT amount FROM order_items WHERE order_id=?", (oid,)).fetchall()
                new_total = sum(float((r[0] if isinstance(r, tuple) else r["amount"]) or 0) for r in rws)
                c.execute("UPDATE orders SET total_amount=?, updated_at=datetime('now','localtime') WHERE id=?", (new_total, oid))
                if pid:
                    row = c.execute("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE project_id=?", (pid,)).fetchone()
                    c.execute("UPDATE projects SET order_amount=? WHERE id=?", (float(row[0] or 0), pid))
            elif field == "qty":
                # v5H226z666 (대표 지시): 수량 — 호기 qty + 금액(단가×수량) 갱신 + SO·프로젝트 금액 자가치유(단가와 동일 경로).
                try:
                    q = float(str(value).replace(",", "")) if value not in (None, "") else 0.0
                except Exception:
                    return JSONResponse({"ok": False, "error": "수량 형식 오류"}, 400)
                if q <= 0:
                    q = 1.0
                _uprow = c.execute("SELECT COALESCE(unit_price,0) FROM order_items WHERE id=?", (iid,)).fetchone()
                _up = float((_uprow[0] if _uprow else 0) or 0)
                c.execute("UPDATE order_items SET qty=?, amount=?, updated_at=datetime('now','localtime') WHERE id=?",
                          (q, _up * q, iid))
                oid = it.get("order_id")
                rws = c.execute("SELECT amount FROM order_items WHERE order_id=?", (oid,)).fetchall()
                new_total = sum(float((r[0] if isinstance(r, tuple) else r["amount"]) or 0) for r in rws)
                c.execute("UPDATE orders SET total_amount=?, updated_at=datetime('now','localtime') WHERE id=?", (new_total, oid))
                if pid:
                    row = c.execute("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE project_id=?", (pid,)).fetchone()
                    c.execute("UPDATE projects SET order_amount=? WHERE id=?", (float(row[0] or 0), pid))
            elif field == "order_date":
                c.execute("UPDATE order_items SET order_date=?, updated_at=datetime('now','localtime') WHERE id=?",
                          (str(value or "").strip() or None, iid))
            elif field == "ship_to":
                c.execute("UPDATE order_items SET ship_to=?, updated_at=datetime('now','localtime') WHERE id=?",
                          (str(value or "").strip() or None, iid))
            elif field == "note":
                c.execute("UPDATE order_items SET line_note=?, updated_at=datetime('now','localtime') WHERE id=?",
                          (str(value or "").strip() or None, iid))
            elif field == "currency":
                cv = str(value or "").strip().upper()
                if cv not in ("KRW", "USD", "VND", "JPY", "CNY", "EUR"):
                    return JSONResponse({"ok": False, "error": "통화 형식 오류"}, 400)
                c.execute("UPDATE order_items SET currency=?, updated_at=datetime('now','localtime') WHERE id=?", (cv, iid))
            elif field == "is_export":
                iv = 1 if str(value).strip() in ("1", "수출", "true", "True") else 0
                c.execute("UPDATE order_items SET is_export=?, updated_at=datetime('now','localtime') WHERE id=?", (iv, iid))
            elif field in ("statement_date", "tax_invoice_date", "tax_invoice_date2", "tax_invoice_date3"):
                # v5H226z484: 호기별 발행일(화이트리스트 필드명이라 f-string 안전)
                c.execute(f"UPDATE order_items SET {field}=?, updated_at=datetime('now','localtime') WHERE id=?",
                          (str(value or "").strip() or None, iid))
            elif field in ("tax_invoice_amt1", "tax_invoice_amt2", "tax_invoice_amt3"):
                try:
                    av = float(str(value).replace(",", "")) if value not in (None, "") else None
                except Exception:
                    return JSONResponse({"ok": False, "error": "금액 형식 오류"}, 400)
                c.execute(f"UPDATE order_items SET {field}=?, updated_at=datetime('now','localtime') WHERE id=?", (av, iid))
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:160]}, 500)
    return JSONResponse({"ok": True})


@app.post("/sales/schedule/row-status")
async def schedule_board_row_status(request: Request):
    """v5H226z711 (대표 지시): 작업일정표 달력에서 날짜 클릭 → 상태(진행중/출하/취소/보류) 선택.
    그 행(수주)의 호기(order_items) 전체에 unit_status + status_date(발생일) 적용 + cascade(상세·색 동기화).
    소모품 행은 호기 개념이 없어 이 경로 미지원(소모품 상세에서 변경). 확정(송장/수금/취소) SO 호기는 보호."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    try:
        b = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "bad_request"}, 400)
    kind = (b.get("kind") or "project").strip()
    status = (b.get("value") or b.get("status") or "").strip()
    sdate = (str(b.get("date") or "").strip() or None)
    if status not in UNIT_STATUSES:
        return JSONResponse({"ok": False, "error": "허용 안 된 상태"}, 400)
    if status == "진행중":
        sdate = None   # 되돌리기 = 발생일(이벤트) 해제
    if kind != "project":
        return JSONResponse({"ok": False, "error": "소모품 상태는 소모품 상세에서 변경하세요"}, 400)
    uids = b.get("uids") or []
    ref_id = b.get("ref_id")
    try:
        with db_session() as c:
            ids = []
            if uids:
                ids = [int(x) for x in uids if str(x).strip().isdigit()]
            elif ref_id:
                ids = [int(r[0]) for r in c.execute(
                    "SELECT oi.id FROM order_items oi JOIN orders o ON o.id=oi.order_id "
                    "WHERE o.project_id=? AND COALESCE(o.status,'')<>'CANCELLED'", (int(ref_id),)).fetchall()]
            if not ids:
                return JSONResponse({"ok": False, "error": "대상 호기가 없습니다"}, 404)
            _ph = ",".join("?" * len(ids))
            # 확정(송장/수금/취소) SO 호기는 보호 — /unit-field 와 동일 정책
            _blocked = {int(r[0]) for r in c.execute(
                f"SELECT oi.id FROM order_items oi JOIN orders o ON o.id=oi.order_id "
                f"WHERE oi.id IN ({_ph}) AND UPPER(COALESCE(o.status,'')) IN ('INVOICED','PAID','CANCELLED')", ids).fetchall()}
            _apply = [i for i in ids if i not in _blocked]
            if not _apply:
                return JSONResponse({"ok": False, "error": "확정(송장/수금/취소) SO 호기는 상태 변경 불가"}, 400)
            _ph2 = ",".join("?" * len(_apply))
            c.execute(f"UPDATE order_items SET unit_status=?, status_date=?, updated_at=datetime('now','localtime') WHERE id IN ({_ph2})",
                      [status, sdate] + _apply)
            _pids = {int(r[0]) for r in c.execute(
                f"SELECT DISTINCT o.project_id FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.id IN ({_ph2})", _apply).fetchall() if r[0]}
            for _pid in _pids:
                try:
                    _pwf.cascade_unit_status_to_project(c, _pid, u.get("id"))
                except Exception:
                    pass
                try:
                    _logi.log_project_change(c, _pid, u.get("id"), "호기 상태(일정표 달력)",
                                             "", f"{status}{(' · ' + sdate) if sdate else ''}", note="작업일정표 달력 클릭")
                except Exception:
                    pass
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:160]}, 500)
    return JSONResponse({"ok": True, "count": len(_apply), "status": status, "date": sdate or "",
                         "skipped": len(_blocked)})


@app.post("/sales/schedule/row-tax")
async def schedule_board_row_tax(request: Request):
    """v5H226z562 (대표 지시): 메인 행 세금계산서·거래명세서 편집 = 그 줄의 호기(order_items) 전체에 적용.
    세금계산서 단일 진실=호기. 분할 줄은 uids(그 호기들), 분할 안 된 프로젝트는 그 프로젝트 전체 호기.
    날짜·거래명세서=호기 전체 동일 적용 / 금액=호기 수로 균등 분배(합계=입력값). 펼침 호기별 편집과 단일 진실 일치.
    (소모품은 호기 개념이 없어 기존 /sales/schedule/cell 로 처리 — 여기선 프로젝트만)."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_view_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    try:
        b = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_json"}, 400)
    ref_id = b.get("ref_id")
    field = (b.get("field") or "").strip()
    value = b.get("value") or ""
    uids = b.get("uids") or ""
    _DATE_F = ("statement_date", "tax_invoice_date", "tax_invoice_date2", "tax_invoice_date3")
    _AMT_F = ("tax_invoice_amt1", "tax_invoice_amt2", "tax_invoice_amt3")
    if field not in (_DATE_F + _AMT_F):
        return JSONResponse({"ok": False, "error": "허용되지 않은 필드"}, 400)
    try:
        _uid_list = [int(x) for x in str(uids).split(",") if str(x).strip().isdigit()]
    except Exception:
        _uid_list = []
    try:
        with db_session() as c:
            _oic = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
            if field not in _oic:
                return JSONResponse({"ok": False, "error": f"order_items.{field} 컬럼 없음"}, 400)
            # 대상 호기 결정: uids(분할 줄) 우선, 없으면 그 프로젝트 전체 호기(취소 SO 제외)
            if _uid_list:
                _ph = ",".join("?" * len(_uid_list))
                tgt = c.execute(
                    f"SELECT oi.id FROM order_items oi JOIN orders o ON o.id=oi.order_id "
                    f"WHERE oi.id IN ({_ph}) AND COALESCE(o.status,'')<>'CANCELLED'", _uid_list).fetchall()
            else:
                tgt = c.execute(
                    "SELECT oi.id FROM order_items oi JOIN orders o ON o.id=oi.order_id "
                    "WHERE o.project_id=? AND COALESCE(o.status,'')<>'CANCELLED' ORDER BY oi.id", (int(ref_id),)).fetchall()
            ids = [int(r[0]) for r in tgt]
            if not ids:
                return JSONResponse({"ok": False, "error": "이 줄에 연결된 호기(수주 품목)가 없습니다"}, 400)
            if field in _DATE_F:
                dv = (str(value or "").strip() or None)   # 빈값=발행 취소(NULL)
                _ph = ",".join("?" * len(ids))
                c.execute(f"UPDATE order_items SET {field}=?, updated_at=datetime('now','localtime') WHERE id IN ({_ph})",
                          [dv] + ids)
            else:
                # 금액 = 입력값을 호기 수로 균등 분배(합계 보존). 빈값=NULL(발행 취소)
                _raw = str(value).replace(",", "").strip()
                if _raw == "":
                    _ph = ",".join("?" * len(ids))
                    c.execute(f"UPDATE order_items SET {field}=NULL, updated_at=datetime('now','localtime') WHERE id IN ({_ph})", ids)
                else:
                    try:
                        total = float(_raw)
                    except Exception:
                        return JSONResponse({"ok": False, "error": "금액 형식 오류"}, 400)
                    n = len(ids)
                    share = round(total / n, 2)
                    # 반올림 잔차는 첫 호기에 몰아 정확히 합계 보존
                    rem = round(total - share * n, 2)
                    for _i, _iid in enumerate(ids):
                        _v = share + (rem if _i == 0 else 0)
                        c.execute("UPDATE order_items SET %s=?, updated_at=datetime('now','localtime') WHERE id=?" % field,
                                  (_v, _iid))
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:160]}, 500)
    return JSONResponse({"ok": True, "n": len(ids)})


# ─── v5H226z488 (대표 지시): 세금계산서 '묶어 발행' — 여러 출하 건을 한 장으로 합산 발행 + 장부 ───
def _ti_row_sig(kind, ref_id, iids):
    """작업일정표 행 식별 서명. 호기 분할 줄=정렬한 iids CSV('unit:7,12,30'), 그 외=kind:ref('project:123')."""
    try:
        if iids:
            return "unit:" + ",".join(str(int(x)) for x in sorted(int(i) for i in iids))
        return f"{kind}:{int(ref_id)}"
    except Exception:
        return f"{kind}:{ref_id}"


def _apply_import_ti_to_units(c, ti_rows):
    """v5H226z660 (대표 지시): 일괄등록/엑셀의 거래명세서·세금계산서를 '호기(order_items)'에 직접 기록.
    작업일정표·프로젝트 상세가 모두 호기 칸을 단일 소스로 읽으므로(z562) 두 화면이 항상 일치한다.
    각 줄이 만든 '자기 수주(SO)의 대표(최소 id) 호기'에 기록(tr.order_id) — 없으면 최신 SO 폴백(레거시).
    v5H226z676 (대표 지시): 이전엔 모두 '최신 SO'에 몰아써 같은 관리번호 여러 SO(추가제작)의 세금계산서가
    서로 덮어쓰기됐음(006T2603: 4개 수주 세금계산서가 최신 1곳에 몰려 마지막만 생존). 반환 (적용 프로젝트수, 세금계산서 차수 합)."""
    try:
        _oic = {x[1] for x in c.execute("PRAGMA table_info(order_items)").fetchall()}
    except Exception:
        _oic = set()
    proj_n = ti_n = 0
    for tr in (ti_rows or []):
        # v5H226z692 (대표 지시): 그 수주(SO)의 '모든 호기'에 나눠 기록 — 한 호기에 전액 몰지 않음.
        #   기존 z676 은 대표(최소 id) 호기 1곳에 전액 기록 → 3호기 완제품도 1호기에 합계만 뜨고 2·3호기 빈칸(006T2602).
        #   출하/발행은 호기 단위이므로 거래명세서·세금계산서를 그 수주 호기수로 균등분배(_write_tax_truth)·날짜는 동일.
        _iids = []
        try:
            _oid = tr.get("order_id")
            if _oid:
                _rows = c.execute(
                    "SELECT oi.id FROM order_items oi JOIN orders o ON o.id=oi.order_id "
                    "WHERE oi.order_id=? AND COALESCE(o.status,'')<>'CANCELLED' ORDER BY oi.id ASC",
                    (int(_oid),)).fetchall()
                _iids = [(r["id"] if isinstance(r, dict) else r[0]) for r in _rows]
            if not _iids:   # 폴백(order_id 없거나 못 찾을 때): 최신 SO 의 전체 호기(레거시)
                _so = c.execute(
                    "SELECT o.id FROM orders o WHERE o.project_id=? AND COALESCE(o.status,'')<>'CANCELLED' "
                    "ORDER BY o.id DESC LIMIT 1", (tr["pid"],)).fetchone()
                if _so:
                    _soid = _so["id"] if isinstance(_so, dict) else _so[0]
                    _rows = c.execute("SELECT id FROM order_items WHERE order_id=? ORDER BY id ASC", (_soid,)).fetchall()
                    _iids = [(r["id"] if isinstance(r, dict) else r[0]) for r in _rows]
        except Exception:
            _iids = []
        if not _iids:
            continue
        # 거래명세서(발행일) — 그 수주 모든 호기에 동일 날짜
        if tr.get("statement_date") and "statement_date" in _oic:
            try:
                _ph = ",".join("?" * len(_iids))
                c.execute(f"UPDATE order_items SET statement_date=? WHERE id IN ({_ph})",
                          [tr["statement_date"]] + _iids)
                proj_n += 1
            except Exception:
                pass
        # 세금계산서 1/2/3차 — 날짜는 모든 호기, 금액은 호기수로 균등분배(합계 보존)
        for (tier, d, bundle, amt) in (tr.get("ti") or []):
            try:
                _write_tax_truth(c, "order_items", _iids, tier, d, amt)
                ti_n += 1
            except Exception:
                pass
    return (proj_n, ti_n)


def _delete_import_ti_bundles(c):
    """v5H226z660 (대표 지시): import 가 만든 묶음 세금계산서(메모로 식별) 제거 — 작업일정표가 묶음을
    우선 표시해 호기 기록(상세)과 어긋나는 것 방지(동기화). 반환 삭제 장수."""
    try:
        _ids = [x[0] for x in c.execute(
            "SELECT id FROM tax_invoices WHERE COALESCE(memo,'') LIKE '일괄등록%' "
            "OR COALESCE(memo,'') LIKE '엑셀 세금계산서%'").fetchall()]
        for _tid in _ids:
            try:
                c.execute("DELETE FROM tax_invoice_lines WHERE ti_id=?", (_tid,))
                c.execute("DELETE FROM tax_invoices WHERE id=?", (_tid,))
            except Exception:
                pass
        return len(_ids)
    except Exception:
        return 0


def _ti_make_bundle(c, tier, issue_date, currency, cust_name, lines, created_by, created_by_name, memo=""):
    """v5H226z491b: 주어진 라인들을 한 장의 묶음 세금계산서(tax_invoices)로 발행(작업일정표 묶어발행과 동일 장부).
    lines=[{sig, ref_kind, ref_id, mgmt_code, label, customer, amount}]. (ti_no, ti_id, total) 반환. 호출자가 트랜잭션 관리."""
    issue_date = (str(issue_date or ""))[:10]
    ym = (issue_date[2:4] + issue_date[5:7]) if len(issue_date) >= 7 else "0000"
    prefix = f"TI-{ym}-"
    seq = (c.execute("SELECT COUNT(*) FROM tax_invoices WHERE ti_no LIKE ?", (prefix + "%",)).fetchone()[0] or 0) + 1
    ti_no = f"{prefix}{seq:04d}"
    total = sum(float(l.get("amount") or 0) for l in lines)
    cid = None
    if cust_name:
        # v5H226z657: 상호(name) 또는 시스템명(alias) 단일 매칭 시 세금계산서 고객사 연결(z654 일관)
        _m = c.execute("SELECT id FROM customers WHERE name=? OR alias=?", (cust_name, cust_name)).fetchall()
        cid = _m[0][0] if len(_m) == 1 else None   # 명확한 단일후보만(연결성 안전원칙)
    cur = c.execute(
        "INSERT INTO tax_invoices(ti_no, issue_date, customer_name, customer_id, total_amount, currency, memo, status, created_by, created_by_name) "
        "VALUES(?,?,?,?,?,?,?,'발행',?,?)",
        (ti_no, issue_date, cust_name, cid, total, currency, memo, created_by, created_by_name))
    ti_id = cur.lastrowid
    for l in lines:
        c.execute(
            "INSERT INTO tax_invoice_lines(ti_id, row_sig, ref_kind, ref_id, unit_iids, mgmt_code, label, customer, amount, tier) "
            "VALUES(?,?,?,?,?,?,?,?,?,?)",
            (ti_id, l.get("sig"), l.get("ref_kind", "consumable"), l.get("ref_id"), "",
             l.get("mgmt_code", ""), l.get("label", ""), l.get("customer", ""), float(l.get("amount") or 0), tier))
    return ti_no, ti_id, total


def _write_tax_truth(c, table, ids, tier, idate, amount):
    """v5H226z672 (대표 지시): 세금계산서 '단일 진실=호기' — 발행 시 대상(order_items 호기 /
    consumable_orders 소모품)의 tier(1/2/3) 발행일+금액을 직접 기록한다. 금액은 대상 수로
    균등분배(합계 보존)·날짜는 동일. (묶음 tax_invoice_lines 는 '한 장으로 발행' 표시 라벨로만
    두고, 화면 추정분배는 폐기 → 보드·상세가 항상 호기 한 곳을 읽어 일치.) table 은 내부 호출
    전용 리터럴('order_items'/'consumable_orders')."""
    try:
        ids = [int(x) for x in (ids or [])]
    except Exception:
        ids = []
    if not ids:
        return
    _t = int(tier or 1)
    _df = {1: "tax_invoice_date", 2: "tax_invoice_date2", 3: "tax_invoice_date3"}.get(_t)
    _af = {1: "tax_invoice_amt1", 2: "tax_invoice_amt2", 3: "tax_invoice_amt3"}.get(_t)
    try:
        _cols = {r[1] for r in c.execute(f"PRAGMA table_info({table})").fetchall()}
    except Exception:
        _cols = set()
    _ua = ", updated_at=datetime('now','localtime')" if "updated_at" in _cols else ""
    if _df and _df in _cols and idate:
        _ph = ",".join("?" * len(ids))
        c.execute(f"UPDATE {table} SET {_df}=?{_ua} WHERE id IN ({_ph})", [str(idate)[:10]] + ids)
    if _af and _af in _cols and amount is not None:
        try:
            total = float(amount)
        except Exception:
            return
        n = len(ids)
        share = round(total / n, 2)
        rem = round(total - share * n, 2)   # 반올림 잔차는 첫 칸에 몰아 합계 정확 보존
        for _i, _iid in enumerate(ids):
            c.execute(f"UPDATE {table} SET {_af}=?{_ua} WHERE id=?",
                      (share + (rem if _i == 0 else 0), _iid))


@app.post("/sales/schedule/tax-invoice/issue")
async def schedule_tax_invoice_issue(request: Request):
    """작업일정표에서 체크한 여러 출하 건(여러 관리번호/여러 호기/같은 출하시점)을 '한 장의 세금계산서'로 묶어 발행.
    기본은 같은 고객사만 묶이게(다르면 force 필요). 청구 성격 → can_view_sales."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_view_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    try:
        b = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "bad_request"}, 400)
    lines = b.get("lines") or []
    if not isinstance(lines, list) or not lines:
        return JSONResponse({"ok": False, "error": "묶을 항목을 선택하세요"}, 400)
    force = bool(b.get("force"))
    issue_date = (str(b.get("issue_date") or "").strip())[:10]
    if not issue_date:
        from datetime import date as _d
        issue_date = _d.today().isoformat()
    memo = (str(b.get("memo") or "").strip())
    # v5H226z489 (대표 지시): 묶음은 세금계산서 차수(1=계약금·2=중도금·3=잔금) 단위 — 여러 건의 같은 차수끼리 한 장.
    try:
        tier = int(b.get("tier") or 1)
    except Exception:
        tier = 1
    if tier not in (1, 2, 3):
        tier = 1
    # v5H226z563 (대표 지시): 다른 고객사끼리는 한 장으로 묶을 수 없음 — 강행(force) 폐기·완전 차단.
    custs = sorted({(ln.get("customer") or "").strip() for ln in lines if (ln.get("customer") or "").strip() and (ln.get("customer") or "").strip() != "—"})
    if len(custs) > 1:
        return JSONResponse({"ok": False,
                             "error": "다른 고객사끼리는 한 장의 세금계산서로 묶어 발행할 수 없습니다: "
                                      + ", ".join(custs) + " — 고객사별로 따로 발행하세요."}, 400)
    currency = (lines[0].get("currency") or "KRW")
    norm, total = [], 0.0
    for ln in lines:
        kind = (ln.get("kind") or "project")
        ref_id = ln.get("ref_id")
        uids = ln.get("uids") or []
        if isinstance(uids, str):
            uids = [x for x in uids.split(",") if x.strip()]
        try:
            amt = float(str(ln.get("amount") or 0).replace(",", ""))
        except Exception:
            amt = 0.0
        norm.append({"sig": _ti_row_sig(kind, ref_id, uids),
                     "rkind": ("unit" if uids else kind), "ref_id": ref_id,
                     "uids": ",".join(str(x) for x in uids) if uids else "",
                     "mgmt_code": (ln.get("code") or ""), "label": (ln.get("label") or ""),
                     "customer": (ln.get("customer") or ""), "amount": amt})
        total += amt
    cust_name = (custs[0] if custs else "")
    try:
        with db_session() as c:
            # v5H226z489: 같은 차수가 이미 다른 '발행' 세금계산서에 묶여 있으면 차단(이중발행 방지)
            _sigs = [n["sig"] for n in norm]
            if _sigs:
                _ph = ",".join("?" * len(_sigs))
                _dup = c.execute(
                    f"SELECT l.mgmt_code, l.label, t.ti_no FROM tax_invoice_lines l "
                    f"JOIN tax_invoices t ON t.id=l.ti_id "
                    f"WHERE t.status='발행' AND l.tier=? AND l.row_sig IN ({_ph})",
                    [tier] + _sigs).fetchall()
                if _dup:
                    _names = ", ".join((d[0] or "") + (f"({d[1]})" if d[1] else "") + f"→#{d[2] or ''}" for d in _dup)
                    return JSONResponse({"ok": False, "error": f"{tier}차가 이미 다른 세금계산서에 묶여 있는 건이 있습니다: {_names}. 먼저 그 발행을 취소하세요."}, 400)
            ym = issue_date[2:4] + issue_date[5:7]   # YYMM
            prefix = f"TI-{ym}-"
            seq = (c.execute("SELECT COUNT(*) FROM tax_invoices WHERE ti_no LIKE ?", (prefix + "%",)).fetchone()[0] or 0) + 1
            ti_no = f"{prefix}{seq:04d}"
            cid = None
            if cust_name:
                _m = c.execute("SELECT id FROM customers WHERE name=?", (cust_name,)).fetchall()
                cid = _m[0][0] if len(_m) == 1 else None   # 명확한 단일후보만(데이터 연결성 안전원칙)
            cur = c.execute(
                "INSERT INTO tax_invoices(ti_no, issue_date, customer_name, customer_id, total_amount, currency, memo, status, created_by, created_by_name) "
                "VALUES(?,?,?,?,?,?,?,'발행',?,?)",
                (ti_no, issue_date, cust_name, cid, total, currency, memo, u.get("id"), u.get("name") or ""))
            ti_id = cur.lastrowid
            for n in norm:
                c.execute(
                    "INSERT INTO tax_invoice_lines(ti_id, row_sig, ref_kind, ref_id, unit_iids, mgmt_code, label, customer, amount, tier) "
                    "VALUES(?,?,?,?,?,?,?,?,?,?)",
                    (ti_id, n["sig"], n["rkind"], n["ref_id"], n["uids"], n["mgmt_code"], n["label"], n["customer"], n["amount"], tier))
            # v5H226z672 (대표 지시): 세금계산서 단일 진실=호기 — 발행 금액을 각 호기/소모품 칸에 직접 기록.
            #   (위 tax_invoices/tax_invoice_lines = '한 장으로 발행' 표시 라벨. 화면 추정분배 폐기 → 보드·상세 일치.)
            for n in norm:
                try:
                    if n["rkind"] == "consumable":
                        _write_tax_truth(c, "consumable_orders",
                                         ([n["ref_id"]] if n.get("ref_id") else []), tier, issue_date, n["amount"])
                        continue
                    if n.get("uids"):
                        _raw = [int(x) for x in str(n["uids"]).split(",") if str(x).strip().isdigit()]
                        _ids = []
                        if _raw:
                            _ph = ",".join("?" * len(_raw))
                            _ids = [int(r[0]) for r in c.execute(
                                f"SELECT oi.id FROM order_items oi JOIN orders o ON o.id=oi.order_id "
                                f"WHERE oi.id IN ({_ph}) AND COALESCE(o.status,'')<>'CANCELLED'", _raw).fetchall()]
                    else:
                        _ids = [int(r[0]) for r in c.execute(
                            "SELECT oi.id FROM order_items oi JOIN orders o ON o.id=oi.order_id "
                            "WHERE o.project_id=? AND COALESCE(o.status,'')<>'CANCELLED' ORDER BY oi.id",
                            (n["ref_id"],)).fetchall()]
                    _write_tax_truth(c, "order_items", _ids, tier, issue_date, n["amount"])
                except Exception:
                    pass
    except Exception as e:
        return JSONResponse({"ok": False, "error": str(e)[:160]}, 500)
    return JSONResponse({"ok": True, "ti_no": ti_no, "ti_id": ti_id, "n": len(norm), "total": total, "currency": currency, "tier": tier})


@app.get("/sales/schedule/tax-invoice/{ti_id:int}")
async def schedule_tax_invoice_view(request: Request, ti_id: int):
    """묶음 세금계산서 1장 구성 보기(작업일정표 📄칩 클릭)."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_view_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    with db_session() as c:
        t = c.execute("SELECT * FROM tax_invoices WHERE id=?", (ti_id,)).fetchone()
        if not t:
            return JSONResponse({"ok": False, "error": "not_found"}, 404)
        t = dict(t)
        ls = [dict(r) for r in c.execute(
            "SELECT mgmt_code, label, customer, amount, tier, ref_kind, ref_id FROM tax_invoice_lines WHERE ti_id=? ORDER BY id", (ti_id,)).fetchall()]
        # v5H226z506 (대표 지시): 관리번호 칸에 수주번호가 들어가던 문제 — ref_id로 '실제 관리번호 + 수주번호'를 조회(스냅샷 무시·기존 묶음도 교정).
        for ln in ls:
            _rk = (ln.get("ref_kind") or ""); _rid = ln.get("ref_id")
            _code, _so = "", ""
            try:
                if _rk == "consumable" and _rid:
                    _rr = c.execute("SELECT mgmt_code, co_no FROM consumable_orders WHERE id=?", (_rid,)).fetchone()
                    if _rr:
                        _code, _so = (_rr[0] or ""), (_rr[1] or "")
                elif _rid:   # project / unit(호기 분할) → 프로젝트
                    _rr = c.execute("SELECT mgmt_code FROM projects WHERE id=?", (_rid,)).fetchone()
                    if _rr:
                        _code = _rr[0] or ""
                    _sr = c.execute("SELECT order_no FROM orders WHERE project_id=? ORDER BY id DESC LIMIT 1", (_rid,)).fetchone()
                    if _sr:
                        _so = _sr[0] or ""
            except Exception:
                pass
            ln["code"] = _code or (ln.get("mgmt_code") or "")   # 폴백=스냅샷
            ln["so_no"] = _so
        # v5H226z620 (대표 지시): 고객사 종사업장번호 표기(같은 상호 다른 종사업장 구분). customer_id 우선.
        _ti_sbn = ""
        try:
            _cid = t.get("customer_id")
            _cr = c.execute("SELECT sub_biz_no FROM customers WHERE id=?", (_cid,)).fetchone() if _cid else None
            if not _cr and t.get("customer_name"):
                _cr = c.execute("SELECT sub_biz_no FROM customers WHERE name=? LIMIT 1", (t.get("customer_name"),)).fetchone()
            if _cr:
                _ti_sbn = (_cr[0] or "")
        except Exception:
            pass
    _tier = (ls[0].get("tier") if ls else 1) or 1
    return JSONResponse({"ok": True, "invoice": {
        "id": t["id"], "ti_no": t.get("ti_no"), "issue_date": t.get("issue_date"),
        "customer_name": t.get("customer_name"), "sub_biz_no": _ti_sbn,
        "total_amount": t.get("total_amount"),
        "currency": t.get("currency"), "memo": t.get("memo"), "status": t.get("status"),
        "tier": _tier, "created_by_name": t.get("created_by_name") or ""}, "lines": ls})


@app.post("/sales/schedule/tax-invoice/{ti_id:int}/cancel")
async def schedule_tax_invoice_cancel(request: Request, ti_id: int):
    """묶음 세금계산서 취소(발행 철회) — 상태='취소'로, 작업일정표 칩 사라짐."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_view_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    with db_session() as c:
        r = c.execute("SELECT status FROM tax_invoices WHERE id=?", (ti_id,)).fetchone()
        if not r:
            return JSONResponse({"ok": False, "error": "not_found"}, 404)
        c.execute("UPDATE tax_invoices SET status='취소', updated_at=datetime('now','localtime') WHERE id=?", (ti_id,))
    return JSONResponse({"ok": True})


def _dept_sched_dept_of(u):
    """기록자 기본 부서 = 소속 팀 이름(법인 라벨 포함 — '본사 · 설계팀'). v5H226z542."""
    tid = u.get("team_id")
    if not tid:
        return ""
    try:
        with db_session() as _c:
            _r = _c.execute("SELECT name, entity FROM teams WHERE id=?", (tid,)).fetchone()
            if not _r:
                return ""
            return _team_label(_r[0], (_r[1] if len(_r) > 1 else None))
    except Exception:
        return ""


@app.get("/dept/schedule", response_class=HTMLResponse)
async def dept_schedule(request: Request, ym: str = "", biz: str = "", dept: str = ""):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    import calendar as _cal
    from datetime import date as _date, datetime as _dt, timedelta as _td
    today = _dt.now().date()
    try:
        _y, _m = (int(ym[:4]), int(ym[5:7])) if (ym and len(ym) >= 7) else (today.year, today.month)
        if not (1 <= _m <= 12):
            raise ValueError
    except Exception:
        _y, _m = today.year, today.month
    last_day = _cal.monthrange(_y, _m)[1]
    mstart, mend = _date(_y, _m, 1), _date(_y, _m, last_day)
    days = list(range(1, last_day + 1))
    today_day = today.day if (today.year == _y and today.month == _m) else None
    _prev, _next = mstart - _td(days=1), mend + _td(days=1)
    prev_ym, next_ym = f"{_prev.year:04d}-{_prev.month:02d}", f"{_next.year:04d}-{_next.month:02d}"

    def _pd(s):
        try:
            return _dt.strptime(str(s)[:10], "%Y-%m-%d").date()
        except Exception:
            return None

    # 수주번호(SO) 맵 — 프로젝트별 최신 order_no
    _so_map = {}
    try:
        with db_session() as _c:
            for _r2 in _c.execute("SELECT project_id, order_no FROM orders WHERE project_id IS NOT NULL ORDER BY id DESC"):
                if _r2[0] and _r2[0] not in _so_map:
                    _so_map[_r2[0]] = _r2[1] or ""
    except Exception:
        pass

    # v5H226z550 (대표 지시): 고객사 '시스템명(별칭)' 맵 — 일정표 표시는 시스템명 우선(연결/검증은 customer_id 그대로)
    _cust_alias = {}
    try:
        with db_session() as _c:
            for _ar in _c.execute("SELECT id, alias FROM customers WHERE COALESCE(alias,'')<>''"):
                _cust_alias[_ar[0]] = _ar[1]
    except Exception:
        _cust_alias = {}

    def _mk(info, od, dd, status, kind):
        s, e = (od or dd), (dd or od)
        if not s and not e:
            return None
        s, e = (s or e), (e or s)
        if e < s:
            s, e = e, s
        if e < mstart or s > mend:
            return None
        info["bar_s"] = max(s, mstart).day
        info["bar_e"] = min(e, mend).day
        info["dday"] = dd.day if (dd and mstart <= dd <= mend) else None
        info["is_delay"] = bool(dd and dd < today and status not in ("출하", "취소", "보류"))
        info["kind"] = kind
        return info

    rows = []
    # v5H226z826 (대표 지시): 부서일정표는 '제작에 꼭 필요한 것만' — 출하완료·취소·보류 건은 제외.
    #   관련부서원은 '지금 만들 것'만 보면 됨(원본 상세·금액은 작업일정표에만). 부분출하는 남김(미출하 호기 있으면 '진행중').
    #   상태값: 프로젝트/호기=한글(출하/취소/보류), 소모품=영문(SHIPPED/PAID/CANCELLED/HOLD) — 둘 다 처리.
    def _dsx_hidden(st):
        s = str(st or "").strip()
        return s in ("출하", "취소", "보류") or s.upper() in ("SHIPPED", "PAID", "CANCELLED", "HOLD")
    _split_map = _board_split_lines_map(unfold_sos=False)   # v5H226z665: 부서일정표는 관리번호=한 줄 유지(추가 SO 묶음) — 부서 기록 중복 방지
    _bus_iid, _bus_proj = _board_unit_status_maps()   # v5H226z661 (대표 지시): 부서일정표 납기 지연색도 호기 출하 반영(작업일정표와 동일)
    for p in (dict(r) for r in _logi.projects_list_logi()):
        if (p.get("project_type") or "").upper() == "CONSUMABLE":
            continue
        code = p.get("mgmt_code") or "—"
        info = {
            "kind": "project", "ref_id": p.get("id"), "code": code,
            "so_no": _so_map.get(p.get("id"), ""),
            "model": p.get("model_name") or "", "equip": p.get("equip_name") or "",
            "qty": p.get("unit_qty") or "", "po_type": p.get("po_type") or "",
            "form_type": p.get("form_type") or _logi.SHIP_TO_FORM.get((p.get("shipment_form") or "").upper(), ""),
            "customer": (_cust_alias.get(p.get("customer_id")) or p.get("customer_name") or "—"),   # v5H226z550: 시스템명 우선
            "cust_ok": bool(p.get("customer_id")),
            "owner": p.get("cc_name") or "",           # 고객사 담당자
            "order_date": str(p.get("order_date") or "")[:10],
            "due_date": str(p.get("due_date") or "")[:10],
            "uids": [],   # v5H226z549: 빈=프로젝트 전체(단일/균일) · 분할 시 그 줄의 호기 id만
        }
        _ulines = _split_map.get(p.get("id"))
        if _ulines:
            # v5H226z549: 호기 단가/납기 상이 → SO/호기 묶음별 1줄(각 줄 수량·납기·'+'펼침이 그 호기만 일치)
            for _ln in _ulines:
                _iu = dict(info)
                _iu["so_no"] = _ln.get("so_no") or info.get("so_no") or ""
                _iu["qty"] = _ln.get("qty", _ln.get("count", 1))   # z666: 라인 실수량
                _iu["order_date"] = (_ln.get("order_date") or info.get("order_date") or "")
                _iu["due_date"] = (_ln.get("due_date") or info.get("due_date") or "")
                _iu["uids"] = _ln.get("iids") or []
                _iu["unit_label"] = _ln.get("label") or ""
                try:
                    _iu["multi"] = int(_iu.get("qty") or 0) >= 2
                except Exception:
                    _iu["multi"] = False
                _eff_st = _board_agg_status([_bus_iid.get(_i) for _i in (_ln.get("iids") or [])]) or p.get("status")
                if _dsx_hidden(_eff_st):   # v5H226z826: 출하/취소/보류 줄 제외(부분출하는 '진행중'이라 유지됨)
                    continue
                _ru = _mk(_iu, _pd(_iu["order_date"]), _pd(_iu["due_date"]), _eff_st, "project")
                if _ru:
                    rows.append(_ru)
        else:
            try:
                info["multi"] = int(p.get("unit_qty") or 0) >= 2   # v5H226z499: 호기 여러 대=완제품 → 호기별 기록 가능
            except Exception:
                info["multi"] = False
            _eff_st = _board_agg_status(_bus_proj.get(p.get("id")) or []) or p.get("status")
            if not _dsx_hidden(_eff_st):   # v5H226z826: 출하/취소/보류 제외
                _r = _mk(info, _pd(p.get("order_date")), _pd(p.get("due_date")), _eff_st, "project")
                if _r:
                    rows.append(_r)
    try:
        from . import consumables as _co_mod
        for cr in _co_mod.co_list(status="", q="", limit=1000):
            if _dsx_hidden(cr.get("status")):   # v5H226z826: 출하완료(SHIPPED/PAID)·취소·보류 소모품 제외
                continue
            info = {
                "kind": "consumable", "ref_id": cr.get("id"), "code": cr.get("mgmt_code") or "—",
                "so_no": cr.get("co_no") or "", "model": cr.get("model_name") or "", "equip": cr.get("equip_name") or "",
                "qty": 1, "po_type": "소모품", "form_type": (cr.get("form_type") or "상품"),   # v5H226z563: 엑셀 형태 반영(기본 상품)
                "customer": (_cust_alias.get(cr.get("customer_id")) or cr.get("customer_name") or "—"),   # v5H226z550: 시스템명 우선
                "cust_ok": bool(cr.get("customer_id")),
                "owner": cr.get("cc_name") or "",
                "order_date": str(cr.get("order_date") or "")[:10],
                "due_date": str(cr.get("due_date") or "")[:10],
                "uids": [],   # v5H226z549: 소모품은 등록 품목 전체 펼침(분할 없음)
            }
            _r = _mk(info, _pd(cr.get("order_date")), _pd(cr.get("due_date")), "", "consumable")
            if _r:
                rows.append(_r)
    except Exception:
        pass

    # 사업부 분류 + 탭 필터 (관리번호 4번째 글자 T/M/L/E/C)
    for r in rows:
        _rc = r.get("code") or ""
        r["div"] = _rc[3] if (len(_rc) >= 4 and _rc[3] in "TMLEC") else ("C" if r["kind"] == "consumable" else "")
    div_counts = {"all": len(rows), "T": 0, "M": 0, "L": 0, "E": 0, "C": 0}
    for r in rows:
        if r["div"] in div_counts:
            div_counts[r["div"]] += 1
    _biz = (biz or "").strip().upper()
    if _biz in ("T", "M", "L", "E", "C"):
        rows = [r for r in rows if r["div"] == _biz]
    else:
        _biz = ""
    rows.sort(key=lambda r: (0 if r["dday"] else 1, r["dday"] or 99, r["code"]))

    # v5H226z571 (대표 지시): 단계 시스템 완전 제거 — 부서일정표의 '단계' 연동 컬럼도 폐지.
    # 내 부서 + 부서 목록(teams)
    my_team = _dept_sched_dept_of(u)
    all_depts = []
    try:
        with db_session() as _c:
            # v5H226z542: 부서 목록에 법인 라벨('본사 · 설계팀'/'베트남 · 설계팀') — 같은 이름도 구분
            all_depts = [_team_label(r[0], (r[1] if len(r) > 1 else None))
                         for r in _c.execute(
                             "SELECT name, entity FROM teams "
                             "ORDER BY (CASE WHEN COALESCE(entity,'KOR')='VN' THEN 1 ELSE 0 END), display_order, id"
                         ).fetchall() if r[0]]
    except Exception:
        all_depts = []
    # v5H226z497 (Phase 2): 부서 필터 — sel_dept 면 그 부서 기록만 마커/요약에 반영(팝업 목록은 전체 유지)
    sel_dept = (dept or "").strip()

    # 이 달 부서 기록 로드 → logmap[key][day_str]=[entries] , cellsum[key][day_str]={n,color}
    #   + 월간/품목별 요약(summary): 유형분포·부서별 건수·기록 품목 수 (사업부 필터된 행 대상)
    logmap, cellsum = {}, {}
    _visible_keys = {f"{r['kind']}:{r['ref_id']}" for r in rows}
    # v5H226z570 (대표 지시·업무량 집계): 월간 요약에 소요시간(hours) + 부서별/개인별 건수·완료·시간
    summary = {"total": 0, "prog": 0, "done": 0, "chg": 0, "etc": 0, "items": 0,
               "hours": 0.0, "by_dept": [], "by_person": []}
    _by_dept, _by_person, _items_with = {}, {}, set()
    try:
        with db_session() as _c:
            for lr in _c.execute(
                "SELECT ref_kind, ref_id, log_date, id, COALESCE(dept,''), COALESCE(log_type,'진행'), "
                "COALESCE(content,''), COALESCE(created_by_name,''), COALESCE(updated_at,''), COALESCE(created_by,0), "
                "COALESCE(handoff_to,''), COALESCE(unit_label,''), COALESCE(hours,0) "
                "FROM dept_schedule_log WHERE log_date BETWEEN ? AND ? ORDER BY id",
                    (mstart.isoformat(), mend.isoformat())):
                key = f"{lr[0]}:{lr[1]}"
                try:
                    dnum = str(int(str(lr[2])[8:10]))
                except Exception:
                    continue
                logmap.setdefault(key, {}).setdefault(dnum, []).append(
                    {"id": lr[3], "dept": lr[4], "type": lr[5], "content": lr[6],
                     "by": lr[7], "ts": lr[8], "uid": lr[9], "to": lr[10], "unit": lr[11],
                     "hours": (float(lr[12]) if lr[12] else 0)})
                # 요약 — 화면에 보이는 행(사업부 필터 통과)만 집계
                if key in _visible_keys:
                    summary["total"] += 1
                    summary[{"진행": "prog", "완료": "done", "변경": "chg"}.get(lr[5], "etc")] += 1
                    _h = float(lr[12] or 0)
                    summary["hours"] += _h
                    _dk = lr[4] or "(부서없음)"
                    _dd = _by_dept.setdefault(_dk, {"n": 0, "done": 0, "hours": 0.0})
                    _dd["n"] += 1; _dd["hours"] += _h
                    if lr[5] == "완료":
                        _dd["done"] += 1
                    _pk = lr[7] or "(이름없음)"
                    _pp = _by_person.setdefault(_pk, {"n": 0, "hours": 0.0})
                    _pp["n"] += 1; _pp["hours"] += _h
                    _items_with.add(key)
        # 마커(cellsum) — 부서 필터 적용(sel_dept 면 그 부서 기록만 카운트)
        # v5H226z514 (대표 지시): 관리번호(접힌) 줄 마커는 '공통 기록'(unit_label 빈 것)만 — 호기 지정 기록은
        #   펼친 호기 줄에서 표시(프론트가 logmap 의 unit 로 계산). 첫 줄=여러 항목 공통.
        for key, dm in logmap.items():
            cs = {}
            for ds, ents in dm.items():
                _e = [e for e in ents if (not sel_dept or e["dept"] == sel_dept) and not (e.get("unit") or "")]
                if not _e:
                    continue
                types = [e["type"] for e in _e]
                color = "done" if "완료" in types else ("chg" if "변경" in types else "prog")
                cs[ds] = {"n": len(_e), "color": color}
            if cs:
                cellsum[key] = cs
        summary["items"] = len(_items_with)
        summary["hours"] = round(summary["hours"], 1)
        summary["by_dept"] = [{"dept": k, "n": v["n"], "done": v["done"], "hours": round(v["hours"], 1)}
                              for k, v in sorted(_by_dept.items(), key=lambda x: -x[1]["n"])][:8]
        summary["by_person"] = [{"name": k, "n": v["n"], "hours": round(v["hours"], 1)}
                                for k, v in sorted(_by_person.items(), key=lambda x: -x[1]["n"])][:8]
    except Exception:
        logmap, cellsum = {}, {}

    return ctx(request, "dept_schedule.html", user=u, active="dept_schedule",
               rows=rows, days=days, today_day=today_day,
               month_label=f"{_y}년 {_m}월", ym=f"{_y:04d}-{_m:02d}",
               prev_ym=prev_ym, next_ym=next_ym, cur_ym=f"{today.year:04d}-{today.month:02d}",
               biz=_biz, div_counts=div_counts, cellsum=cellsum, logmap=logmap,
               my_team=my_team, all_depts=all_depts, sel_dept=sel_dept, summary=summary,
               types=["진행", "완료", "변경", "기타"],
               today=today.isoformat(), is_admin=bool(u.get("role") in ("admin", "ceo")), uid=u.get("id"))


@app.post("/dept/schedule/cell/add")
async def dept_schedule_add(request: Request):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "로그인 필요"}, 401)
    try:
        body = await request.json()
    except Exception:
        body = {}
    kind = (body.get("kind") or "").strip()
    ref_id = int(body.get("ref_id") or 0)
    date = (body.get("date") or "").strip()[:10]
    dept = (body.get("dept") or "").strip()
    log_type = (body.get("log_type") or "진행").strip()
    content = (body.get("content") or "").strip()
    handoff_to = (body.get("handoff_to") or "").strip()   # v5H226z497: 넘길 부서(다음 담당)
    unit_label = (body.get("unit_label") or "").strip()[:40]   # v5H226z499: 호기(빈값=품목 전체)
    # v5H226z570 (대표 지시): 소요시간(시간) — 업무량 집계용. 빈값/이상치는 None.
    try:
        hours = float(str(body.get("hours") or "").replace(",", "").strip())
        if hours <= 0 or hours > 999:
            hours = None
    except Exception:
        hours = None
    if kind not in ("project", "consumable") or not ref_id or not date:
        return JSONResponse({"ok": False, "error": "잘못된 요청"}, 400)
    if log_type not in ("진행", "완료", "변경", "기타"):
        log_type = "진행"
    if not content:
        return JSONResponse({"ok": False, "error": "내용을 입력하세요"}, 400)
    from datetime import datetime as _dt
    try:
        _dt.strptime(date, "%Y-%m-%d")
    except Exception:
        return JSONResponse({"ok": False, "error": "날짜 형식 오류"}, 400)
    if not dept:
        dept = _dept_sched_dept_of(u)
    notify = {"sent": 0, "in_app": 0, "to": handoff_to}
    with db_session() as c:
        c.execute("INSERT INTO dept_schedule_log(ref_kind, ref_id, log_date, dept, log_type, content, handoff_to, unit_label, hours, created_by, created_by_name) "
                  "VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                  (kind, ref_id, date, dept, log_type, content, handoff_to or None, unit_label or None, hours, u.get("id"), u.get("name") or ""))
        # v5H226z543 (대표 지시): '넘길 부서'를 여러 개 선택 가능 — ' | '로 합쳐 옴 → 각 부서원에게 통보(합집합 1회).
        _targets = [t.strip() for t in (handoff_to or "").split("|") if t.strip()]
        _targets = [t for t in _targets if t != (dept or "")]
        if _targets:
            try:
                from urllib.parse import quote
                _code = ""
                if kind == "project":
                    _cr = c.execute("SELECT mgmt_code FROM projects WHERE id=?", (ref_id,)).fetchone()
                else:
                    _cr = c.execute("SELECT mgmt_code FROM consumable_orders WHERE id=?", (ref_id,)).fetchone()
                _code = (_cr[0] if _cr else "") or f"{kind}#{ref_id}"
                # v5H226z542: 각 대상은 법인 라벨('베트남 · 설계팀') → 이름+법인으로 정확 매칭
                _ids = set()
                for _tg in _targets:
                    _nm, _ent = _parse_team_label(_tg)
                    if _ent == "VN":
                        _q = ("SELECT u.id FROM users u JOIN teams t ON t.id=u.team_id "
                              "WHERE t.name=? AND t.entity='VN' AND COALESCE(u.is_active,1)=1")
                    elif _ent == "KOR":
                        _q = ("SELECT u.id FROM users u JOIN teams t ON t.id=u.team_id "
                              "WHERE t.name=? AND COALESCE(t.entity,'KOR')='KOR' AND COALESCE(u.is_active,1)=1")
                    else:
                        _q = ("SELECT u.id FROM users u JOIN teams t ON t.id=u.team_id "
                              "WHERE t.name=? AND COALESCE(u.is_active,1)=1")
                    for r in c.execute(_q, (_nm,)).fetchall():
                        _ids.add(r[0])
                _ids = list(_ids)
                _tgt_disp = ", ".join(_targets)
                if _ids:
                    _title = f"🗓 [부서 일정] {_code} — {dept or '앞 부서'}→{_tgt_disp}"
                    _body = (f"{date} · {log_type}\n{content}\n"
                             f"(기록: {u.get('name') or '—'}{(' / ' + dept) if dept else ''} → {_tgt_disp}(으)로 넘김)")
                    _link = "/dept/schedule?dept=" + quote(_targets[0])
                    _res = _notify_users(c, _ids, "dept_schedule", _title, _body, _link)
                    notify["sent"] = _res.get("msg_sent", 0)
                    notify["in_app"] = _res.get("in_app", 0)
            except Exception:
                pass   # 통보 실패해도 기록 저장은 유지
    return JSONResponse({"ok": True, "notify": notify})


@app.post("/dept/schedule/cell/update")
async def dept_schedule_update(request: Request):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "로그인 필요"}, 401)
    try:
        body = await request.json()
    except Exception:
        body = {}
    lid = int(body.get("id") or 0)
    content = (body.get("content") or "").strip()
    log_type = (body.get("log_type") or "진행").strip()
    base_ts = body.get("base_ts") or ""
    # v5H226z570: 소요시간(시간) 수정 반영
    try:
        hours = float(str(body.get("hours") or "").replace(",", "").strip())
        if hours <= 0 or hours > 999:
            hours = None
    except Exception:
        hours = None
    if not lid:
        return JSONResponse({"ok": False, "error": "잘못된 요청"}, 400)
    if log_type not in ("진행", "완료", "변경", "기타"):
        log_type = "진행"
    if not content:
        return JSONResponse({"ok": False, "error": "내용을 입력하세요"}, 400)
    with db_session() as c:
        row = c.execute("SELECT COALESCE(created_by,0), COALESCE(updated_at,'') FROM dept_schedule_log WHERE id=?", (lid,)).fetchone()
        if not row:
            return JSONResponse({"ok": False, "error": "없는 기록입니다"}, 404)
        if not (row[0] == u.get("id") or u.get("role") in ("admin", "ceo")):
            return JSONResponse({"ok": False, "error": "작성자만 수정할 수 있습니다"}, 403)
        if base_ts and row[1] and base_ts != row[1]:
            return JSONResponse({"ok": False, "error": "다른 곳에서 먼저 수정됐습니다 — 새로고침 후 다시"}, 409)
        c.execute("UPDATE dept_schedule_log SET content=?, log_type=?, hours=?, updated_at=datetime('now','localtime') WHERE id=?",
                  (content, log_type, hours, lid))
    return JSONResponse({"ok": True})


