    # 빈 입력행 50개 (8행~57행) — 사용자가 채울 영역
    empty_font = Font(name="맑은 고딕", size=10, color="1E293B")
    for r in range(8, 58):
        for ci in range(1, len(cols) + 1):
            c = ws.cell(row=r, column=ci, value=None)
            c.font = empty_font
