    # v5H226z621 (대표 지시): 고객사 콤보박스에서 고른 customer_id 우선 적용 —
    #   같은 상호 다른 종사업장 구분(이름매칭 LIMIT 1 모호 방지). 빈값/무효면 기존 이름매칭 유지.
    _picked_cid = (form.get("customer_id") or "").strip()
    if new_pid and _picked_cid.isdigit():
        try:
            with db_session() as _cc_cid:
                if _cc_cid.execute("SELECT 1 FROM customers WHERE id=?", (int(_picked_cid),)).fetchone():
                    _cc_cid.execute("UPDATE projects SET customer_id=? WHERE id=?",
                                    (int(_picked_cid), int(new_pid)))
        except Exception:
            pass
    # v5H226z209 (2026-06-04 대표 지시·2단계): 품목(project_items) 저장.
    #   · item1 = 폼 기본 필드(출고형태·모델·수량·단가) — 대표 품목.
    #   · 추가 품목 = 폼 repeater(pi_* 배열) — 출고형태별 칸(장비명/품명·모델명).
    #   추가 품목은 수주(SO)로도 전개해 매출에 반영(z204 규칙: 장비=호기 N줄 / 부품·기타=동일단가×수량 1줄).
    #   품목 저장 실패는 등록 자체를 막지 않음(상세에서 보정 가능).
    _z209_extra_oids = []   # 추가 품목으로 발행한 SO id (아래 item1 자동발행 가드에서 제외)
    if new_pid:
        try:
            with db_session() as _cpi:
                # item1 (대표 품목) — 출고형태별 (z211):
                #   ASS'Y → 장비 자체(장비명+장비모델) / 부품 → 부품(품명+부품모델, 1식·상세 별도) / 기타 → 기타품명
                _sf1 = (form.get("shipment_form") or "ASSEMBLY").strip().upper()
                if _sf1 == "PARTS":
                    _it_name = (form.get("part_name") or "").strip() or "부품 1식"
                    _it_model = (form.get("part_model") or "").strip()
                    _it_qty, _it_price, _it_amt = 1, 0.0, 0.0       # 부품은 1식 — 상세·금액은 별도(PACKING LIST)
                    _it_note = "[등록] 부품 1식 (상세 별도)"
                elif _sf1 == "ETC":
                    _it_name = (form.get("etc_name") or "").strip() or project_name
                    _it_model = ""
                    _it_qty, _it_price, _it_amt = unit_qty, unit_price, amt
                    _it_note = "[등록] 기타 품목"
                else:  # ASSEMBLY
                    _it_name = (form.get("equip_name") or "").strip() or project_name
                    _it_model = form.get("model", "")
                    _it_qty, _it_price, _it_amt = unit_qty, unit_price, amt
                    _it_note = "[등록] 장비(대표 품목)"
                _logi.project_item_create(_cpi, int(new_pid), {
                    "shipment_form": _sf1,
                    "item_name": _it_name, "model_name": _it_model,
                    "qty": _it_qty, "unit_price": _it_price, "amount": _it_amt,
                    "currency": _ccy_v, "is_export": form.get("is_export", "0"),
                    "order_date": form.get("order_date", ""), "due_date": form.get("due_date", ""),
                    "secondary_customer": form.get("secondary_customer", ""),
                    "final_amount": form.get("final_amount", ""),
                    "note": _it_note,
                })
                # 추가 품목 (repeater) — 같은 인덱스 배열
                _pi_sf    = form.getlist("pi_sf[]")
                _pi_name  = form.getlist("pi_name[]")
                _pi_model = form.getlist("pi_model[]")
                _pi_qty   = form.getlist("pi_qty[]")
                _pi_price = form.getlist("pi_price[]")
                for _i in range(len(_pi_name)):
                    _nm = (_pi_name[_i] or "").strip()
                    _md = ((_pi_model[_i] if _i < len(_pi_model) else "") or "").strip()
                    if not _nm and not _md:
                        continue  # 빈 행 스킵
                    _sf = (_pi_sf[_i] if _i < len(_pi_sf) else "ASSEMBLY")
                    try:
                        _q = int(float(((_pi_qty[_i] if _i < len(_pi_qty) else "1") or "1").replace(",", "")))
                    except ValueError:
                        _q = 1
                    if _q < 1:
                        _q = 1
                    try:
                        _pr = float(((_pi_price[_i] if _i < len(_pi_price) else "0") or "0").replace(",", ""))
                    except ValueError:
                        _pr = 0.0
                    _pi_id = _logi.project_item_create(_cpi, int(new_pid), {
                        "shipment_form": _sf, "item_name": _nm or _md, "model_name": _md,
                        "qty": _q, "unit_price": _pr, "amount": _pr * _q,
                        "currency": _ccy_v, "is_export": form.get("is_export", "0"),
                        "note": "[등록] 추가 품목",
                    })
                    # 추가 품목 → 수주(SO) 전개 (출고형태별 규칙)
                    _sfu = (_sf or "ASSEMBLY").strip().upper()
                    if _sfu == "PARTS":
                        _so_t, _exp = "CONSUMABLE", False
                    elif _sfu == "ETC":
                        _so_t, _exp = "OTHER", False
                    else:
                        _so_t, _exp = "EQUIPMENT", True
                    try:
                        _r = _pwf.add_followup_order(
                            _cpi, int(new_pid), order_date=form.get("order_date", ""),
                            total_amount=_pr, due_date=form.get("due_date", ""),
                            created_by=_u.get("id") or 0, po_number=form.get("customer_po", ""),
                            note=f"[추가품목] {_nm}{(' / 모델: ' + _md) if _md else ''}",
                            qty=_q, so_type=_so_t, currency=_ccy_v, ship_to="",
                            expand_units=_exp, line_label=(_md or _nm))
                        if _r.get("ok") and _r.get("order_id"):
                            _logi.project_item_update(_cpi, _pi_id, {"order_id": _r["order_id"]})
                            _z209_extra_oids.append(int(_r["order_id"]))
                    except Exception:
                        pass
        except Exception:
            pass
    # v5H226z373 (대표 지시): 제작요청서 = 프로젝트 생성 출발점.
    #   간편폼의 '📋 제작요청 발행' 체크 시 — 등록·SO발번 직후(아래 성공 리다이렉트 경유)
    #   ① 작업일정표 '제작요청' 단계 자동기록 ② 관련부서(전부서) WORKS 통보(단가·금액 제외).
    _pr_notify = (form.get("prod_notify") or "").strip() in ("1", "on", "true", "yes")
    _pr_cust_req = (form.get("pr_cust_req") or "").strip()
    _pr_note = (form.get("pr_note") or "").strip()
    _pr_team_ids = [int(t) for t in form.getlist("pr_team_ids") if str(t).strip().isdigit() and int(t) > 0]
    # v5H226z794 (대표 지시): 개별 부서원 선택 — 개별 지정 인원(사업부 필터 없이 정확히 통보)
    _pr_user_ids = [int(x) for x in form.getlist("pr_user_ids") if str(x).strip().isdigit() and int(x) > 0]
    # v5H226z772 (대표 지시): 제작요청 발행 시 참고 이미지 첨부 — 멀티파트로 함께 온 파일 바이트를 먼저 읽어둠(await는 async 본문에서만).
    #   프로젝트·제작요청서 생성 직후 그 제작요청서(prid)에 귀속 저장. 최대 20장·장당 25MB.
    _pr_image_files = []
    if _pr_notify:
        try:
            for _imf in form.getlist("pr_images"):
                _fn = getattr(_imf, "filename", "") or ""
                if not _fn or not hasattr(_imf, "read"):
                    continue
                _raw = await _imf.read()
                if _raw and len(_raw) <= 25 * 1024 * 1024:
                    _pr_image_files.append((_fn, _raw))
                if len(_pr_image_files) >= 20:
                    break
        except Exception:
            _pr_image_files = []

    _reg_is_parts = (form.get("shipment_form") or "").strip().upper() == "PARTS"

    def _finish_new(_pid, _warn=""):
        """등록 성공 후 공통 종료 — 제작요청 발행(통보)까지 한 번에 처리하고 상세로 이동."""
        _qs = []
        if _warn:
            _qs.append(f"warn={_warn}")
        # v5H226z428(대표 지시): 형태=상품이면 상세의 PACKING LIST 로 유도(자동 스크롤·강조)
        if _reg_is_parts:
            _qs.append("focus=packing")
        # SO 발행 실패(_warn) 시엔 통보하지 않음(미완 상태로 전부서 호출 방지)
        if _pr_notify and _pid and not _warn:
            try:
                _res = _prod_request_notify_core(int(_pid), _pr_cust_req, _pr_note, _pr_team_ids, _u,
                                                 image_count=len(_pr_image_files), user_ids=_pr_user_ids)
                if _res.get("ok"):
                    _qs.append(f"prod_sent={_res.get('sent_to', 0)}")
                    _qs.append(f"prod_dept={_res.get('dept_count', 0)}")
                    # z772: 제작요청서(prid)에 참고 이미지 저장 — 실패해도 통보/등록은 유효(신호만 남김)
                    _prid = _res.get("pr_id") or 0
                    if _prid and _pr_image_files:
                        try:
                            _imgres = _attach_prod_images(_prid, _pid, _pr_image_files, (_u.get("id") if _u else None))
                            if _imgres.get("saved"):
                                _qs.append(f"prod_img={_imgres['saved']}")
                            if _imgres.get("skipped"):
                                _qs.append(f"prod_imgskip={len(_imgres['skipped'])}")
                        except Exception:
                            _qs.append("prod_imgerr=1")
                    # v5H226z391: 메신저(KNK Eum) 통보 결과 — 보낸 인원 수 / 실패 시 신호
                    _qs.append(f"prod_msg={_res.get('msg_sent', 0)}")
                    if _res.get("msg_err"):
                        _qs.append("prod_msgerr=1")
                    if _res.get("stage_warn"):
                        _qs.append("prod_stagewarn=1")
                    # z762: 제작요청서 저장 실패 시 신호(통보는 됐지만 이력 미저장 — 조용히 넘기지 않음)
                    if _res.get("pr_save_err"):
                        _qs.append("prod_saveerr=1")
                else:
                    _qs.append("prod_err=1")
            except Exception:
                _qs.append("prod_err=1")
        _url = f"/project/{_pid}" + ("?" + "&".join(_qs) if _qs else "")
        return RedirectResponse(_url, status_code=303)

    if confirm_now and new_pid:
        # v5H81: 호기 라인 — (납기, 납품지) 그룹화 키 포함
        # v5H92: 통화(currency) 도 라인별로 받음 (KRW/USD)
        labels = form.getlist("unit_label[]")
        amounts = form.getlist("unit_amount[]")
        dues = form.getlist("unit_due[]")
        ships = form.getlist("unit_ship[]")
        notes_u = form.getlist("unit_note[]")
        currs = form.getlist("unit_currency[]")
        units = []
        for i in range(max(len(labels), len(amounts))):
            # v5H137: 폼에서 라벨 비어 있으면 project_type 기준 자동 라벨
            lbl = (labels[i] if i < len(labels) else "").strip() or _logi.project_unit_label(_ptype, i + 1)
            raw = (amounts[i] if i < len(amounts) else "0").strip().replace(",", "")
            try:
                u_amt = float(raw) if raw else 0
            except ValueError:
                u_amt = 0
            u_due = (dues[i] if i < len(dues) else "").strip()
            u_ship = (ships[i] if i < len(ships) else "").strip()
            u_note = (notes_u[i] if i < len(notes_u) else "").strip()
            # v5H171: 화이트리스트 KRW/USD/VND/JPY/CNY/EUR (폼 옵션과 일치, VND 묵음 손실 버그 수정)
            # 헤더 통화로 대체(빈 셀 시) — 사용자가 헤더에서 USD 선택했으면 호기 라인도 USD 가 default
            _hdr_cur = (form.get("currency", "KRW") or "KRW").upper()
            u_cur = (currs[i] if i < len(currs) else "").strip().upper() or _hdr_cur
            if u_cur not in ("KRW", "USD", "VND", "JPY", "CNY", "EUR"):
                u_cur = _hdr_cur if _hdr_cur in ("KRW","USD","VND","JPY","CNY","EUR") else "KRW"
            if not (labels[i] if i < len(labels) else "") and u_amt == 0:
                continue
            units.append({"label": lbl, "amount": u_amt,
                          "due_date": u_due, "ship_to": u_ship,
                          "note": u_note, "currency": u_cur})
        # v5H226z: PARTS 형태는 호기 라인 없이 빈 SO + so_type=PARTS_EXPORT
        _ship_form_cn = (form.get("shipment_form") or "ASSEMBLY").strip().upper()
        try:
            with db_session() as c:
                if _ship_form_cn == "PARTS":
                    _pres = _pwf.confirm_order_multi(
                        c, int(new_pid), units=[],
                        order_date=form.get("order_date", ""),
                        created_by=_u.get("id") or 0,
                        po_number=form.get("customer_po", ""),
                        so_type="PARTS_EXPORT",
                    )
                    # v5H226z430 (대표 지시): 폼에서 입력한 부품(pk_*) → 이 PARTS SO 의 order_items 로 저장
                    #   (품명=unit_label · 모델=규격 spec · 수량·단가·금액). → 상세 PACKING LIST 에 그대로 나타남.
                    try:
                        _po_oid = ((_pres.get("groups") or [{}])[0].get("order_id")) if isinstance(_pres, dict) else None
                        if _po_oid and _pk_parts:
                            _oicols = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
                            # v5H226z602: 외화(USD 등)+환율이면 z596과 동일 — 판매단가=USD 인보이스가,
                            #   원가=매입KRW÷환율(마진% 유지). 환율은 SO(orders.exchange_rate)에 저장.
                            _foreign_v = (_ccy_v or "KRW").upper() != "KRW"
                            _so_fx = 0.0; _psum = 0.0
                            for _pp in _pk_parts:
                                _qy2 = float(_pp.get("qty") or 1) or 1
                                _price_krw = float(_pp.get("price") or 0)
                                _cost_krw = _pp.get("cost")
                                _fxv = float(_pp.get("fx") or 0)
                                if _foreign_v and _fxv > 0:
                                    _up = round(_price_krw / _fxv, 2)
                                    _cs = (round(float(_cost_krw) / _fxv, 4) if _cost_krw not in (None, "") else None)
                                    if _so_fx <= 0:
                                        _so_fx = _fxv
                                else:
                                    _up = _price_krw
                                    _cs = (float(_cost_krw) if _cost_krw not in (None, "") else None)
                                _amt2 = round(_qy2 * _up, 2); _psum += _amt2
                                _row = {"order_id": _po_oid, "qty": _qy2,
                                        "unit_price": _up, "amount": _amt2,
                                        "cost_price": _cs, "margin_pct": _pp.get("margin"),  # v5H226z460
                                        "unit_label": _pp["name"], "spec": _pp["model"],
                                        "material_no": _pp.get("matno") or None,
                                        "maker": _pp.get("maker") or None,
                                        "supplier": _pp.get("supplier") or None,
                                        "line_note": _pp.get("note") or None,
                                        "currency": _ccy_v,
                                        "order_date": form.get("order_date", "") or None,
                                        "due_date": (_pp.get("due") or form.get("due_date", "") or None),
                                        "unit_status": (_pp.get("status") or "진행중"),  # v5H226z729/z738: 폼 상태 반영(한글)
                                        "is_export": form.get("is_export", "0")}
                                if (_ccy_v or "").upper() == "USD" and _foreign_v and _fxv > 0:
                                    _row["invoice_unit_price_usd"] = _up
                                    _row["invoice_amount_usd"] = _amt2
                                _row = {k: v for k, v in _row.items() if k in _oicols}
                                _cols2 = list(_row.keys()); _ph2 = ",".join("?" * len(_cols2))
                                c.execute(f"INSERT INTO order_items({','.join(_cols2)}) VALUES({_ph2})",
                                          [_row[k] for k in _cols2])
                            _psum = round(_psum, 2)
                            try:
                                # z602: 부품 SO 에 통화·환율 저장(상세 KRW 환산 표시) + 프로젝트 금액/원화환산
                                _ocols2 = {r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()}
                                _os, _ov = [], []
                                if "currency" in _ocols2:
                                    _os.append("currency=?"); _ov.append(_ccy_v)
                                if "exchange_rate" in _ocols2 and _so_fx > 0:
                                    _os.append("exchange_rate=?"); _ov.append(_so_fx)
                                _os.append("total_amount=?"); _ov.append(_psum); _ov.append(_po_oid)
                                c.execute(f"UPDATE orders SET {', '.join(_os)} WHERE id=?", _ov)
                                c.execute("UPDATE projects SET order_amount=? WHERE id=?", (_psum, int(new_pid)))
                                if _foreign_v and _so_fx > 0:
                                    _akrw = round(sum((float(_p.get("price") or 0)) * (float(_p.get("qty") or 1))
                                                      for _p in _pk_parts), 2)
                                    c.execute("UPDATE projects SET fx_rate=?, amount_krw=? WHERE id=?",
                                              (_so_fx, _akrw, int(new_pid)))
                            except Exception:
                                pass
                    except Exception as _e:
                        print(f"[z430 parts insert] {_e}")
                elif units:
                    _pwf.confirm_order_multi(
                        c, int(new_pid), units=units,
                        order_date=form.get("order_date", ""),
                        created_by=_u.get("id") or 0,
                        po_number=form.get("customer_po", ""),
                    )
                else:
                    # 호기 라인이 비어 있으면 기존 단일 SO 흐름 (하위호환)
                    _pwf.confirm_order(
                        c, int(new_pid),
                        order_date=form.get("order_date", ""),
                        total_amount=amt,
                        due_date=form.get("due_date", ""),
                        created_by=_u.get("id") or 0,
                        po_number=form.get("customer_po", ""),
                        note=form.get("note", ""),
                    )
        except Exception:
            return _finish_new(new_pid, "so_issue_failed")
        return _finish_new(new_pid)
    # v5H87: confirm_now 미체크 + status 가 won (진행중/출하) 인 경우
    # 자동으로 SO 발행 (관리코드만 있고 SO 없는 모순 상태 방지)
    # v5H132: 수량 N → N개 호기 라인 자동 생성 (단가=unit_price)
    # v5H223: CONSUMABLE 도 자동 SO 발행 (빈 SO — 라인은 후속 추가)
    status_val = (form.get("status") or "").strip()
    # v5H226z: 출고 형태 PARTS 면 자동 SO 빈 SO + so_type=PARTS_EXPORT
    _ship_form_new = (form.get("shipment_form") or "ASSEMBLY").strip().upper()
    _is_parts_new = (_ship_form_new == "PARTS")
    # v5H226z194 (대표 지시): 등록 시 수주번호(SO) '항상' 발급 (제안 단계 포함). 상태(초기협의 등)는 그대로 유지.
    if not confirm_now and new_pid and _ptype in ("NEW_EQUIP", "CONSUMABLE", "OTHER"):
        try:
            with db_session() as c:
                # 이미 SO 가 있으면 발행 안 함 (재진입 방지).
                # v5H226z209: 단, 방금 '추가 품목'으로 발행한 SO(_z209_extra_oids)는 제외 —
                #   그것 때문에 item1(대표) 자동 SO 발행이 건너뛰어지지 않도록.
                if _z209_extra_oids:
                    _ph209 = ",".join("?" * len(_z209_extra_oids))
                    exists = c.execute(
                        f"SELECT 1 FROM orders WHERE project_id=? AND id NOT IN ({_ph209}) LIMIT 1",
                        (new_pid, *_z209_extra_oids)
                    ).fetchone()
                else:
                    exists = c.execute(
                        "SELECT 1 FROM orders WHERE project_id=? LIMIT 1", (new_pid,)
                    ).fetchone()
                if not exists:
                    # v5H132: 수량 N → N개 호기 (각 단가=unit_price)
                    # v5H223: CONSUMABLE 은 빈 SO (라인 후속 추가)
                    # v5H226z: PARTS 도 빈 SO (정식 PACKING LIST 후속 추가)
                    # v5H226z455 (대표 지시): 호기는 '완제품'(ASSEMBLY)만. 제품(SEMI)·기타는 1줄(수량=N).
                    _per_unit = unit_price if unit_price > 0 else (amt / max(1, unit_qty))
                    if _ptype == "CONSUMABLE" or _is_parts_new:
                        _units_list = []
                    elif _ship_form_new == "ASSEMBLY":
                        # v5H226z633 (대표 지시): 완제품 수량 N → 호기별 N줄. z629(1줄 qty=N) 되돌림 — 호기별 개별 관리.
                        _units_list = [{
                            "label": _logi.project_unit_label(_ptype, i + 1),
                            "amount": _per_unit,
                            "due_date": form.get("due_date", ""),
                            "ship_to": "",
                            "note": "",
                        } for i in range(max(1, unit_qty))]
                    else:
                        # 제품(SEMI)·기타(ETC) — 호기 없이 1줄 (수량=N)
                        _units_list = [{
                            "label": "",
                            "amount": round(_per_unit * max(1, unit_qty), 2),
                            "qty": max(1, unit_qty),
                            "due_date": form.get("due_date", ""),
                            "ship_to": "",
                            "note": "",
                        }]
                    _so_type_new = "PARTS_EXPORT" if _is_parts_new else None
                    _pwf.confirm_order_multi(
                        c, int(new_pid),
                        units=_units_list,
                        order_date=form.get("order_date", ""),
                        created_by=_u.get("id") or 0,
                        po_number=form.get("customer_po", ""),
                        so_type=_so_type_new,
                    )
        except Exception:
            return _finish_new(new_pid, "so_issue_failed")
        return _finish_new(new_pid)
    # v5H224: 모든 등록은 항상 프로젝트 상세 페이지로 이동 (이전: /projects 목록으로 이동했음)
    if new_pid:
        return _finish_new(new_pid)
    return RedirectResponse("/projects", status_code=303)


