@app.post("/as/{as_id}/status")
async def as_status_submit(request: Request, as_id: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_sales(u):
        return RedirectResponse("/home", 303)
    form = await request.form()
    to_status = (form.get("status") or "").strip()
    note = (form.get("note") or "").strip()
    with db_session() as c:
        _logi.as_status_change(c, as_id, to_status, changed_by=u.get("id"), note=note)
    return RedirectResponse(f"/as/{as_id}", 303)


@app.post("/as/{as_id}/edit")
async def as_edit_submit(request: Request, as_id: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_sales(u):
        return RedirectResponse("/home", 303)
    form = await request.form()
    data = {"is_paid": form.get("is_paid", "")}   # 체크박스 — 미체크 시 무상(0)
    for k in ("customer_name", "customer_phone", "customer_address", "product_name", "model_name",
              "purchase_date", "symptom", "inbound_tracking", "outbound_tracking", "shipped_date",
              "repair_fee", "repair_note", "note"):
        if k in form:
            data[k] = form.get(k)
    _aid = (form.get("assignee_id") or "").strip()
    if _aid.isdigit():
        data["assignee_id"] = int(_aid)
    with db_session() as c:
        _logi.as_ticket_update(c, as_id, data)
    return RedirectResponse(f"/as/{as_id}", 303)


# ==========================================================
# v5H226z122 (2026-05-19): 고객사 일괄 업로드 — 처음부터 다시 작성
#   - GET  /customers/import-template  → 양식 xlsx (안내 + 고객사 + 예제 3행)
#   - POST /customers/import-xlsx      → 업로드·파싱·검증 → 미리보기 JSON
#   - POST /customers/import-confirm   → 확정 INSERT / UPDATE (UPSERT by name)
#   시트: '고객사' row 1 헤더 / row 2+ 데이터 (31컬럼)
# ==========================================================
def _cust_import_parse_xlsx(file_bytes: bytes) -> list[dict]:
    """v5H226z122: 시트 '고객사' row 2+ 31컬럼 파싱 — 담당자 5명 × 5필드."""
    from openpyxl import load_workbook
    import io as _io
    import re as _re
    wb = load_workbook(_io.BytesIO(file_bytes), data_only=True, read_only=True)
    sheet_name = None
    # z122 신 양식 우선 → 구 양식 폴백
    for candidate in (CUST_DATA_SHEET_NAME, "🏢 고객사 일괄 등록", "고객사 데이터", "Customers"):
        if candidate in wb.sheetnames:
            sheet_name = candidate
            break
    if not sheet_name:
        raise ValueError(f"'{CUST_DATA_SHEET_NAME}' 시트를 찾을 수 없습니다")
    ws = wb[sheet_name]
    # 데이터 시작 행: z122 = row 2, z121 폴백 = row 5, 구 양식 = row 7
    if sheet_name == "🏢 고객사 일괄 등록":
        data_start = 5
    elif sheet_name == "고객사 데이터":
        data_start = 7
    else:
        data_start = 2

    def _to_str(v) -> str:
        return "" if v is None else str(v).strip()

    name_map: dict[str, int] = {}
    bizno_map: dict[str, tuple[int, str]] = {}
    try:
        with db_session() as _cc:
            for r in _cc.execute("SELECT id, name, biz_no FROM customers"):
                if r and r[0] and r[1]:
                    name_map[r[1]] = r[0]
                    bn = _re.sub(r"\D", "", r[2] or "")
                    if bn:
                        bizno_map[bn] = (r[0], r[1])
    except Exception:
        pass

    email_re = _re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
    EXPECTED_COLS = len(_CUST_XLSX_COLS)  # 31
    out = []
    row_no = 0
    for r in ws.iter_rows(min_row=data_start, values_only=True):
        row_no += 1
        actual_row = row_no + data_start - 1
        if not r or all((c is None or str(c).strip() == "") for c in r):
            continue
        cells = list(r) + [None] * (EXPECTED_COLS - len(r)) if len(r) < EXPECTED_COLS else list(r[:EXPECTED_COLS])
        # v5H226z147: key 기반 매핑 (_CUST_XLSX_COLS 순서와 1:1)
        rowmap = {}
        for ci, (_h, _w, _d, _rq, _g, key) in enumerate(_CUST_XLSX_COLS):
            rowmap[key] = _to_str(cells[ci]) if ci < len(cells) else ""

        name = rowmap.get("name", "")
        if not name:
            continue
        code = rowmap.get("code", "")
        biz_no_raw = rowmap.get("biz_no", "")
        ceo = rowmap.get("ceo_name", "")
        business_type = rowmap.get("business_type", "")
        business_item = rowmap.get("business_item", "")
        zipcode = rowmap.get("zipcode", "")
        address = rowmap.get("address", "")
        address_detail = rowmap.get("address_detail", "")
        phone = rowmap.get("phone", "")
        fax = rowmap.get("fax", "")
        sub_biz_no = rowmap.get("sub_biz_no", "")
        active_raw = rowmap.get("is_active", "")
        note = rowmap.get("note", "")

        if active_raw == "" or active_raw in ("1", "활성", "Y", "y", "True", "true"):
            is_active = 1
        elif active_raw in ("0", "비활성", "N", "n", "False", "false"):
            is_active = 0
        else:
            is_active = 1

        contacts = []
        for i in range(1, 6):
            cname = rowmap.get(f"c{i}_name", "")
            if not cname:
                continue
            contacts.append({
                "name": cname,
                "mobile": rowmap.get(f"c{i}_phone", ""),
                "email": rowmap.get(f"c{i}_email", ""),
                "department": rowmap.get(f"c{i}_dept", ""),
                "note": rowmap.get(f"c{i}_note", ""),
                "is_primary": 1 if i == 1 else 0,
            })

        errors, warnings = [], []
        # v5H226z147: 필수 강제 (대표 지시) — 사업자번호·대표자·주소
        if not biz_no_raw:
            errors.append("사업자번호 누락(필수)")
        if not ceo:
            errors.append("대표자명 누락(필수)")
        if not address:
            errors.append("주소 누락(필수)")
        biz_no_norm = _re.sub(r"\D", "", biz_no_raw) if biz_no_raw else ""
        biz_no_display = biz_no_raw
        if biz_no_raw:
            if len(biz_no_norm) != 10 or not biz_no_norm.isdigit():
                errors.append(f"사업자번호 형식 오류(10자리 숫자): '{biz_no_raw}'")
            else:
                biz_no_display = f"{biz_no_norm[:3]}-{biz_no_norm[3:5]}-{biz_no_norm[5:]}"

        for ci, ct in enumerate(contacts, 1):
            em = ct.get("email", "")
            if em and not email_re.match(em):
                warnings.append(f"{ci}담당자 이메일 형식: '{em}'")

        existing_id = name_map.get(name)
        action = "update" if existing_id else "create"
        if biz_no_norm and biz_no_norm in bizno_map:
            other_id, other_name = bizno_map[biz_no_norm]
            if other_name != name:
                warnings.append(f"사업자번호 중복: 기존 '{other_name}' (#{other_id})")

        out.append({
            "row_no": actual_row,
            "code": code,
            "name": name, "biz_no": biz_no_display, "biz_no_norm": biz_no_norm,
            "ceo_name": ceo, "address": address,
            "business_type": business_type, "business_item": business_item,
            "zipcode": zipcode, "address_detail": address_detail,
            "fax": fax, "sub_biz_no": sub_biz_no,
            "phone": phone, "note": note, "is_active": is_active,
            "contacts": contacts,
            "manager_name": (contacts[0]["name"] if contacts else ""),
            "email": "", "tier": "",
            "_existing_id": existing_id, "_action": action,
            "_errors": errors, "_warnings": warnings,
        })
    return out


@app.get("/customers/import-template")
async def customers_import_template(request: Request):
    """v5H226z122 (2026-05-19): 양식 — 안내 + 고객사 (row1 헤더 + row2~4 예제 3행)."""
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_sales(u):
        return RedirectResponse("/home", 303)
    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    except ImportError:
        return JSONResponse({"error": "openpyxl 미설치 — pip install openpyxl"}, 500)
    from datetime import datetime as _dt

    wb = Workbook()
    ws_guide = wb.active
    ws_guide.title = CUST_GUIDE_SHEET_NAME
    _cust_xlsx_build_guide(ws_guide)
    ws_data = wb.create_sheet(CUST_DATA_SHEET_NAME)
    _cust_xlsx_build_data_headers(ws_data)

    examples = [
        ["GOODIX", "211-87-12345", "장 회장", "경기도 평택시 ...", "활성", "주력 고객사",
         "이매니저", "031-555-1234", "contact@goodix.kr", "관리팀", "25일 마감담당",
         "김부장", "031-555-1235", "kim@goodix.kr", "구매2팀", "결제 담당",
         "", "", "", "", "",
         "", "", "", "", "",
         "", "", "", "", ""],
        ["삼성디스플레이", "124-81-00012", "한 사장", "충남 천안시 ...", "활성", "",
         "박과장", "041-589-1234", "po@sds.com", "제조기술", "자료 빠른 회신 선호",
         "", "", "", "", "",
         "", "", "", "", "",
         "", "", "", "", "",
         "", "", "", "", ""],
        ["G2TOUCH", "", "", "서울시 강남구 ...", "활성", "신규 거래처",
         "김대표", "02-3456-7890", "g2@g2touch.com", "", "",
         "", "", "", "", "",
         "", "", "", "", "",
         "", "", "", "", "",
         "", "", "", "", ""],
    ]
    example_fill = PatternFill("solid", fgColor="FFFBEB")
    example_font = Font(size=10, color="9A3412", italic=True)
    thin = Side(style="thin", color="EEEEEE")
    bd_light = Border(left=thin, right=thin, top=thin, bottom=thin)
    for row_offset, row_data in enumerate(examples):
        r_idx = 2 + row_offset
        for c_idx, v in enumerate(row_data, 1):
            cell = ws_data.cell(row=r_idx, column=c_idx, value=v)
            cell.font = example_font
            cell.fill = example_fill
            cell.alignment = Alignment(horizontal="left", vertical="center")
            cell.border = bd_light

    import io
    from urllib.parse import quote as _q
    buf = io.BytesIO(); wb.save(buf); buf.seek(0)
    today = _dt.now().strftime("%Y%m%d")
    return Response(
        content=buf.getvalue(),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": (
            f'attachment; filename="KNK_customers_import_template.xlsx"; '
            f"filename*=UTF-8''{_q(f'KNK_고객사_일괄등록_템플릿_{today}.xlsx')}")},
    )


@app.post("/customers/import-xlsx")
async def customers_import_xlsx(request: Request, xlsx: UploadFile = File(...)):
    """v5H226z122: 업로드 → 파싱 + 검증 → 미리보기 JSON 반환."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    try:
        body = await xlsx.read()
        rows = _cust_import_parse_xlsx(body)
    except Exception as e:
        return JSONResponse({"ok": False, "error": f"파싱 실패: {e}"}, 400)
    create_count = sum(1 for r in rows if r["_action"] == "create" and not r["_errors"])
    update_count = sum(1 for r in rows if r["_action"] == "update" and not r["_errors"])
    error_count = sum(1 for r in rows if r["_errors"])
    warning_count = sum(1 for r in rows if r["_warnings"] and not r["_errors"])
    return JSONResponse({
        "ok": True, "rows": rows, "total": len(rows),
        "create_count": create_count, "update_count": update_count,
        "error_count": error_count, "warning_count": warning_count,
    })


@app.post("/customers/import-confirm")
async def customers_import_confirm(request: Request):
    """v5H226z122: 미리보기 확정 → INSERT / UPDATE. 담당자 5명 INSERT (중복 이름 skip)."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "login_required"}, 401)
    if not can_use_sales(u):
        return JSONResponse({"ok": False, "error": "permission_denied"}, 403)
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_json"}, 400)
    rows = body.get("rows") or []
    if not isinstance(rows, list) or not rows:
        return JSONResponse({"ok": False, "error": "no_rows"}, 400)

    created, updated, failed = [], [], []
    try:
        from . import customer_tier as _ct
    except Exception:
        _ct = None

    with db_session() as c:
        for r in rows:
            try:
                name = (r.get("name") or "").strip()
                if not name:
                    failed.append({"row_no": r.get("row_no"), "name": "",
                                   "error": "고객사명 누락"})
                    continue
                biz_no = (r.get("biz_no") or "").strip()
                ceo = (r.get("ceo_name") or "").strip()
                manager = (r.get("manager_name") or "").strip()
                phone = (r.get("phone") or "").strip()
                email = (r.get("email") or "").strip()
                address = (r.get("address") or "").strip()
                tier = (r.get("tier") or "").strip().upper()
                is_active = int(r.get("is_active") if r.get("is_active") is not None else 1)
                note = (r.get("note") or "").strip()
                # v5H226z147: 추가 사업장 항목
                code = (r.get("code") or "").strip()
                business_type = (r.get("business_type") or "").strip()
                business_item = (r.get("business_item") or "").strip()
                zipcode = (r.get("zipcode") or "").strip()
                address_detail = (r.get("address_detail") or "").strip()
                fax = (r.get("fax") or "").strip()
                sub_biz_no = (r.get("sub_biz_no") or "").strip()

                existing = c.execute(
                    "SELECT id FROM customers WHERE name=?", (name,)
                ).fetchone()
                if existing:
                    cid = existing["id"] if hasattr(existing, "keys") else existing[0]
                    sets, vals = [], []
                    for col, v in (
                        ("biz_no", biz_no), ("ceo_name", ceo),
                        ("manager_name", manager), ("phone", phone),
                        ("email", email), ("address", address),
                        ("note", note),
                        ("business_type", business_type), ("business_item", business_item),
                        ("zipcode", zipcode), ("address_detail", address_detail),
                        ("fax", fax), ("sub_biz_no", sub_biz_no),
                    ):
                        if v:
                            sets.append(f"{col}=?")
                            vals.append(v)
                    sets.append("is_active=?")
                    vals.append(is_active)
                    if sets:
                        vals.append(cid)
                        c.execute(
                            f"UPDATE customers SET {','.join(sets)} WHERE id=?",
                            tuple(vals)
                        )
                    if _ct:
                        try: _ct.refresh_customer_tier(c, cid)
                        except Exception: pass
                    contacts_list = r.get("contacts") or []
                    for ct in contacts_list:
                        ct_name = (ct.get("name") or "").strip()
                        if not ct_name:
                            continue
                        existing_ct = c.execute(
                            "SELECT id FROM customer_contacts WHERE customer_id=? AND name=?",
                            (cid, ct_name)
                        ).fetchone()
                        if existing_ct:
                            continue
                        c.execute(
                            "INSERT INTO customer_contacts(customer_id, name, department, mobile, email, is_primary, role) VALUES(?,?,?,?,?,?,?)",
                            (cid, ct_name, ct.get("department", ""),
                             ct.get("mobile", ""), ct.get("email", ""),
                             int(ct.get("is_primary", 0)), "기타")
                        )
                    updated.append({"row_no": r.get("row_no"), "id": cid, "name": name})
                else:
                    fields = {
                        "name": name, "tier": tier or "일반",
                        "biz_no": biz_no, "ceo_name": ceo,
                        "manager_name": manager, "phone": phone,
                        "email": email, "address": address,
                        "is_active": is_active, "note": note,
                        "business_type": business_type, "business_item": business_item,
                        "zipcode": zipcode, "address_detail": address_detail,
                        "fax": fax, "sub_biz_no": sub_biz_no,
                        "code": code or _gen_customer_code(c),   # 비면 자동 부여
                    }
                    cols = ",".join(fields.keys())
                    ph = ",".join(["?"] * len(fields))
                    c.execute(
                        f"INSERT INTO customers({cols}) VALUES({ph})",
                        tuple(fields.values())
                    )
                    new_id = c.execute("SELECT last_insert_rowid()").fetchone()[0]
                    contacts_list = r.get("contacts") or []
                    for ct in contacts_list:
                        ct_name = (ct.get("name") or "").strip()
                        if not ct_name:
                            continue
                        c.execute(
                            "INSERT INTO customer_contacts(customer_id, name, department, mobile, email, is_primary, role) VALUES(?,?,?,?,?,?,?)",
                            (new_id, ct_name, ct.get("department", ""),
                             ct.get("mobile", ""), ct.get("email", ""),
                             int(ct.get("is_primary", 0)), "기타")
                        )
                    if _ct:
                        try: _ct.refresh_customer_tier(c, new_id)
                        except Exception: pass
                    created.append({"row_no": r.get("row_no"), "id": new_id, "name": name})
            except Exception as e:
                failed.append({"row_no": r.get("row_no"),
                               "name": r.get("name"), "error": str(e)})

    return JSONResponse({
        "ok": True,
        "created_count": len(created),
        "updated_count": len(updated),
        "failed_count": len(failed),
        "created": created,
        "updated": updated,
        "failed": failed,
    })


@app.get("/projects/{pid}/edit", response_class=HTMLResponse)
async def projects_edit_form(request: Request, pid: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not can_use_sales(u):
        return RedirectResponse("/home", 303)
    # v5H101: 편집 폼 진입 시 SO 기준으로 자가치유
    #   납기/발주일/수주액 = SO 합계·MAX·MIN 으로 정정 후 폼 노출
    try:
        with db_session() as c2:
            sos = _pwf.get_project_orders(c2, pid)
            if sos:
                so_sum = sum(float(o.get("total_amount") or 0) for o in sos)
                dues = [o.get("due_date") for o in sos if o.get("due_date")]
                ords = [o.get("order_date") for o in sos if o.get("order_date")]
                heal_pairs = [("order_amount", so_sum)]
                if dues:
                    heal_pairs.append(("due_date", max(dues)))
                if ords:
                    heal_pairs.append(("order_date", min(ords)))
                for col, val in heal_pairs:
                    try:
                        c2.execute(f"UPDATE projects SET {col}=? WHERE id=?", (val, pid))
                    except Exception:
                        pass
    except Exception:
        pass
    p = _logi.projects_get_logi(pid)
    if not p:
        return RedirectResponse("/projects", status_code=303)
    # v5H174: 등록자/등록일시 표시용 — created_by → 사용자명 lookup
    # v5H226z800 (대표 지시·규칙): 등록자 = 이름 직책 부서 [[knk_name_display_rule]]
    p = dict(p)
    try:
        if p.get("created_by"):
            with db_session() as _c:
                _u_row = _c.execute(
                    "SELECT name FROM users WHERE id=?", (p.get("created_by"),)
                ).fetchone()
                if _u_row:
                    p["created_by_name"] = _u_row[0]
                p["created_by_disp"] = user_disp_by_id(_c, p.get("created_by"), p.get("created_by_name") or "")
    except Exception:
        pass
    # v5H103: SO 존재 여부 → 폼 수주액 readonly 안내용
    has_orders = False
    try:
        with db_session() as c3:
            row = c3.execute(
                "SELECT COUNT(*) FROM orders WHERE project_id=?", (pid,)
            ).fetchone()
            has_orders = (row[0] or 0) > 0
    except Exception:
        pass
    return ctx(request, "project_form.html",
               user=u, active="sales_projects",
               project=p,
               STAGES=_logi.STAGES, STATUSES=_logi.LOGI_STATUSES,
               PO_TYPES=_logi.PO_TYPES,
               PROJECT_TYPES=_logi.PROJECT_TYPES,
               PROJECT_TYPE_LABELS=_logi.PROJECT_TYPE_LABELS,
               customers=_logi.customers_for_picker(),
               has_orders=has_orders)


@app.post("/projects/{pid}/edit")
async def projects_edit_submit(request: Request, pid: int):
    """v5H70: 폼 실제 필드명(name/customer_name)과 정합 + 콤마 자동 정리.
    v5H52 의 /projects/new 와 같은 패턴 — edit 도 동일 수정."""
    _u = get_user(request)
    if not _u:
        return RedirectResponse("/login", 303)
    if not can_use_sales(_u):
        return RedirectResponse("/home", 303)
    form = await request.form()
    # v5H226z150 (2026-06-02 대표 지시): SSO 단일 로그인 전환으로 본인 WORKS 비밀번호가
    #   없어 비밀번호 검증 폐기 → '잠금 해제(확인창) 통과' 만 요구. 변경은 이력에 기록됨.
    #   TODO(향후): 여기에 '잠금해제 권한 부여자만' 전용 권한 체크 추가 예정 (현재는 can_use_sales).
    # v5H226z354 (대표 지시): 빠른 폼 수정 모드(quick=1)에서 온 오류는 빠른 폼으로 복귀(정식 폼으로 튕기지 않게)
    _is_quick_edit = (form.get("quick") or "").strip().lower() in ("1", "true", "on", "yes")
    _edit_base = f"/projects/{pid}/quick-edit" if _is_quick_edit else f"/projects/{pid}/edit"
    if (form.get("unlock_verified") or "") != "1":
        return RedirectResponse(f"{_edit_base}?error=unlock_required", status_code=303)
    project_name = (form.get("name") or form.get("project_name") or "").strip()
    customer = (form.get("customer_name") or form.get("customer") or "").strip()
    biz_div = (form.get("biz_div") or "").strip()
    # v5H226s: 변경 전 메타값 캡처 (cascade 비교용)
    _old_meta = {}
    try:
        with db_session() as _mc:
            _mr = _mc.execute(
                "SELECT due_date, order_date, currency FROM projects WHERE id=?", (pid,)
            ).fetchone()
            if _mr:
                _old_meta = {"due_date": _mr["due_date"], "order_date": _mr["order_date"],
                             "currency": _mr["currency"]}
    except Exception:
        _old_meta = {}
    # v5H192: 필수 필드 검증 (비고 제외)
    if not project_name:
        return RedirectResponse(f"{_edit_base}?error=name_required", status_code=303)
    if not customer:
        return RedirectResponse(f"{_edit_base}?error=customer_required", status_code=303)
    if customer:
        with db_session() as _cc:
            _ok = _cc.execute(
                "SELECT 1 FROM customers WHERE name=? OR alias=? LIMIT 1", (customer, customer)  # v5H226z654: 상호 또는 시스템명 등록이면 통과
            ).fetchone()
        if not _ok:
            from urllib.parse import quote as _q
            return RedirectResponse(
                f"{_edit_base}?error=customer_not_registered&cust={_q(customer)}",
                status_code=303
            )
    raw_amt = (form.get("order_amount") or "0").strip().replace(",", "")
    try:
        amt = float(raw_amt) if raw_amt else 0
    except ValueError:
        amt = 0
    # v5H132: 단가/수량 받아서 amt 재계산
    raw_price = (form.get("unit_price") or "0").strip().replace(",", "")
    try:
        unit_price = float(raw_price) if raw_price else 0.0
    except ValueError:
        unit_price = 0.0
    raw_qty = (form.get("unit_qty") or "1").strip()
    try:
        unit_qty = int(float(raw_qty))
    except (TypeError, ValueError):
        unit_qty = 1
    if unit_qty < 1:
        unit_qty = 1
    if unit_qty > 100:
        unit_qty = 100
    if unit_price > 0:
        amt = unit_price * unit_qty
    elif amt > 0 and unit_qty >= 1:
        unit_price = amt / unit_qty
    status_val = form.get("status", "초기협의") or "초기협의"
    # v5H137: 프로젝트 유형 + 부모 프로젝트
    _ptype = (form.get("project_type") or "NEW_EQUIP").strip().upper()
    if _ptype not in _logi.PROJECT_TYPES:
        _ptype = "NEW_EQUIP"
    _parent_id_raw = (form.get("parent_project_id") or "").strip()
    _parent_id = int(_parent_id_raw) if _parent_id_raw.isdigit() else None
    if _ptype not in ("CONSUMABLE", "SERVICE"):
        _parent_id = None
    _logi.projects_update_logi(pid, {
        "_changed_by": _u.get("id"),
        # v5H226z652 (대표 지시): 콤보박스에서 고른 종사업장(customer_id) 우선 적용 — 간편폼/picker 사용 폼의 수정 경로 반영
        "customer_id": (int(form.get("customer_id")) if (form.get("customer_id") or "").strip().isdigit() else None),
        "biz_div": biz_div, "project_name": project_name, "customer": customer,
        "model": form.get("model", ""),
        # v5H226z211 (대표 지시): 장비명 — 관리번호=장비 단위
        "equip_name": form.get("equip_name", ""),
        # v5H214: stage 는 status 에서 자동 매핑
        "stage": stage_from_status(status_val),
        "po_type": form.get("po_type", "신규") or "신규",
        "status": status_val,
        "customer_po": form.get("customer_po", ""),
        "currency": (form.get("currency", "KRW") or "KRW").upper(),
        # v5H171: 수정 시에도 fx_rate / amount_krw 저장
        "fx_rate": (lambda v: float(v) if (v or "").strip() else None)(form.get("fx_rate", "")),
        "amount_krw": (lambda v: float(v) if (v or "").strip() else None)(form.get("amount_krw", "")),
        "is_export": form.get("is_export", "0"),
        "order_amount": amt,
        "unit_qty": unit_qty,
        "unit_price": unit_price if (unit_price is not None and unit_price > 0) else None,  # v5H226z441: None 안전(형태=상품 부품등록 시 unit_price=None)
        "order_date": form.get("order_date", ""),
        "due_date": form.get("due_date", ""),
        # v5H201: 제안 단계 일정 (수주확정 전 스케줄용)
        "proposal_date": form.get("proposal_date", ""),
        "quotation_date": form.get("quotation_date", ""),
        # v5H226z: 출고 형태 (NEW_EQUIP 만 의미 있음, 그 외는 ASSEMBLY 폴백)
        "shipment_form": (form.get("shipment_form") or "ASSEMBLY").strip().upper(),
        "pm": form.get("pm", ""), "sales": form.get("sales", ""),
        "note": form.get("note", ""),
        "project_type": _ptype,
        "parent_project_id": _parent_id,
        # v5H226z166: 고객사 담당자
        "cc_name": form.get("cc_name", ""), "cc_dept": form.get("cc_dept", ""),
        "cc_position": form.get("cc_position", ""), "cc_phone": form.get("cc_phone", ""),
        "cc_email": form.get("cc_email", ""), "cc_note": form.get("cc_note", ""),
        # v5H226z195: 2단계 발주(법인 경유)
        "two_tier_order": form.get("two_tier_order", ""),
        "secondary_customer": form.get("secondary_customer", ""),
        "final_amount": form.get("final_amount", ""),
    })
    # v5H226z354 (대표 지시): 빠른 폼 수정 모드는 납품위치(ship_to)를 대표 SO(orders 최신)에 반영.
    #   정식 폼은 호기별 unit_ship[] 을 쓰므로 top-level 'ship_to' 를 보내지 않음 → 빠른 폼에만 적용(필드 존재 시).
    if _is_quick_edit and (form.get("ship_to") is not None):
        _ship_v = (form.get("ship_to") or "").strip()
        if _ship_v:
            try:
                with db_session() as _sc:
                    _ocols = {r[1] for r in _sc.execute("PRAGMA table_info(orders)").fetchall()}
                    if "ship_to" in _ocols:
                        _so_r = _sc.execute(
                            "SELECT id FROM orders WHERE project_id=? ORDER BY id DESC LIMIT 1", (pid,)
                        ).fetchone()
                        if _so_r:
                            _sc.execute("UPDATE orders SET ship_to=? WHERE id=?", (_ship_v, _so_r[0]))
            except Exception as _ship_err:
                print(f"[v5H226z354] quick-edit ship_to err: {_ship_err}")
    # v5H87: 수정 후 status 가 won 인데 SO 가 아직 없으면 자동 발행
    # v5H132: 수량 N → N개 호기 라인
    # v5H142: NEW_EQUIP 만 자동 SO 발행
    if status_val in _logi.WON_STATUSES and _ptype == "NEW_EQUIP":
        try:
            with db_session() as c:
                exists = c.execute(
                    "SELECT 1 FROM orders WHERE project_id=? LIMIT 1", (pid,)
                ).fetchone()
                if not exists:
                    _per_unit = unit_price if unit_price > 0 else (amt / max(1, unit_qty))
                    # v5H226z633 (대표 지시): 완제품 수량 N → 호기별 N줄. z629(1줄 qty=N) 되돌림.
                    _units_list = [{
                        "label": _logi.project_unit_label(_ptype, i + 1),
                        "amount": _per_unit,
                        "due_date": form.get("due_date", ""),
                        "ship_to": "",
                        "note": "",
                    } for i in range(max(1, unit_qty))]
                    _pwf.confirm_order_multi(
                        c, int(pid),
                        units=_units_list,
                        order_date=form.get("order_date", ""),
                        created_by=_u.get("id") or 0,
                        po_number=form.get("customer_po", ""),
                    )
        except Exception:
            pass
    # v5H226r: 수정 후 status 변경분 SO/호기 cascade
    try:
        with db_session() as c:
            _pwf.cascade_project_status_to_so(c, int(pid), status_val, _u.get("id"))
    except Exception as _csc_err:
        print(f"[v5H226r] edit-submit cascade err: {_csc_err}")
    # v5H226s: 메타필드(due_date/order_date/currency) cascade
    try:
        _new_meta = {
            "due_date":   form.get("due_date", "") or "",
            "order_date": form.get("order_date", "") or "",
            "currency":   (form.get("currency", "KRW") or "KRW").upper(),
        }
        with db_session() as c:
            _pwf.cascade_project_meta_to_so(c, int(pid), _old_meta, _new_meta, _u.get("id"))
    except Exception as _csc_err:
        print(f"[v5H226s] edit-submit meta cascade err: {_csc_err}")
    return RedirectResponse(f"/project/{pid}", status_code=303)


@app.post("/projects/{pid}/delete")
async def projects_delete_submit(request: Request, pid: int):
    """v5H72: 프로젝트 삭제 — 더 엄격한 can_delete_sales 권한.
    v5H98: 삭제 실패 시 구체적 FK/sqlite 에러 메시지 JSON 으로 반환.
    v5H226l: kind=consumable 이면 legacy consumable_orders 행 삭제로 분기."""
    _u = get_user(request)
    if not _u:
        return RedirectResponse("/login", 303)
    if not can_delete_sales(_u):
        return JSONResponse({"error": "권한 없음",
                              "message": "프로젝트 삭제는 영업팀 팀장 또는 위임받은 등록권한자만 가능합니다."}, 403)
    _form = await request.form()
    _kind = (_form.get("kind") or "project").strip().lower()
    try:
        if _kind == "consumable":
            from . import consumables as _co_mod
            _co_mod.co_delete(pid)
        else:
            _logi.projects_delete_logi(pid)
    except PermissionError as e:
        # v5H226z176: 관리코드(수주확정) 부여 건 — 정책상 삭제 불가
        return JSONResponse({"ok": False, "error": "삭제 불가", "message": str(e)}, 403)
    except Exception as e:
        import traceback
        err_msg = str(e)
        tb = traceback.format_exc()
        # 어느 테이블이 막는지 힌트 추출 (FOREIGN KEY constraint failed)
        hint = ""
        if "FOREIGN KEY" in err_msg or "foreign key" in err_msg.lower():
            hint = ("관련 자식 데이터가 남아 있어 삭제 차단됨. "
                    "잠시 후 다시 시도하거나 시스템 관리자에게 보고하세요.")
        return JSONResponse({
            "ok": False,
            "error": "삭제 실패",
            "message": f"{err_msg}\n{hint}",
            "trace": tb[-500:],  # 마지막 500자만
        }, 500)
    return JSONResponse({"ok": True, "message": "프로젝트 삭제 완료"})


@app.post("/projects/bulk-delete")
async def projects_bulk_delete(request: Request):
    """v5H179: 다건 프로젝트 일괄 삭제. ids=콤마구분 또는 ids[]=반복.
    개별 실패는 무시하고 계속 진행 — 결과 집계 반환."""
    _u = get_user(request)
    if not _u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_delete_sales(_u):
        return JSONResponse({"error": "권한 없음",
                              "message": "프로젝트 삭제는 영업팀 팀장 또는 위임받은 등록권한자만 가능합니다."}, 403)
    form = await request.form()
    raw = form.getlist("ids[]") or form.getlist("ids")
    if not raw and form.get("ids"):
        raw = [s.strip() for s in str(form.get("ids")).split(",") if s.strip()]
    co_raw = form.getlist("co_ids[]") or form.getlist("co_ids")  # v5H226l: legacy 소모품 묶음
    pids: list[int] = []
    for v in raw:
        try:
            pids.append(int(v))
        except (TypeError, ValueError):
            continue
    co_ids: list[int] = []
    for v in co_raw:
        try:
            co_ids.append(int(v))
        except (TypeError, ValueError):
            continue
    if not pids and not co_ids:
        return JSONResponse({"ok": False, "message": "삭제할 ID 가 없습니다"}, 400)
    if len(pids) + len(co_ids) > 200:
        return JSONResponse({"ok": False, "message": "한 번에 200건 초과 불가"}, 400)
    ok, fail = [], []
    for pid in pids:
        try:
            _logi.projects_delete_logi(pid)
            ok.append(pid)
        except Exception as e:
            fail.append({"id": pid, "kind": "project", "error": str(e)[:200]})
    if co_ids:
        try:
            from . import consumables as _co_mod
        except Exception:
            _co_mod = None
        for cid in co_ids:
            try:
                if _co_mod is None:
                    raise RuntimeError("consumables 모듈 로드 실패")
                _co_mod.co_delete(cid)
                ok.append(cid)
            except Exception as e:
                fail.append({"id": cid, "kind": "consumable", "error": str(e)[:200]})
    return JSONResponse({
        "ok": True,
        "deleted": len(ok),
        "failed": len(fail),
        "fail_details": fail[:20],  # 처음 20건만
        "message": f"{len(ok)}건 삭제 완료" + (f", {len(fail)}건 실패" if fail else ""),
    })


@app.post("/customers/bulk-delete")
async def customers_bulk_delete(request: Request):
    """v5H180: 다건 고객사 일괄 삭제.
    안전 정책:
      - can_delete_sales 권한 필요 (영업팀 팀장/등록권한자)
      - 프로젝트(또는 SO/견적)가 연결된 고객사는 삭제 거부 (FK 안전)
      - 한 번에 200건 제한
      - 개별 실패는 집계 후 계속 진행
    """
    _u = get_user(request)
    if not _u:
        return JSONResponse({"error": "로그인 필요"}, 401)
    if not can_delete_sales(_u):
        return JSONResponse({
            "error": "권한 없음",
            "message": "고객사 삭제는 영업팀 팀장 또는 위임받은 등록권한자만 가능합니다."
        }, 403)
    form = await request.form()
    raw = form.getlist("ids[]") or form.getlist("ids")
    if not raw and form.get("ids"):
        raw = [s.strip() for s in str(form.get("ids")).split(",") if s.strip()]
    cids: list[int] = []
    for v in raw:
        try:
            cids.append(int(v))
        except (TypeError, ValueError):
            continue
    if not cids:
        return JSONResponse({"ok": False, "message": "삭제할 ID 가 없습니다"}, 400)
    if len(cids) > 200:
        return JSONResponse({"ok": False, "message": "한 번에 200건 초과 불가"}, 400)
    ok, fail = [], []
    with db_session() as c:
        for cid in cids:
            try:
                # FK 검증: 프로젝트/SO/견적/PO 연결 여부 확인
                proj_n = (c.execute(
                    "SELECT COUNT(*) FROM projects WHERE customer_id=?", (cid,)
                ).fetchone() or [0])[0]
                ord_n = 0
                try:
                    ord_n = (c.execute(
                        "SELECT COUNT(*) FROM orders WHERE customer_id=?", (cid,)
                    ).fetchone() or [0])[0]
                except Exception:
                    pass
                if proj_n or ord_n:
                    parts = []
                    if proj_n: parts.append(f"프로젝트 {proj_n}건")
                    if ord_n: parts.append(f"수주 {ord_n}건")
                    fail.append({"id": cid,
                                 "error": f"연결 데이터 존재 — {', '.join(parts)}. 먼저 정리 필요"})
                    continue
                # 고객사 담당자 (있으면) → cascade 삭제
                try:
                    c.execute("DELETE FROM customer_contacts WHERE customer_id=?", (cid,))
                except Exception:
                    pass
                c.execute("DELETE FROM customers WHERE id=?", (cid,))
                ok.append(cid)
            except Exception as e:
                fail.append({"id": cid, "error": str(e)[:200]})
    return JSONResponse({
        "ok": True,
        "deleted": len(ok),
        "failed": len(fail),
        "fail_details": fail[:20],
        "message": f"{len(ok)}건 삭제 완료" + (f", {len(fail)}건 실패" if fail else ""),
    })


