# =====================================================
# Top3 S1 4차 — 미수금 추적 + 수금 알림 자동 (2026-04-26)
# 헬퍼 _outstanding_receivables / check_receivable_alerts.
# 알림 통합 (사이클 2026-04-26 notify_user SALES) 활용 · 1시간 중복 방지 내장.
# G1~G5 핫패치 보존 · v2 본체 무수정 · 외부 자산 0건.
# =====================================================

def _parse_terms_days(terms: str) -> int:
    """payment_terms 문자열 → 일수. NET30/30일/선금 등 휴리스틱.
    매칭 실패 시 30 (기본 NET30)."""
    if not terms:
        return 30
    s = str(terms).upper().replace(" ", "")
    # NET#, #일, #DAYS
    import re
    m = re.search(r"(\d{1,3})", s)
    if m:
        try:
            d = int(m.group(1))
            if 0 < d <= 365:
                return d
        except Exception:
            pass
    if "선금" in str(terms) or "CASH" in s or "현금" in str(terms):
        return 0
    return 30


def _outstanding_receivables(c, only_overdue: bool = False):
    """미수금 건별 집계 — orders.total_amount - SUM(receipts_payment.amount).
    z745b(대표 지시): 만기 = **세금계산서 발행일 + 고객사 pay_days**(납품·수금 화면과 통일).
      발행일 = 그 수주 호기(order_items.tax_invoice_date) 중 가장 이른 날(없으면 orders 폴백).
      발행일 없으면(미발행) 발주일 기준으로 폴백(보수적). pay_days 미설정(0)이면 레거시 payment_terms 폴백.
    등급: CURRENT(미만기) / D-30 / D-60 / D-90+ (연체일 기준). Returns: list of dicts (overdue desc)."""
    today = date.today()
    oic = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
    ordc = {r[1] for r in c.execute("PRAGMA table_info(orders)").fetchall()}
    cusc = {r[1] for r in c.execute("PRAGMA table_info(customers)").fetchall()}
    _pd = "COALESCE(cu.pay_days,0)" if "pay_days" in cusc else "0"
    # 발행일 per order: 호기 tax_invoice_date 우선 → orders 폴백, 가장 이른 날
    i_td = "oi.tax_invoice_date" if "tax_invoice_date" in oic else "NULL"
    o_td = "o.tax_invoice_date" if "tax_invoice_date" in ordc else "NULL"
    issue_map = {}
    try:
        for r in c.execute(f"SELECT oi.order_id AS oid, {i_td} AS itd, {o_td} AS otd "
                           f"FROM order_items oi JOIN orders o ON o.id=oi.order_id"):
            d = dict(r)
            dt = (str(d["itd"] or "").strip() or str(d["otd"] or "").strip())[:10]
            if dt:
                oid = d["oid"]
                if oid not in issue_map or dt < issue_map[oid]:
                    issue_map[oid] = dt
    except Exception:
        issue_map = {}
    rows = c.execute(
        f"""SELECT o.id AS order_id, o.order_no, o.order_date, o.due_date,
                  o.total_amount, o.status, o.customer_id,
                  COALESCE(cu.name,'-') AS customer_name,
                  {_pd} AS pay_days,
                  COALESCE((SELECT SUM(amount) FROM receipts_payment rp
                            WHERE rp.order_id=o.id), 0) AS paid_total,
                  COALESCE((SELECT terms FROM payment_terms pt
                            WHERE pt.customer_id=o.customer_id
                            ORDER BY pt.id DESC LIMIT 1), '') AS terms
           FROM orders o
           LEFT JOIN customers cu ON cu.id = o.customer_id
           WHERE o.status IN ('SHIPPED','INVOICED')
             AND o.total_amount > 0"""
    ).fetchall()
    out = []
    for r in rows:
        d = dict(r)
        outstanding = (d["total_amount"] or 0) - (d["paid_total"] or 0)
        if outstanding <= 0:
            continue
        # 만기 기준일 = 세금계산서 발행일(있으면) → 없으면 발주일 폴백
        issue_date = issue_map.get(d["order_id"], "")
        base_iso = issue_date or (d["order_date"] or today.isoformat())
        try:
            base = datetime.strptime(base_iso[:10], "%Y-%m-%d").date()
        except Exception:
            base = today
        # 결제조건 일수 = 고객사 pay_days(>0) → 없으면 레거시 payment_terms
        _pdv = int(d.get("pay_days") or 0)
        days_terms = _pdv if _pdv > 0 else _parse_terms_days(d["terms"])
        due = base + timedelta(days=days_terms)
        overdue_days = (today - due).days  # 음수 = 만기 이전
        if only_overdue and overdue_days <= 0:
            continue
        if overdue_days <= 0:
            grade = "CURRENT"
        elif overdue_days <= 30:
            grade = "D-30"
        elif overdue_days <= 60:
            grade = "D-60"
        else:
            grade = "D-90+"
        d["outstanding"] = outstanding
        d["issue_date"] = issue_date
        d["due_base"] = "발행일" if issue_date else "발주일(미발행)"
        d["due_date_calc"] = due.isoformat()
        d["overdue_days"] = overdue_days
        d["grade"] = grade
        d["terms_days"] = days_terms
        out.append(d)
    out.sort(key=lambda x: (-x["overdue_days"], -x["outstanding"]))
    return out


def _outstanding_summary(items):
    """등급별 집계 KPI."""
    grades = {"CURRENT": 0.0, "D-30": 0.0, "D-60": 0.0, "D-90+": 0.0}
    counts = {"CURRENT": 0, "D-30": 0, "D-60": 0, "D-90+": 0}
    total = 0.0
    overdue_total = 0.0
    for it in items:
        g = it["grade"]
        amt = it["outstanding"]
        grades[g] = grades.get(g, 0.0) + amt
        counts[g] = counts.get(g, 0) + 1
        total += amt
        if g != "CURRENT":
            overdue_total += amt
    return {
        "by_grade": grades, "counts": counts,
        "total": total, "overdue_total": overdue_total,
        "n_total": len(items),
        "overdue_rate": (overdue_total / total * 100.0) if total > 0 else 0.0,
    }


def check_receivable_alerts():
    """수금 알림 트리거 — 만기 임박(D-7) + 연체(D+1, D+30, D+60).
    notify_user(SALES, ...) 사용 (1시간 중복 방지 내장).
    수신자: orders.created_by (수주 등록자) → can_use_sales 폴백.
    Returns: {sent: int, skipped: int, items: int}.
    """
    sent = 0; skipped = 0; total_items = 0
    with db_session() as c:
        items = _outstanding_receivables(c)
        total_items = len(items)
        # 영업 권한자 폴백 (주된 알림 대상 미상시)
        sales_uids = [r[0] for r in c.execute(
            "SELECT id FROM users WHERE can_use_sales=1 OR role IN ('admin','ceo')"
        ).fetchall()]
        for it in items:
            ov = it["overdue_days"]
            order_no = it.get("order_no") or f"#{it['order_id']}"
            cust = it.get("customer_name") or "-"
            outstanding = it.get("outstanding") or 0
            # 발송 조건: 만기 7일 임박 OR 연체 1/30/60일 도달
            tag = None
            if ov == -7:
                tag = "만기 임박 (D-7)"
            elif ov == 1:
                tag = "연체 1일"
            elif ov == 30:
                tag = "연체 30일"
            elif ov == 60:
                tag = "연체 60일"
            if not tag:
                continue
            title = f"💰 미수금 {tag} — {order_no}"
            body = (f"거래처: {cust} / 미수금: {int(outstanding):,}원 / "
                    f"등급: {it['grade']} / 만기: {it['due_date_calc']}")
            link = f"/sales/orders/{it['order_id']}"
            # 우선 created_by, 폴백 영업권한자 전체
            recipients = []
            cb = c.execute(
                "SELECT created_by FROM orders WHERE id=?", (it["order_id"],)
            ).fetchone()
            if cb and cb[0]:
                recipients.append(cb[0])
            else:
                recipients.extend(sales_uids)
            for uid in recipients:
                if notify_user(uid, "SALES", title, body=body, link=link):
                    sent += 1
                else:
                    skipped += 1
    return {"sent": sent, "skipped": skipped, "items": total_items}


