@app.post("/export/item/{iid:int}/customs")
async def export_item_customs_save(req: Request, iid: int):
    """수출 통관 칸만 저장(order_items) — 판매단가/금액/라벨은 절대 건드리지 않음(별도 흐름)."""
    u = _export_guard(req)
    if not u:
        return JSONResponse({"ok": False, "error": "권한 없음"}, 403)
    form = await req.form()
    with db_session() as c:
        oicols = {r[1] for r in c.execute("PRAGMA table_info(order_items)").fetchall()}
        sets, vals = [], []
        # 텍스트형 통관 칸
        for col in ("hs_code", "origin", "box_no", "pallet_size", "description"):
            if col in oicols and form.get(col) is not None:
                sets.append(f"{col}=?")
                vals.append((form.get(col) or "").strip() or None)
        # 숫자형 통관 칸 (미전송=건너뜀 / 빈값=NULL)
        for col in ("duty_rate", "vat_rate", "invoice_unit_price_usd",
                    "invoice_amount_usd", "duty_krw", "duty_usd",
                    "final_amount_usd", "weight_kg"):
            if col not in oicols:
                continue
            raw = form.get(col)
            if raw is None:
                continue
            raw = (raw or "").strip().replace(",", "")
            if raw == "":
                sets.append(f"{col}=?"); vals.append(None)
            else:
                try:
                    sets.append(f"{col}=?"); vals.append(float(raw))
                except ValueError:
                    pass
        if not sets:
            return JSONResponse({"ok": True, "changed": 0})
        if "updated_at" in oicols:
            sets.append("updated_at=datetime('now','localtime')")
        vals.append(iid)
        c.execute(f"UPDATE order_items SET {','.join(sets)} WHERE id=?", vals)
    return JSONResponse({"ok": True, "changed": 1})


# ------------------------------------------------------------
# v5H226z463 (대표 지시·수출 2단계): 패킹리스트(PACKING LIST) — 1단계 통관 입력(order_items)에서 생성.
#   인쇄(A4 HTML)·엑셀(KNK 표준). 데이터 출처 = order_items(품명·규격·원산지·HS·수량·중량·박스·팔레트).
# ------------------------------------------------------------
def _export_pl_build(c, pid):
    """프로젝트의 수출 품목(order_items)으로 PACKING LIST 데이터 구성. (project, pl, lines) 또는 (None,None,None)."""
    prow = c.execute(
        """SELECT id, mgmt_code, name, customer_name, currency, order_date, due_date, secondary_customer
           FROM projects WHERE id=?""", (pid,)).fetchone()
    if not prow:
        return None, None, None
    p = dict(prow)
    try:
        sos = _pwf.get_project_orders(c, pid)
    except Exception:
        sos = []
    lines, so_nos, boxes = [], [], set()
    for so in sos:
        if so.get("order_no"):
            so_nos.append(so["order_no"])
        for u in (so.get("units") or []):
            _bx = (u.get("box_no") or "").strip()
            if _bx:
                boxes.add(_bx)
            lines.append({
                "part_name": u.get("unit_label") or "-",
                "spec": u.get("spec") or "",
                "origin": u.get("origin") or "",
                "hs_code": u.get("hs_code") or "",
                "material_no": u.get("material_no") or "",
                "qty": float(u.get("qty") or 0),
                "unit": u.get("unit") or "EA",
                "weight_kg": float(u.get("weight_kg") or 0),
                "box_no": _bx,
                "pallet_size": u.get("pallet_size") or "",
            })
    pl = {
        "pl_no": f"PL-{p.get('mgmt_code') or pid}",
        "buyer": p.get("customer_name") or "-",
        "order_no": " · ".join(so_nos) if so_nos else (p.get("mgmt_code") or "-"),
        "mgmt_code": p.get("mgmt_code") or "-",
        "order_date": p.get("order_date") or "",
        "due_date": p.get("due_date") or "",
        "total_qty": round(sum(l["qty"] for l in lines), 2),
        "total_weight": round(sum(l["weight_kg"] for l in lines), 2),
        "total_boxes": len(boxes) if boxes else len(lines),
        "n_lines": len(lines),
    }
    return p, pl, lines


