@app.post("/consumables/import-bulk")
async def consumables_import_bulk(request: Request, file: UploadFile = File(...)):
    """v5H226z368: KNK 표준 소모품 발주 양식(24열) 업로드 → 파싱 → 미리보기 JSON.
    품목 사진은 임시폴더(token)에 추출해 두고, 확정 때 발주별 폴더로 이동. DB 미반영(확정 전)."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    # 리뷰반영: 확장자·크기 검증(다른 import 라우트와 동일 가드)
    _fn = (file.filename or "")
    if not _fn.lower().endswith((".xlsx", ".xlsm")):
        return JSONResponse({"ok": False, "error": "엑셀(.xlsx) 파일만 업로드할 수 있습니다"}, 400)
    raw = await file.read()
    if len(raw) > 60 * 1024 * 1024:
        return JSONResponse({"ok": False, "error": "파일이 너무 큽니다 (최대 60MB)"}, 400)
    # 리뷰반영: 미확정으로 방치된 오래된(>3시간) 임시 사진폴더 정리(누수 방지)
    try:
        import time as _t
        _root = tempfile.gettempdir(); _now = _t.time()
        for _d in os.listdir(_root):
            if _d.startswith("cobulk_"):
                _p = os.path.join(_root, _d)
                try:
                    if os.path.isdir(_p) and (_now - os.path.getmtime(_p)) > 3 * 3600:
                        shutil.rmtree(_p, ignore_errors=True)
                except Exception:
                    pass
    except Exception:
        pass
    _uid = str(u.get("id") or "0")
    tmp_dir = tempfile.mkdtemp(prefix=f"cobulk_{_uid}_")   # 리뷰반영: 토큰에 사용자ID 포함(타사용자 토큰 재사용 차단)
    tmp_path = os.path.join(tmp_dir, "upload.xlsx")
    try:
        with open(tmp_path, "wb") as f:
            f.write(raw)
        res = _co.parse_co_bulk_xlsx(tmp_path, image_out_dir=tmp_dir)
    except Exception as e:
        shutil.rmtree(tmp_dir, ignore_errors=True)
        return JSONResponse({"ok": False, "error": f"파싱 실패: {str(e)[:160]}"}, 400)
    finally:
        try:
            os.remove(tmp_path)
        except Exception:
            pass
    if not res.get("ok"):
        shutil.rmtree(tmp_dir, ignore_errors=True)
    else:
        res["token"] = os.path.basename(tmp_dir)   # 확정 때 사진을 이 임시폴더에서 발주별로 이동
    return JSONResponse(res)


@app.post("/consumables/import-bulk-confirm")
async def consumables_import_bulk_confirm(request: Request):
    """v5H226z368: 미리보기 확정 → 발주별 co_create + 메타 반영 + 품목/사진 일괄 등록.
    고객사는 상호 안전매칭(정확 1건만 연결), 연결관리번호는 관리코드로 해석(못 찾으면 미연결+안내),
    품목 사진은 임시폴더(token)에서 발주 폴더로 이동. 건별 실패 표면화."""
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "invalid_json"}, 400)
    orders = body.get("orders") or []
    if not isinstance(orders, list) or not orders:
        return JSONResponse({"ok": False, "error": "no_orders"}, 400)
    # 사진 임시폴더(token) — 경로 traversal 방지(basename·패턴 검증)
    import re as _re
    _uid = str(u.get("id") or "0")
    token = (body.get("token") or "").strip()
    tmp_dir = None
    # 리뷰반영: 토큰 형식 + '본인 ID 폴더'인지 확인(타사용자 토큰 재사용 차단) + 존재 확인
    if token and _re.match(r"^cobulk_[A-Za-z0-9_]+$", token) and token.startswith(f"cobulk_{_uid}_"):
        _cand = os.path.join(tempfile.gettempdir(), token)
        if os.path.isdir(_cand):
            tmp_dir = _cand
    _safe_img = _re.compile(r"^l\d+_\d+(_t)?\.jpg$")
    created, failed, link_warnings, unmatched_customers = [], [], [], []
    images_attached = 0; images_failed = 0
    # v5H226z672 (대표 지시): 소모품 '-N' 묶음 자동발행 폐기 — consumable_orders 칸이 단일 진실.
    for o in orders:
        if o.get("_errors"):   # 차단 오류 발주는 스킵(연결성 표면화)
            failed.append({"customer": o.get("customer_name"), "order_date": o.get("order_date"),
                           "error": "; ".join(o.get("_errors") or [])})
            continue
        items_in = [it for it in (o.get("items") or []) if not it.get("_errors")]
        if not items_in:
            failed.append({"customer": o.get("customer_name"), "error": "유효 품목 없음"})
            continue
        cust_raw = (o.get("customer_name") or "").strip()
        _match = _co.match_customer_by_name(cust_raw) if cust_raw else None
        cust_name = _match["name"] if _match else cust_raw
        try:
            co_id, co_no = _co.co_create(
                customer_name=cust_name, biz_div="",     # 소모품: 관리번호 C 자동·진행사업부 미사용
                order_date=(o.get("order_date") or "").strip(),
                due_date=(o.get("due_date") or "").strip(),
                currency=(o.get("currency") or "KRW").strip().upper(),
                note=(o.get("note") or "").strip(),
                source_file="통합 일괄등록(표준양식)", created_by=u.get("id"))
        except Exception as e:
            failed.append({"customer": cust_name, "error": f"발주 생성 실패: {str(e)[:120]}"})
            continue
        # 리뷰반영: 미등록(미연결) 고객사는 확정 후에도 표면화(텍스트로만 저장됨 — 확인 유도)
        if not _match and cust_raw:
            unmatched_customers.append({"co_no": co_no, "customer": cust_raw})
        # 발주 메타 보강(고객사 연결·2차고객사·담당자·연락처·납품위치·영업담당자·거래구분)
        try:
            with db_session() as c:
                _cocols = {r[1] for r in c.execute("PRAGMA table_info(consumable_orders)").fetchall()}
                _sets, _vals = [], []

                def _put(col, val):
                    if val not in (None, "") and col in _cocols:
                        _sets.append(f"{col}=?"); _vals.append(val)

                if _match:
                    _put("customer_id", _match["id"])
                _put("secondary_customer", o.get("customer2"))
                # v5H226z730 (대표 지시): 발주(헤더) 대표 모델/장비 = '기본정보 블록'의 발주 단위 값(전체 대표 이름).
                #   옛 방식(첫 품목 라인값)은 폐기 — 모델/장비를 라인에서 제거하고 발주 단위로 일원화.
                #   사진1(엑셀 기본정보 모델명·장비명) ↔ 사진2(상세 '제품' 모델명·장비명) 매칭.
                _put("model_name", (o.get("model_name") or "").strip())
                _put("equip_name", (o.get("equip_name") or "").strip())
                _put("cc_name", o.get("cc_name")); _put("cc_phone", o.get("cc_phone"))
                _put("ship_to", o.get("ship_to")); _put("sales_name", o.get("sales_name"))
                _put("form_type", o.get("form_type"))   # v5H226z563: 엑셀 형태(제품/상품/기타) 반영
                _put("status", o.get("status"))   # v5H226z719 (대표 지시): 엑셀 상태(진행중→CONFIRMED·출하→SHIPPED·취소→CANCELLED·보류→HOLD). 빈칸이면 _put 스킵→기본 DRAFT
                if o.get("is_export") is not None and "is_export" in _cocols:
                    _sets.append("is_export=?"); _vals.append(int(o.get("is_export") or 0))
                # v5H226z490 (대표 지시): 거래명세서·세금계산서(1/2/3차) 발행일·금액 일괄등록 반영
                _put("statement_date", o.get("statement_date"))
                _put("tax_invoice_date", o.get("tax_invoice_date"))
                _put("tax_invoice_date2", o.get("tax_invoice_date2"))
                _put("tax_invoice_date3", o.get("tax_invoice_date3"))
                for _ac in ("tax_invoice_amt1", "tax_invoice_amt2", "tax_invoice_amt3"):
                    try:
                        _av = float(o.get(_ac) or 0)
                    except Exception:
                        _av = 0.0
                    if _av > 0 and _ac in _cocols:
                        _sets.append(f"{_ac}=?"); _vals.append(_av)
                if _sets:
                    _vals.append(co_id)
                    c.execute(f"UPDATE consumable_orders SET {', '.join(_sets)} WHERE id=?", _vals)
        except Exception:
            pass
        # v5H226z672 (대표 지시): 소모품 세금계산서 = consumable_orders 칸이 단일 진실(위에서 발행일·금액 기록).
        #   '-N' 묶음번호 자동발행 폐기 — 여러 건을 한 장으로 '표기'하려면 작업일정표 '묶어 발행'(라벨) 사용.
        img_dir = _co.co_image_dir(co_id)
        items_out = []
        for ln, it in enumerate(items_in, 1):
            _lpid = None
            _lm = (it.get("link_mgmt") or "").strip().upper()
            if _lm:
                try:
                    with db_session() as c:
                        _r = c.execute("SELECT id FROM projects WHERE mgmt_code=? LIMIT 1", (_lm,)).fetchone()
                    if _r:
                        _lpid = _r[0]
                    else:
                        link_warnings.append(f"{co_no} · 연결관리번호 '{_lm}' 미발견 → 미연결 등록")
                except Exception:
                    pass
            # v5H226z727 (대표 지시): 자재코드(material_no) → 등록 자재(part_id) 자동 연결(선택·못 찾으면 미연결)
            _part_id = None
            _mat = (it.get("material_no") or "").strip()
            if _mat:
                try:
                    with db_session() as c:
                        _pr = c.execute("SELECT id FROM parts WHERE UPPER(part_no)=? LIMIT 1", (_mat.upper(),)).fetchone()
                    if _pr:
                        _part_id = _pr[0]
                    else:
                        link_warnings.append(f"{co_no} · 자재코드 '{_mat}' 미발견 → 미연결 등록")
                except Exception:
                    pass
            # 품목 사진 이동(임시폴더 → 발주폴더). _imgs 는 파서가 '사진(photo) 우선'으로 정렬.
            #   첫 이미지 = 대표사진(image_path), 둘째 = 보조(image_loc_path). 표준양식(사진+사진위치)·
            #   이 파일(사진을 사진위치 칸에 붙임) 둘 다 대표 썸네일이 채워지도록 — 슬롯 2개까지.
            _chosen = []
            for im in (it.get("_imgs") or []):
                if len(_chosen) >= 2 or not tmp_dir:
                    break
                fn = im.get("full") or ""; ft = im.get("thumb") or ""
                if not (_safe_img.match(fn) and _safe_img.match(ft)):
                    continue
                try:
                    ok_move = True
                    for nm in (fn, ft):
                        src = os.path.join(tmp_dir, nm)
                        if os.path.isfile(src):
                            shutil.move(src, os.path.join(img_dir, nm))
                        else:
                            ok_move = False
                    if ok_move:
                        _chosen.append((fn, ft)); images_attached += 1
                    else:
                        images_failed += 1   # 리뷰반영: 이동 못한 사진 표면화
                except Exception:
                    images_failed += 1
            _photo = _chosen[0] if _chosen else None
            _loc = _chosen[1] if len(_chosen) > 1 else None
            items_out.append({
                "line_no": ln, "part_name": it.get("part_name"), "spec": it.get("spec"),
                # v5H226z730: 모델/장비는 발주 단위(위 consumable_orders 저장) — 라인에는 저장 안 함.
                "qty": it.get("qty"), "unit": it.get("unit"), "unit_price": it.get("unit_price"),
                "linked_project_id": _lpid, "part_id": _part_id, "note": it.get("note"),
                "image_path": (_co.co_image_url(co_id, _photo[0]) if _photo else None),
                "image_thumb_path": (_co.co_image_url(co_id, _photo[1]) if _photo else None),
                "image_loc_path": (_co.co_image_url(co_id, _loc[0]) if _loc else None),
                "image_loc_thumb_path": (_co.co_image_url(co_id, _loc[1]) if _loc else None),
            })
        try:
            _co.coi_bulk_insert(co_id, items_out)
        except Exception as e:
            failed.append({"customer": cust_name, "co_no": co_no,
                           "error": f"품목 저장 실패: {str(e)[:120]}"})
            continue
        created.append({"co_no": co_no, "customer": cust_name,
                        "order_date": o.get("order_date"), "items": len(items_out),
                        "images": sum(1 for _io in items_out if _io.get("image_path") or _io.get("image_loc_path"))})
    # v5H226z672 (대표 지시): 소모품 자동 묶음 발행 폐기 — consumable_orders 칸이 단일 진실(위에서 기록).
    #   (여러 건을 한 장으로 '표기'하려면 작업일정표 '묶어 발행' 라벨 사용.)
    ti_bundles, ti_lines_bundled, ti_singles = 0, 0, 0
    if tmp_dir:
        shutil.rmtree(tmp_dir, ignore_errors=True)   # 완료/실패 무관 임시 사진폴더 정리
    return JSONResponse({"ok": True, "created_count": len(created), "failed_count": len(failed),
                         "created": created, "failed": failed, "link_warnings": link_warnings,
                         "unmatched_customers": unmatched_customers,
                         "images_attached": images_attached, "images_failed": images_failed,
                         "ti_bundles": ti_bundles, "ti_lines_bundled": ti_lines_bundled, "ti_singles": ti_singles})


@app.post("/consumables/upload-xlsx")
async def consumables_upload_xlsx(request: Request,
                                   file: UploadFile = File(...),
                                   customer_name: str = Form(""),
                                   biz_div: str = Form(""),
                                   order_date: str = Form(""),
                                   due_date: str = Form(""),
                                   currency: str = Form("KRW"),
                                   note: str = Form("")):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    # v5H218: 진행 사업부 필수 (T/M)
    if biz_div not in ("T", "M", "L"):
        return JSONResponse({"ok": False, "error": "biz_div_required",
                              "message": "진행 사업부(검사기/자동화)를 선택해주세요"}, 400)
    co_id, co_no = _co.co_create(
        customer_name=customer_name, biz_div=biz_div, order_date=order_date, due_date=due_date,
        currency=currency, note=note, source_file=file.filename or "",
        created_by=u.get("id"),
    )
    raw = await file.read()
    tmp_dir = tempfile.mkdtemp(prefix=f"co_{co_id}_")
    tmp_path = os.path.join(tmp_dir, file.filename or "upload.xlsx")
    with open(tmp_path, "wb") as f:
        f.write(raw)
    img_dir = _co.co_image_dir(co_id)
    parsed = _co.parse_consumable_xlsx(tmp_path, image_out_dir=img_dir)
    # v5H226z287 (대표 지시): 양식 정보란(좌·우) 전체를 소모품수주에 반영. 관리번호·수주번호만 자동.
    _meta = parsed.get("meta") or {}
    _meta_ccy = _meta.get("currency")
    _meta_exp = _meta.get("is_export")
    _eff_cust = _meta.get("customer") or customer_name   # 엑셀 고객사 우선
    _match_cust_id = None
    # v5H226z294 (대표 지시): (주)/주식회사 차이 무시하고 상호로 등록 고객사 매칭 → 정식명칭으로 등록
    _cust_match = _co.match_customer_by_name(_eff_cust) if _eff_cust else None
    try:
        with db_session() as _mc:
            _cocols = {r2[1] for r2 in _mc.execute("PRAGMA table_info(consumable_orders)").fetchall()}
            _sets, _vals = [], []

            def _put(col, val):
                if val not in (None, "") and col in _cocols:
                    _sets.append(f"{col}=?"); _vals.append(val)

            # 고객사: 상호 매칭되면 등록 정식명칭+id, 아니면 엑셀명 그대로(미연결 → 보드 적색)
            if _cust_match:
                _match_cust_id = _cust_match["id"]
                _put("customer_id", _cust_match["id"])
                _put("customer_name", _cust_match["name"])
            elif _meta.get("customer"):
                _put("customer_name", _meta["customer"])
            _put("order_date", _meta.get("order_date"))
            _put("due_date", _meta.get("due_date"))
            _put("ship_to", _meta.get("ship_to"))
            _put("cc_name", _meta.get("cc_name"))
            _put("cc_phone", _meta.get("cc_phone"))
            _put("secondary_customer", _meta.get("customer2"))
            _put("model_name", _meta.get("model_name"))
            _put("equip_name", _meta.get("equip_name"))
            _put("sales_name", _meta.get("sales_name"))
            if _meta_ccy:
                _put("currency", _meta_ccy)
            if _meta_exp is not None and "is_export" in _cocols:
                _sets.append("is_export=?"); _vals.append(int(_meta_exp))
            if _sets:
                _vals.append(co_id)
                _mc.execute(f"UPDATE consumable_orders SET {', '.join(_sets)} WHERE id=?", _vals)
    except Exception:
        pass
    _eff_ccy = (_meta_ccy or currency or "KRW")
    enriched = []
    for ln in parsed["lines"]:
        part_match = _co.match_part_by_name(ln.get("part_name", ""))
        # v5H226z287: 연결관리번호(사용자 입력) 우선 → 없으면 모델 자동매칭
        proj_match = _co.match_project_by_mgmt(ln.get("link_mgmt", "")) \
            or _co.match_project_by_model(ln.get("model_use", ""), _match_cust_id)
        imgs_v = parsed["images"].get(ln["line_no"], [])
        if not isinstance(imgs_v, list):
            imgs_v = []
        ln_out = {
            **ln,
            "part_match": part_match,
            "project_match": proj_match,
            "images": [{
                "thumb_url": _co.co_image_url(co_id, im["thumb"]),
                "full_url": _co.co_image_url(co_id, im["full"]),
                "thumb_file": im["thumb"], "full_file": im["full"],
                "category": im.get("category", "photo"),   # v5H226z286: photo(사진) / loc(사진위치)
                "orig_size": im.get("orig_size", 0),
                "compressed_size": im.get("compressed", 0),
            } for im in imgs_v],
        }
        enriched.append(ln_out)
    try:
        shutil.rmtree(tmp_dir, ignore_errors=True)
    except Exception:
        pass
    return JSONResponse({
        "ok": True,
        "co_id": co_id, "co_no": co_no,
        "header_row": parsed.get("header_row"),
        "col_map": parsed.get("col_map"),
        "lines": enriched,
        "currency": _eff_ccy,                                  # v5H226z285: 양식에서 읽은 통화
        "is_export": _meta_exp,                                # 거래구분(1=수출/0=내수)
        "image_count": parsed.get("image_count", 0),
        "error": parsed.get("error"),
    })


@app.post("/consumables/{co_id:int}/import-confirmed")
async def consumables_import_confirmed(request: Request, co_id: int):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    try:
        body = await request.json()
    except Exception:
        body = {}
    items_in = body.get("items") or []
    items_out = []
    for it in items_in:
        items_out.append({
            "line_no": it.get("line_no") or 0,
            "model_use": it.get("model_use") or "",
            "equip": it.get("equip") or "",                        # v5H226z288: 장비명
            "part_name": it.get("part_name") or "",
            "spec": it.get("spec") or "",
            "qty": it.get("qty") or 0,
            "unit": it.get("unit") or "EA",
            "unit_price": it.get("unit_price") or 0,
            "part_id": it.get("part_id"),
            "linked_project_id": it.get("linked_project_id"),
            "image_path": (_co.co_image_url(co_id, it["image_full_file"])
                            if it.get("image_full_file") else None),
            "image_thumb_path": (_co.co_image_url(co_id, it["image_thumb_file"])
                                  if it.get("image_thumb_file") else None),
            # v5H226z286: 사진위치(PICTURE LOCATION) 이미지
            "image_loc_path": (_co.co_image_url(co_id, it["image_loc_full_file"])
                                if it.get("image_loc_full_file") else None),
            "image_loc_thumb_path": (_co.co_image_url(co_id, it["image_loc_thumb_file"])
                                      if it.get("image_loc_thumb_file") else None),
            "note": it.get("note") or "",
        })
    n = _co.coi_bulk_insert(co_id, items_out)
    return JSONResponse({"ok": True, "co_id": co_id, "inserted": n})


@app.get("/consumables/{co_id:int}", response_class=HTMLResponse)
async def consumables_detail(request: Request, co_id: int):
    u = get_user(request)
    if not u:
        return RedirectResponse("/login", 303)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return RedirectResponse("/home", 303)
    co = _co.co_get(co_id)
    if not co:
        return RedirectResponse("/consumables", 303)
    items = _co.coi_list(co_id)
    # v5H226z300/z301 (대표 지시): 미연결 라인에 '등록 자재 추천' + '관리번호(모델 자동매칭) 추천'
    for _it in items:
        if not _it.get("part_id"):
            _it["suggest_part"] = _co.match_part_by_name(_it.get("part_name", ""))
        if not _it.get("linked_project_id"):
            # v5H226z302 (대표 지시): 추천 = 같은 1차 고객사 + 모델명 90%↑ + 장비명 90%↑ (모두 충족)
            _it["suggest_mgmt"] = _co.suggest_mgmt_for_line(
                _it.get("model_use", ""), _it.get("equip_name", ""), co.get("customer_id"))
    # v5H226z292 (대표 지시): 관련부서 통보 — 부서 선택 모달용 팀 목록(활성 인원 있는 팀)
    _teams = []
    try:
        with db_session() as _tc:
            _teams = [dict(r) for r in _tc.execute(
                "SELECT t.id, t.name, COUNT(u.id) AS member_count "
                "FROM teams t LEFT JOIN users u ON u.team_id=t.id AND COALESCE(u.is_active,1)=1 "
                "GROUP BY t.id, t.name HAVING member_count > 0 "
                "ORDER BY t.display_order, t.id"
            ).fetchall()]
    except Exception:
        _teams = []
    _history = _co.co_history_list(co_id)   # v5H226z298: 변경 이력 탭
    # v5H226z299 (대표 지시): 1차 고객사는 등록 고객사 중에서만 선택 — 드롭다운 목록
    _customers = []
    try:
        with db_session() as _cc:
            _customers = [dict(r) for r in _cc.execute(
                "SELECT id, name FROM customers ORDER BY name").fetchall()]
    except Exception:
        _customers = []
    return ctx(request, "consumable_detail.html",
               user=u, active="consumables",
               co=co, items=items, teams=_teams, history=_history, customers=_customers,
               STATUS_LABELS=_co.CO_STATUS_LABELS,
               STATUSES=_co.CO_STATUSES)


@app.post("/consumables/{co_id:int}/items/{iid:int}/edit")
async def consumables_item_edit(request: Request, co_id: int, iid: int):
    u = get_user(request)
    if not u:
        return JSONResponse({"ok": False, "error": "auth"}, 401)
    if not (can_use_logistics(u) or can_use_sales(u)):
        return JSONResponse({"ok": False, "error": "forbidden"}, 403)
    form = await request.form()
    fields = {}
    for k in ("model_use", "equip_name", "part_name", "spec", "unit", "note"):  # v5H226z297: 장비명 편집
        if k in form:
            fields[k] = (form.get(k) or "").strip()
    for k in ("qty", "unit_price"):
        if k in form:
            try:
                fields[k] = float((form.get(k) or "0").replace(",", ""))
            except ValueError:
                fields[k] = 0
    for k in ("part_id", "linked_project_id"):
        if k in form:
            v = (form.get(k) or "").strip()
            fields[k] = int(v) if v.isdigit() else None
    _co.coi_update(iid, fields, by_id=u.get("id"), by_name=(u.get("name") or u.get("login_id") or ""))
    co = _co.co_get(co_id)
    return JSONResponse({"ok": True, "total_amount": (co or {}).get("total_amount", 0)})


